/* 平成14年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h14.committeeSessions.push(...[{"id":"h14-20021002-4","meetingId":"h14-c-settlement","date":"2002年10月2日","dateIso":"2002-10-02","committee":"決算特別委員会","time":"午前１０時０５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を115件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"嶋副委員長","kind":"質問・要望","question":"第１項理事および理事会の設置についてです。１人当たりの質問時間は答弁時間も含めて１０分、１５分、２０分のいずれかとし、会派で割り振ることとしておりますので、その時間内であれば、質問数は問いません。経過時間のお知らせにつきましては、残り時間３分前に振鈴を１回、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"}]},{"id":"topic-02","title":"以上で決算統計上の数値についての説明が終わりました。 それでは、平成１３年度品川区一般会計歳入歳出決算","agenda":"以上で決算統計上の数値についての説明が終わりました。 それでは、平成１３年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今日の決算特別委員会の一番手を引き受けします。第７款の特別区交付金、それから第９款分担金及び負担金から総務費負担金、それと１７款の諸収入から民生費委託収入、それから１８款特別区債、この辺で質問させていただきたいと思います。品川区は２４年間黒字を継続しているということで、大変すばらしい決算内容、これからも維持していただきたいと思います。お願いいたします。","respondent":"市岡企画財政課長","answer":"家計でも臨時収入を当てにしながらでしか運営できないということは非常に家計の財政が健全でないということになります。それで、先ほど決算統計のご説明を申し上げましたが、実質収支、これが黒だということを申し上げました。","voiceIndex":13,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その時点でミニ市場公募債の品川中央公園の関係ということでお話があったんですが、今までですと縁故債ですけど、それをミニ市場公募債にした場合、引き受ける側、金融機関側においても、品川区の信頼性を見ていく、それから当然買う方も縁故債ではなく、個人の方が買っていくわけですから、まさに品川区の信頼を受けられるか受けられないかという状況だと思うんですが、その辺。","respondent":"市岡企画財政課長","answer":"こういうことも含めて、若干コストはこれまでの縁故債よりはかかりますが、それはおそらく数百万円のうちのかなり低いコストで終わるのではないかというふうに見ておりまして、それよりも区民参加の一層の促進ということのほうがメリットがあるのではないか。","voiceIndex":15,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"教育にかける意識の強い地域は固定資産税が高い。ですから、教育に外れていこうと思えば、そこから引っ越してしまうという、そういう話で説明もありました。ですから、もっと皆さんが意識を持てるような形で、その辺はどうお考えいただけるかどうか、お願いいたします。","respondent":"市岡企画財政課長","answer":"政府資金の場合は償還がたしか２５年ぐらいの長期ですので、この経済状勢の中で区民公募債をやるときに、そういう長期の証券というのはちょっと発行しにくいと思いますので、今度の中央公園も５年満期一括償還ぐらいを考えておりまして。","voiceIndex":17,"id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ただ、国の責任を免れさせないで、区としてやはりそういう協力を地域の方に求めるということをぜひ考えていただきたいなと思うんですが、これは要望しておきます。私もこの予算特別委員会で質問させていただいたんですが、これからの３年間の介護保険料をどのように考えているのか、サービス供給量ともにどのようなお考えかということで、ご質問させていただきたいと思います。","respondent":"早津高齢福祉課長","answer":"ただし、最終的な詰めの作業をこのまま継続いたしまして、今月末に予定されております厚生委員会、１０月２９日だと思いますが、そちらのほうでご報告を詳細にさせていただきたい、このように考えてあります。","voiceIndex":19,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"は厚生委員会のほうで、よろしくお願いいたします。私ども、ちょっと一緒に出ておりませんでしたので、どんなお話になっているのか、それと区に対して、また議会に対しても何も話が出ていないと思うんですが、そこら辺の観点でどうなっているんでしょうか。","respondent":"西島経理課長","answer":"それから２点目ですけれども、移転の時期は当初１５年の２月を予定していたけれども、１５年中を目途に検討したいということ。それから３点目は、その間、地元と十分協議をしていきたいという説明をしたというふうに聞いてあります。","voiceIndex":21,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"引き続きやはり必要な場所だと考えています。先日の文教委員会の中で、学校教室の冷房化について予算の関係、今回は区の自主財源ですが、地方交付税になった場合の可能性という話もちょっとあったと思うんですが、その中で、もし地方交付税で入ってくる可能性、財調として入ってくる可能性がどの程度あるのか、それから、財調で入ってきたときに、財調に対して要望、国に対しての要望もどの程度しているのか。","respondent":"市岡企画財政課長","answer":"そういう中で、堅実な見通しを立てていくということが一番大事かなというふうに考えてあります。","voiceIndex":23,"id":"exchange-007"},{"speaker":"堺委員","kind":"提案","question":"賃貸工場アパートの件について、たしか今現在は空き状況がなかったかなと記憶しておるんですが、その辺のところ、今状況はどうなっているのか、その辺をちょっと教えていただきたいのと、あわせまして、今回の決算の中で、収入未済が約５８０万円計上されておりますけども、これは昨年もちょっと教えていただいたんですが、その後新しく、いわゆる収入未済の対象というんですか。","respondent":"宮地区民課長、市川産業振興課長、桑村人事課長","answer":"今現在マイク等設備をしていますので、その結果、今のところは苦情等はございませんので。ただ、現在のところ、このうち一つの企業がすべて払い込みをしていますので、現状入居企業については１カ月分の使用料の払い込みの遅れがある。そういった数字で７３％です。","voiceIndex":26,"id":"exchange-008"},{"speaker":"堺委員","kind":"質問・要望","question":"そうすると、使用料との関連にもなってくるかと思うんですけども、この件についても昨年お尋ねをさせていただいた際に、今年の９月がちょうど更新の時期だというお話だったかと思うんですけども、私その際に、ぜひこういう社会状況、経済状況ですから、ぜひ使用料等については、据え置きといいましょうか、近傍家賃の実勢を見ながらお考えいただくということでございましたので。","respondent":"宮地区民課長、市川産業振興課長、桑村人事課長","answer":"先ほど申し上げたマイク、アンプ等に引き続きまして、ビデオ等ですが、その周辺の音に対するいろいろなご意見もありますので、今のところ状況を見ながら。この工場アパートの使用料の債権管理につきましては、ご指摘のあった点に十分留意しながら今後努めてまいりたいと思います。待機寮のあり方につきましては、平成１３年度からいろいろ検討してまいりました。","voiceIndex":30,"id":"exchange-009"},{"speaker":"堺委員","kind":"確認","question":"その辺についてのちょっとお考えを確認しておきたいと思います。たしか賃貸工場アパートの裏に変電所があったんですが、今回今年の７月ごろでしょうか、あそこの変電所が撤去されましたから、今後は低周波問題というのは起きてこないんだろうなとは思うんですが、その辺、ちょっと確認の意味も含めて状況をお知らせください。それから、職員住宅の件、転用を考えざるを得ないということですよね。","respondent":"宮地区民課長、小野政策担当課長、市川産業振興課長","answer":"今おっしゃられたように、臨海部広域斎場が少し開場が早まりまして、１５年度中、１６年１月ということですが、１５年度中ということになりましたので。そういう意味で、ただいま委員ご指摘いただいたような方法も含めまして、十分この間のいろいろな状況の変化。私どもにもその入居企業からお知らせがございまして、数年前、トランスの音ですとか、振動ですとかにつきまして。","voiceIndex":34,"id":"exchange-010"},{"speaker":"堺委員","kind":"質問","question":"そこで、工場アパートの件ですが、これも事務事業評価によりますと、今回工場等の集団化、共同化事業についてＣと、こんなふうな新たな事業展開についても検討していくというふうなことになっておりますが、これは賃貸工場アパートも含めて全体的にこの件については見直していくということになるんでしょうか。その辺についてはいかがでしょうか。","respondent":"市川産業振興課長","answer":"ただ、近時になりまして、実際に入っている入居企業からも、住宅としてではなくて、何か、例えば軽作業ができる、そういった部屋として使えないものかとか、あるいは住宅は別のところに手当てをしたいとかという、これはすべてがそうだというわけじゃございませんが。","voiceIndex":38,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は歳入のところで、東京都の補助金のところで、全般にわたって影響がどういうふうになるかということを伺いたいと思います。そして、２３区の区長会として、都知事にもう一度伺う予定なんだというふうなお話だったんですけれども、改めて、いつどういう内容で要請したのか、その点をお聞かせいただきたいと思います。特に、今不況の中で、非常に大変になっております。","respondent":"日下部障害者福祉課長","answer":"廃止・縮小ということも挙がっておりますので、これにつきましては、代替の機能、これが必要ではないか、この辺についての検討も必要だということ、これが２点です。","voiceIndex":41,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今回は人件費補助をどんどん削っていくというのが一つと、もう一つは、福祉施設を廃止あるいは民間移譲と、そういう二つの方向が出ておりますけども、具体的に区内の施設で一体どういう影響が出てくるんだろうかということがもう一つ聞きたい点なんですけども、私どものところも幾つか視察に行ったりしてまいりました。ところが、利用者が非常にまだまだ多いと。ですから、施設の方も心配をしておりました。","respondent":"日下部障害者福祉課長","answer":"先ほどご答弁申し上げましたように、東京都の改革の中身というのは大きく２点あります。１点目の都立施設の関係について申し上げますと、確かに旗の台にあります景徳学園ですね、これが当初の東京都の委員会の提言の中で検討の俎上にのぼっております。","voiceIndex":43,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"全体的に、全部聞けたわけじゃないんですけども、お話を聞けたところでは、大体２，０００万円から３，０００万円、１施設当たり補助金を受けていると。今回、西大井保育園は今度新しく全部ワンフロアになりますけれども、２階建て、そういうところの加算もあるんですけど、こういうのはどういうふうな見通しになっていくのか、そこのところもあわせてお伺いしたいと思います。","respondent":"金子保育課長","answer":"委員ご指摘のとおり、仮にこの改革の提言が実施されれば、かなりの相応の影響が出るというふうには考えておりますが、私どもとしましても、既存の補助の仕方というのは、未来永劫続いていくとは考えておりませんので、東京都の改革の動向、私たちの品川区としての考え方。","voiceIndex":45,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問・要望","question":"推移を見守るというのはちょっとがっかりなんですけども。じゃあそうすると、例えば民間の保育園ですと、どういう努力が今の方向では求められると。課長のほうから見ると、民間の保育園はこういう努力が必要になってくるというのは、どういうふうに見ているのか、お考えいただきたい。","respondent":"金子保育課長","answer":"区としまして、実際に各法人に対してどのような額が入っているかというのは、私どもとしましては、直接私どもを経由していないので正確な額というのはつかめておりませんけれども、先ほど障害者福祉課長が申し上げたとおり、相応の額になっておりますので。","voiceIndex":47,"id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問・要望","question":"区長が２３区の区長会として申し入れしているわけですから、その辺、やっぱり一定どういうふうな影響なのかというのは、私はそこを踏まえての話かなというふうに思っていたんですけども、ちょっとつかんでいないということであれば、こういう申し入れをしているわけですから、やっぱり区の施設、民間でも区を経由していないにしても。","respondent":"日下部障害者福祉課長","answer":"それから景徳学園のことについてお話がありましたけれども、東京都のほうとしましては、かつてと時代が変わって、民間施設等も大分充実をしてきたということで、東京都の果たすべき役割というものをもう一度改めて再検討したいと、このようなことで東京都は主張しておりますし。","voiceIndex":49,"id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ぜひ申し入れの今の内容で強力にお願いしたいと思います。一定程度、いわゆる今の給与体系を大幅に見直さなきゃいけない、そういうことになっていくと思うんですけれども、このところでベテランの職員を配置していく、こういう意味、その中での補助金の意味ですね、このところの見解をお伺いしたいなと思うんです。","respondent":"日下部障害者福祉課長、小沼福祉事業部長","answer":"ただ、そういった点からは、一方でサービス水準を確保しつつ、より効率的な経営努力、これがどういう形で進められるのかと、なかなか難しい課題でもありますけれども、一つにはそういうことで受けとめざるを得ないと。経営努力ということで、これは当然公立、私立関係なくして、こういうご時世ですし、時代の進展、それから利用者、潜在利用者を含めて、そういう時代の流れに応じて対応していくというのは。","voiceIndex":51,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問・要望","question":"区長会のほうで、先ほどの趣旨で申し入れされたということなので、これは全力で頑張っていただきたいと思います。最後になります。ちょっと重なりますけども、やっぱり区長会として申し入れている、先ほども協議、調整をやってほしいということでありますから、やっぱり区内の実態ですね、民間の施設も含めて、そこのところをよく把握していただきたい、このことを最後にお願いして終わりにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"私は２０７ページの歳入全般と、あと特別区税、それと職員費についてお伺いしたいと思います。２０７ページの歳入の欄を見しますと、特別区税よりも財調のほうが上回っていますが、これはどのようなことをあらわしているのか、まずお尋ねします。","respondent":"市岡企画財政課長","answer":"それ以前は基本的には区税が区の歳入の第１位だです。","voiceIndex":56,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"特別区２３区で、他区と比べて品川区はどうなっているのか教えてください。","respondent":"市岡企画財政課長","answer":"これは財調のときにいろいろご説明する機会がありますが、例えば平成１４年度ですと、渋谷区は不交付区、つまり財調がゼロな区です。それから、総じて都心区は財調の割合が非常に低くて、コンマ幾つというふうな割合です。","voiceIndex":58,"id":"exchange-020"},{"speaker":"藤原委員","kind":"意見","question":"今ご答弁いただいた中で、それぞれ区として何でこのような差が出るのかというのがまず１点と、よく財調のお話をしていただくときに、品川区は標準区、真ん中ですというご説明が出るんですけれども、真ん中というあらわし方がいいのか何なのか、真ん中だけでいつも終わっちゃうと思うので、その辺のご説明をしていただけますか。","respondent":"市岡企画財政課長","answer":"この偏在というのは、例えばよくご説明するんですが、一番区税の１人当たりの納税額の多い区と、一番少ない区と、これも区名を申し上げませんが、５倍ぐらいの差があります。つまり、逆に言えば、５分の１の１人当たりの税収しかない区があります。","voiceIndex":60,"id":"exchange-021"},{"speaker":"藤原委員","kind":"質問・要望","question":"区の収入の中で、ほんとうに財調の占める割合というのは一番多いわけですが、その点について、区としてどのように注意していく点があったら教えていただきたいのと、あと、収入の中で、一番だということを区民にどのように示していくのか、この２点についてお伺いいたします。","respondent":"市岡企画財政課長","answer":"区民の皆様には、財調という制度はなかなかわかりにくいものですから、ただ、歳入が一番だということではなくて、これからいろいろな機会に財政状況の公表もありますので、その機会にわかりやすく財調というものの制度をご説明していく、こういう姿勢が大事だと思ってあります。","voiceIndex":62,"id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"次に特別区税についてお伺いしますが、ほんとうに今景気が悪い中で、特別区税が増えているんですけれども、たしか２年連続で増えていると思うんですが、これは景気が悪いにもかかわらず、特別区税が伸びているのはどんな背景があるのかお尋ねします。","respondent":"松崎税務課長","answer":"ただ、その中でも、所得税をベースにして計算する特別区民税は多少の影響を受けます。したがいまして、平成６年以降、９年を除いて恒久的減税を実施してまいりました。","voiceIndex":64,"id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"今ご答弁の中で出ましたけど、減税をしているにもかかわらず税収が伸びたということですよね。再開発をして、ファミリー層が増えたということが税収に反映されているんだなと思っておるんですが、その増えたファミリー層、税金を払ってくださっているファミリー層に区民サービスという点で、どのようなことをしていくのか、お答えがあったらいただきたいんですけれども。","respondent":"松崎税務課長","answer":"ただ、施策全体の中で再分配をするというのは今でもやっておりますので、それは当然のことだというふうに理解しております。","voiceIndex":66,"id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"この間出された「ふれあい」の中で、平成９年度から平成１２年度まで４年連続で２３区中１位の成績で、区長が皆さんの努力に感謝しますと載っているんですけれども、まず一番初めにあるのは、払ってくださる区民の皆様がいるのが一番感謝だと思います。ですけれども、こういうふうに２３区中１位の成績になる何か秘訣みたいなものがあったら教えていただきたい。","respondent":"松崎税務課長","answer":"特に秘訣はございません。やはり、委員がおっしゃられたように、税金に対する区民の認識、これが高いというふうに理解しています。私どもとしては、お支払いいただいて、ほんとうにありがたいというふうに感謝の気持ち、これを前面に出すように職員にはお願いしています。","voiceIndex":68,"id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"職員費についてお伺いします。私は、その中の質問の中で、日本の場合、品川区の場合の説明をさせていただきまして、途中採用について伺ったら、市は途中採用は当たり前だということをお話ししておったんですけれども、これから品川区が中途採用するというのは厳しいかもしれないんですけれども、そういうような流れについては何かお考えがあるのか教えてください。","respondent":"桑村人事課長","answer":"その意味で、今急に私どものほうで必要とするという事態にはなってございませんけれども、十分これから検討していく課題だろうというふうに思ってあります。","voiceIndex":70,"id":"exchange-026"},{"speaker":"高星委員","kind":"質問・要望","question":"大変な思いをしながら５億円余なんですね。３点目の施設使用料の関係なんですが、これは非常に私も質問するときに、どういう形で質問しようかなと思ったんですが、一つには、これまでもこのような委員会の中で、ほかの方からも指摘があったかもわからないけれども、品川区の保養施設、区民施設、こういったものがほかの自治体との相互乗り入れの関係、この辺が必要だなというふうにつくづく考える次第です。","respondent":"松崎税務課長、宮地区民課長、長田地域活動課長","answer":"ただ、ワンルームマンションについては、いろいろな使用形態がありますので、十分私どものほうでは把握できないというのが現状です。相互乗り入れということで、保養所の例ですけれども、例えば、伊東では品川荘の隣に目黒区の伊東荘があるということで、今例に引き出されたところですが。歩行喫煙の問題ですとか、ポイ捨てに関するご質問ですけれども、千代田区では、昨日１０月１日から罰則を適用する条例が施行されたのは報道等のとおりです。","voiceIndex":74,"id":"exchange-027"},{"speaker":"高星委員","kind":"質問・要望","question":"だからその意味で、マナーをどうのこうのということももちろんこれは大切なことなんですけれども、それは区民の方からいろんな形の税金をいただくわけですから、その中できちんともう少し大事に大事に考えて、大事に考えていないと言っているわけでもないわけですけれども、もう少し、例えば端的にもう一度お聞きしますけれども、今後品川区の特別区たばこ税について、品川区は前向きに増やしていくのか。","respondent":"松崎税務課長、宮地区民課長、浜脇住環境整備課長、小野政策担当課長","answer":"最初の特別区たばこ税ですが、委員ご指摘のように、費用対効果の面からいいますと。ですから、そういうリンクのところから他自治体のいろんな施設を紹介するということは技術上は可能かと思いますので。先ほどのワンルームマンションにお住まいの方の住民登録の件ですが、私ども住環境整備課といたしましては。ワンルームマンションの問題につきましては、さまざまな地域の中での問題ということが今まで指摘されているわけですけれども、都市型のいろんな居住。","voiceIndex":78,"id":"exchange-028"},{"speaker":"高星委員","kind":"質問・要望","question":"新しく議員になられた方と希望者くらいの方で見に行ったというふうに思うんだけれども、私は区民の代表として出てきている議員が現況、区の施設がどういうふうになっているか、現況をよく区民にアピールする、周知する意味合いでも行くべきだというふうに思っているんですが、これはあまり軽々に言うとまた議会運営委員会の関係とかいろいろあるんだろうというふうに思いますけれども。","respondent":"福田区議会事務局長","answer":"経過をかいつまんでご説明します。平成７年までは委員おっしゃるように全議員を対象とした各保養施設につきまして、改正期ごとにご施設をいただいておった、こういう時代が長く続いておりました。","voiceIndex":83,"id":"exchange-029"},{"speaker":"高星委員","kind":"質問・要望","question":"ちょっと私のほう、強引に聞いちゃったような感じもするんですけど、私は議員の使命、議員というのは変な話ですけど、私はできれば議会事務局と各方面と協議を進めていただく中で、もう一度予算とか何かのところを考えていただきたいな、これは議会のほうともひとつよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-030"},{"speaker":"本多委員","kind":"質問・要望","question":"決算で２７回ということで、その見直しをする斎場のあり方ということで、見直しの過程について、その辺の考え方を改めてお聞かせいただきたいと思います。","respondent":"小野政策担当課長、宮地区民課長","answer":"こちらにつきましては、個々の事例の中でほんとうにこのＰＦＩの中で効率的に一番いいサービスが提供できるかどうか、こういうことを勘案しながら、個々のケースで検討してまいりたいというふうに考えております。平塚橋会館葬儀の利用ですが、平成１２年度は１７件、平成１３年度は２７件ということで、平成１３年度の利用のための予算を見積もるときに、平成１２年度のときに前半でかなり葬儀の利用が、かなりと申しましても十三。","voiceIndex":87,"id":"exchange-031"},{"speaker":"本多委員","kind":"質問・要望","question":"これはまだ法が整備されて３年ですから、これからのほんとうに課題だと思うんですが、品川区でも、そういった部分のとらえ方というか、当てはまるようなものがどのようなものが今後可能、不可能というんではなくて、どういった場合のケースにかかわってくるのか、その辺を教えていただきたいと思います。","respondent":"市岡企画財政課長、宮地区民課長","answer":"不交付団体である区にはそのまま適用するということがなかなか困難なので、これから制度の充実を見ながら、いろんなことを検討していきたい、こういうことです。平塚橋会館を葬儀ができるようにするという形で、この間、平成１０年にオープンする中で、形として骨葬という形になってきたわけですが、やはり。","voiceIndex":90,"id":"exchange-032"},{"speaker":"中島委員","kind":"質問","question":"私は１０款の使用料及び手数料のところで、５９ページの品川健康センター使用料、そして６１ページの区民住宅使用料に関連してお伺いしたいと思います。それと、主にホールのほうなんですが、どのような目的で利用されていることが多いのでしょうか、最初にこのことを質問いたします。","respondent":"田中健康課長","answer":"ホールは、多くは、あそこはダンスができる状況でございまして、かなり人気がある状況で、９カ月前のときにも申し込みが殺到しまして、抽選によって行っているという流れでございまして、その点では利用率は高いほうかなというふうに考えてあります。","voiceIndex":94,"id":"exchange-033"},{"speaker":"中島委員","kind":"質問","question":"ここがフロアが張られているということで、ダンスをされる方にとっては非常にいいフロアであるということで、好評を博しているなということは私も感じております。ところが、やはり体を動かすホールにしては、非常に空調の問題があるのではないかと思うんですが、これは利用者の方から何か聞いておられるでしょうか。","respondent":"田中健康課長","answer":"その当時もすぐ調べましたんですが、なかなかあそこは全館管理というような空調システムでございまして、いろいろ調整が難しい、それからあそこのところは炭酸ガスが、たくさんの人がいらっしゃるということで、排気するための設備という形がございまして、それと空調の段取りが。","voiceIndex":96,"id":"exchange-034"},{"speaker":"中島委員","kind":"質問・要望","question":"やはり、使用料を取って、あそこのホールを使っていただいているわけですので、改善するためには費用もかかると思うんですが、区民の方たちの要望をぜひ受けとめて改善をしていただきたいと、これは要望しておきます。そうした背景のもとでお伺いしたいのですが、たしか一昨年完成したと思われますファミーユ南大井ですが、この区民住宅の設計というのはいつごろからされたんでしょうか。","respondent":"片田施設担当課長","answer":"南大井の複合施設につきましては、ファミーユ南大井、ならびに老人保健施設が入った建物として、平成８年度に一応設計しています。","voiceIndex":98,"id":"exchange-035"},{"speaker":"中島委員","kind":"質問","question":"平成８年度に設計が終わったということなんでしょうか。","respondent":"片田施設担当課長","answer":"設計を平成８年度に一応完了しています。","voiceIndex":100,"id":"exchange-036"},{"speaker":"中島委員","kind":"質問","question":"そうしますと、これは完成したのは一昨年でよろしいんでしょうか。その辺をちょっと。","respondent":"片田施設担当課長","answer":"建設につきましては、平成９年から行いまして、平成１２年の２月に一応オープンしています。","voiceIndex":102,"id":"exchange-037"},{"speaker":"中島委員","kind":"質問","question":"平成１２年に完成したということなんですが、この１年前、平成１１年に洪水がありました。この地域というのが、洪水、床上浸水とか、そういった危険性のある地域であるということは認識されていなかったんでしょうか。","respondent":"片田施設担当課長","answer":"その中では、設計事務所側として、過去平成元年ぐらいまでにさかのぼって調査したところ、若干２回ほどこの地域の南大井周辺で被害があったという状況は把握していますけれども、そういう中で、今回設計しているということで聞いております。","voiceIndex":104,"id":"exchange-038"},{"speaker":"中島委員","kind":"質問","question":"この間、８月４日の洪水になったときなんですが、行って驚いたのは１階のところがちょっと道路、西側の道路ですか、その面は掘り下げた設計になって、半地下のようなところに１階の部屋が６世帯置かれているわけなんですが、近くのマンションもよく雨が降るとトイレが使えなくなるほど非常に下水の状況がよくないということを聞いておりましたが。","respondent":"片田施設担当課長","answer":"ただ、雨水の流水抑制ということで、施設のほうについては貯留槽を設置したり、配管の能力等々についても９０mmぐらいは対応できると、施設本体としてはそういう対応ができるということで設計しています。","voiceIndex":106,"id":"exchange-039"},{"speaker":"中島委員","kind":"質問","question":"なかなか抜けなくて、地域の方たちが総出で大きなポンプが使えなくて、小さなポンプで出していたわけなんですが、つい最近、またあのところへ私行ってみましたら、土のうが、せっかく新しい建物なのに、あっちこっちに土のうが散乱していて、そしてホースがいっぱいつながれていたんですが、あれはどういうことなんでしょうか。","respondent":"片田施設担当課長","answer":"ただ、昨日雨がございました。それ以前にも台風１３号等が経過しています。そんな中で、応急対応といいますか、今後そういうことがないようにポンプ等を設置して、万が一の部分に現時点では備えようということでのポンプ等の設置をしている状況です。","voiceIndex":108,"id":"exchange-040"},{"speaker":"中島委員","kind":"質問・要望","question":"具体的なことをちょっとお伺いしますが、では、あそこの１階の方たちは、先ほどちょっと区民住宅に入る方たちの生活、それはゆとりのある方もいらっしゃると思います、さまざまだと思います。しかし、生活の中で大きな住宅の費用というのがウエートを占めている。そういう中で、一生懸命働きながらあそこの住宅を求めてこられた方たちなんですが、今回の床上浸水に対して、特別何か配慮はされたのでしょうか。","respondent":"田村住宅課長","answer":"一部壁のほうも浸水したということで、やはりなるだけ短期間に効率的に進めるためには一定の期間仮住居が必要だということで、既存の区民住宅で空き家補修を終わっているところを活用しまして、そちらのほうに引っ越し。","voiceIndex":110,"id":"exchange-041"},{"speaker":"中島委員","kind":"質問","question":"それなりの対応はされているんだと思いますが、まだまだちょっとどうかな、まだこれから先もいつも不安を抱えて住んでいらっしゃるわけですから、それでも家賃のほうは同じ家賃で住んでいらっしゃるのでしょうか。","respondent":"田村住宅課長","answer":"ただ、それと、そちらに振りかえたわけですから、既存の区民住宅の使用料については通常どおりいただいているという状況です。","voiceIndex":112,"id":"exchange-042"},{"speaker":"中島委員","kind":"質問・要望","question":"やはり、あの地域がそれだけお水が出るということがわかっていて、しかも下げて建てているということは、このこと自体が問題だと思いますし、今後そういうことは絶対に住宅の供給に対してはあってはならないことだと教訓にしていただきたいとともに、やはり、ただ天災で済ますのではなくて、しっかり対処していっていただきたい、そのようなご配慮をお願いしたいと思います。","respondent":"田村住宅課長","answer":"やはり、今回の災害に当たって被害を受けられた方については、誠意を持った対応を心がけていきたいと、そのように考えております。","voiceIndex":114,"id":"exchange-043"},{"speaker":"中島委員","kind":"質問・要望","question":"私があそこに行って感じたことは、あそこに人を住まわせること自体が問題だなと思いました。そういった意味では、もう住んでしまっているわけですから、今後しっかりとした対策をとって、二度と被害を受けないようにそのように配慮をお願いしたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"年金、恩給等の支給ですとか、児童扶養手当の支給、不動産鑑定士等の登録等々においての、これら住民票の写しが、本人確認のための写しが必要なくなったということなんですが、一方、今申し上げましたように、平成１４年度の予算上は、例年と同じぐらいの２５万５，０００件をベースに予算措置がされているわけですが。","respondent":"冨田戸籍住民課長","answer":"住基ネットで国への情報提供によりまして、住民票の写しが省略できるようにはなりました。ただし、それを実施するには提供を受ける側の体制が必要です。国等でありますと、事務的な部分ですので、規則改正が必要です。","voiceIndex":120,"id":"exchange-045"},{"speaker":"田中委員","kind":"質問・要望","question":"そうすると、当初の導入効果というんでしょうか、提供側の体制が整うまでの間の状況ではありますが、いわゆる導入効果、また、一般の住民の方々がこれを活用する件数が少ないというような認識なんでしょうか。ちょっとその辺、私も理解が間違っているかもしれないんですが、改めてお聞かせいただきたいと思います。","respondent":"冨田戸籍住民課長","answer":"国等に対して資格付与、あるいは給付の関係の事務について住民票の省略をというのが一つのねらい目です。ただいま申し上げましたように、国等の体制の整備ができるまでは従来どおり住民票の写しの提出という形になろうかと思います。","voiceIndex":122,"id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひこの導入効果、さまざまな部分で今後出てこなくては、これだけの経費をかけてシステムを導入する意味がないと思いますので、ぜひ国全体の体制次第だと思いますが、早急にその効果があらわれるような促進に向けてご尽力いただきたいと思います。","respondent":"冨田戸籍住民課長","answer":"ただ、これは住民票の写しの省略の部分だけですので、今回の住民基本台帳ネットワークシステムにつきましては、そのほかのねらい目もあるわけですので、それは今後のいろいろな施策の中でそれらとあわせた形である程度の削減は見込めるかなというふうに考えております。","voiceIndex":124,"id":"exchange-047"},{"speaker":"田中委員","kind":"質問・要望","question":"三多摩地区だと大半が２００円で、一部府中市だとか日野市、西東京市というのは１５０円という金額設定で、品川区の半分の手数料で住民票交付がなされているわけですが、来年の８月からはいわゆる広域交付ということで、どこの自治体からも住民票を得ることができるという、そういう状況になってまいりますが、その辺も踏まえて、まずは手数料の考え方というんでしょうか。","respondent":"冨田戸籍住民課長","answer":"住基ネット絡みで広域交付手数料あるいは住民基本台帳カードなど、交付手数料の改正は一応予定はしております。積算についてはこれからという段階です。幾らになるかということについては今出ている数字はごさいません。","voiceIndex":126,"id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"一方、地域センターの役割の評価としてはＢとなっておりまして、これはすべてが住民票関連だけではないと思いますが、窓口行政事務に関しては今後再検討するというような形で書かれておりますが、いわゆる出先機関といいますか、広域交付が始まるということを念頭に、これらの大井町サービスコーナー、あるいは地域センターの活用頻度というのが今までとは違う状況になってくるんではないかなと思うんですが。","respondent":"冨田戸籍住民課長","answer":"届出関係、住民異動届に関しましては、地域センターのうちの一部、６カ所と住民票係だけです。これらの関係を含めまして、広域交付あるいは住民基本台帳カード、それから、特例転出の手続、これをどういうところで扱うかにつきましては、今後十分検討していきたいと考えています。","voiceIndex":128,"id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"例えば、郵便局もワンストップサービスを展開するということで、郵便局でも今後は住民票などがとれるとか、コンビニエンスストアでもどうかとか、さまざまな検討がなされていく中で、基本は品川区の施設でそれらが対応していけるものは対応するというのがまず一つの考え方だろうと思うんですが、ちょっと漠然としておりますが、将来の、今後の出先機関等々の位置づけというんでしょうか。","respondent":"小野政策担当課長","answer":"地域での開発の状況もありますし、今後、地域のサービスのあり方につきましては、さまざまなそういう状況を踏まえまして、十分に検討してまいりたいというふうに考えております。","voiceIndex":130,"id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"そんな中で、１点だけセキュリティーに関してのことで改めて別の機会に質問するつもりなんですが、１点だけお伺いしたいんですが、今住民票の記載事項の中に、大きく１６項目あるうちの、今回の住基ネットで対応しているデータというのは５項目、名前、性別、生年月日、住所、あと住民票コードとその他の移り変わりの部分の。","respondent":"冨田戸籍住民課長","answer":"それ以外の住民票の事項につきましては、従来から十分セキュリティーについては要綱も定めておりますし、適正に管理をしてきているところです。","voiceIndex":132,"id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"終わろうと思っていたんですが、それはすべての方を性善説に例えて考えたらば、こういう規定があるからということかもしれません、安全性が担保されているのかもしれませんが、今後は住民コードをもとに、さまざまなデータベースを構築できる、その構築する一つが確かにネットワークに載っているデータではありますが、そこに追加するデータというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"２点お尋ねしたいと思います。この点についての見解を伺いたいと思います。これでサービス水準が低下していないと言えるんでしょうか。したがって、こういう状況について、私は少なくとも、どこに行けば、どういう設備が借りられるのか、そこを明らかにさせて、区民の要求にきちんとこたえて、４回も電話しなくても済むようにしていただきたい、こう思うんですが、これについていかがでしょうか。","respondent":"志村品川図書館長、上川内生涯学習課長、片田施設担当課長","answer":"ですので、さらに私どもでは、これをはじめとした児童サービスの拡充にボランティアは欠かせないと、こういう認識でこれからも続けてまいりたいと。すべてのニーズにこたえるというのはちょっと今の時点では不可能とは思いますが、どこにあるか、それで、どういうふうなところにあるか。ただ、この施設、当該施設をつくる建設予定地について、直接被害があったという話は聞いてございませんで。","voiceIndex":136,"id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、きちんとそこは対応を早急にしていただきたいということを強くお願いしたいと思うんですが。改めてちょっとここで伺いたいのは、あそこのファミーユ南大井だけじゃなくて、高齢者施設のほうも含めて、敷地は全体の土地の広さですけども、建物そのものの平米数がどのくらいあるのか、ちょっとそこがこの間いただいた資料では全然わからないので、そこをちょっと教えていただきたいと思います。","respondent":"志村品川図書館長、片田施設担当課長","answer":"自然観察教室、それからお楽しみ会等、私どものほうでこれまでも実施してございました。平成１３年度につきましても、自然観察教室各館で１回行ってあります。ただ、今回のお話の中で、私どものほうとしても、早々に緊急な対応をすることについては、委員と同じ気持ちを持ってありますので、早々に検討した中で方向性を出して区民の方にお示ししたいと、そのように考えてあります。","voiceIndex":140,"id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"ファミーユ南大井のほうは昨日の台風に際して、私も心配なので、夜２回ほど地域を回ってみました。ところが、最近は事前予約をしてくれと。今説明を求めたら、事前の準備が必要だからというふうなお話で、きちんとした、いつだれが行ったって対応できるような、先生がついているわけですしね、保育園の職員が。ですから、そういうことというのは理由にならないというふうに私は思うわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-055"},{"speaker":"高木委員","kind":"質問","question":"１点お尋ねを申し上げます。区政の基本は人口であり、税収ですが、先ほどお伺いしますと、１月１日の住民登録でもって課税するというお話ですが、申し上げるに及ばないわけですが、しかしながら、先ほど高星委員も質問いたしましたけれども、住民登録をされていない方がおられる。品川区は、住民登録と国勢調査の差はどのぐらいあるのか、ちょっとお尋ねをいたします。","respondent":"宮地区民課長","answer":"当然のことながら、住民基本台帳による登録と国勢調査では差がございまして、国勢調査のほうが、住民基本台帳の数字を上回っているところです。大体８，０００人から９，０００人の間という形で上回っているところです。","voiceIndex":145,"id":"exchange-056"},{"speaker":"高木委員","kind":"質問","question":"私は一度びっくりしたのは、何かもっと多かったような気がするんですが、世田谷区なんかは５万人ぐらい差があるとかと一時ちらちらと調べるほどじゃないんですが、聞いたことがあったんですが、品川区ももう少し多いんではないかと思うんですが、それはあまり数字の正確さを申し上げるわけじゃないんですが、問題は登録していない人は課税しない、だけども、先ほどのみなし課税とか。","respondent":"松崎税務課長、小野政策担当課長","answer":"老齢者ですとか、障害者の方ですとか、一定の収入のない方は納めなくてもいいということになります。したがいまして、居住しているということと、納税をしているということは、必ずしも一致しないという面があります。そういう意味では、地域でのそういう問題もコミュニティとして解決を図りながら新たな活力につなげるような、そういうふうな方向の問題を模索していかなければいけないかなというふうに考えております。","voiceIndex":147,"id":"exchange-057"},{"speaker":"高木委員","kind":"質問","question":"これ以上、私は掘り下げて聞けないわけですが、今の政策担当課長のお話をもう少しじっくりお聞きしたいと思いますが、これはまちの様子、全体的に、そして生活のスタイル、これが近隣の穏やかさをどうなるかと、行政との絡みは決定的なものはそうないわけでありますけれども、私はかねてからおまえの言い分があるじゃないかと、ワンルームマンションは結婚に促進されないということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-058"},{"speaker":"石田委員","kind":"質問・要望","question":"私からは８７ページ、放置自転車等保管料、それから１５８ページ、職員費に関連をして伺いたいと思います。放置自転車等の保管料、保管料というか、放置自転車についてなんですが、歳入では２，６７４万３，０００円とあります。撤去に対する人件費等いろいろかかって、実質幾ら一般財源からマイナスになっているかという数字をまず教えていただきたいのが１点。","respondent":"奈良交通安全担当課長","answer":"ご質問にお答えをいたします。１点目の自転車保管料の関係ですけれども、保管料につきましては、当初の見込みは約２，３００万円を見込んでおりましたけれども、歳入のほうは２，６７０万円ということで、一般財源からのマイナスは約１，６００万円になっております。","voiceIndex":152,"id":"exchange-059"},{"speaker":"石田委員","kind":"質問","question":"質問の仕方が悪かったんで、じゃあ簡単に言います。その収入と支出があって、幾らマイナスだったのかというのを、一般財源を投入して幾ら実質お金がかかって出ているのかというのと、あと所有者の方にはがきを発送していると思います、わかった方には。これは何件ぐらいあるか、この２点だけ教えてください。","respondent":"奈良交通安全担当課長","answer":"歳入と歳出の関係で、一般財源からのマイナスは約１，６００万円。はがきの枚数につきましては、約９，０００件出しております。そのうち、はがきを出したうちでとりに来た方は約３，３００件ほどです。","voiceIndex":154,"id":"exchange-060"},{"speaker":"石田委員","kind":"質問","question":"とりに来る人もいるか、自分の自転車がどれだとはがきも行かないし、自分でとられちゃったなと思えば来る方もいるでしょうが、返還が１万１，０００台、ここであるということは、２，０００人ぐらいの方は、はがきもなくて連絡もないけど、自転車がとられていったということになるわけですから、あるわけですが、ここの登録をまずしてもらうというのは、どこが主になってやっているのか、警察なのか区なのか。","respondent":"奈良交通安全担当課長、中谷まちづくり事業部長","answer":"１点目の自転車の防犯登録の関係ですけども、これはいわゆる改正自転車法にうたわれておりまして、これはいわゆる防犯登録の義務化を図られておりますけども、そういったいわゆる防犯登録をきちんとやるのは。これは都道府県等につきましても、駐輪場等の設置についての協力義務、設置の義務もありますので、そういう点で協力しているわけです。","voiceIndex":156,"id":"exchange-061"},{"speaker":"石田委員","kind":"質問・要望","question":"次に行きたいので、あまり時間をとりたくないんですが、今のお話の中で、協力体制をほんとうにとっていただけているのかなと思います。ということは、それに協力をしていくためには何が必要か。放置自転車の撤去を言っているわけですよ。第６条だけでしばられちゃっているかもしれないんだけれども、そこを聞きたくて質問しているわけで、そこら辺の点をもう一度答弁いただきたい。","respondent":"奈良交通安全担当課長","answer":"今委員のほうからご指摘されました法第５条の６項の件なんですけれども、これにつきましては、いわゆる警察の法令の規定に基づいて自転車等の放置防止に努めなさいという条文になっておりますけども、いわゆる改正自転車法の中には。","voiceIndex":159,"id":"exchange-062"},{"speaker":"石田委員","kind":"質問・要望","question":"職員費にいきたいと思います。５５歳、５７歳、５８歳、会社をやめろということではありません。５５歳なら５５歳で役職を１回やめるということを考えて、その後の５年間はまたいろいろなところで活躍をしていただくわけですが、そういうところの研究とか、そういう情報とかをつかんで、こういうものがどういうふうなデメリット、メリットがあったというような研究をされたことが今まであるのかどうか。","respondent":"桑村人事課長","answer":"今、民間企業のお話がありましたけれども、今民間企業で行われているのは、いわゆる例えば役付で５５歳になると子会社に出向するとか、この間のリストラ等に入りますと、早期退職制度を入れまして、例えば松下電器あたりですと。","voiceIndex":161,"id":"exchange-063"},{"speaker":"石田委員","kind":"意見","question":"５５歳で１回役職を部長、課長クラス、１回やめます。それで、やる気のある方はそこで１年契約でもう一度取締役会に自分がレポートを出す。銀行でも今度信用金庫でも取り入れると言っていましたが、そういう発想の勉強というのを、どういう形にしろ、そういうものを設定するということの研究はしていかないといけないのではないのかなと思うんだけど、その考え方を。","respondent":"高橋区長","answer":"今のお考え、大変結構だと思います。ただ、問題になりますのは、今現在人事委員会制度がございまして、その制度をやめなければ、この問題は適用できません。","voiceIndex":163,"id":"exchange-064"},{"speaker":"石田委員","kind":"質問","question":"これは私というよりも、自民党、我々の会派からは常によく人事委員会の話は出まして、品川区は独自で抜けちゃえ、抜けちゃえという話を区長にもよく言っておりまして、もしおっしゃったような考え方が、人事委員会を抜けるということであれば、どんどん言っていただいて、早く抜けていただいて、検討に入っていただければと考えていますが、そこら辺の人事委員会の感じですね、抜けられるか。","respondent":"高橋区長","answer":"率直に申し上げますと、抜けられません。というのは、２３区で合同で設けたんだから、品川区だけ抜けるのは２２区の合意が必要、同意が必要だというのが向こうの主張です。うちだけ抜けることはできるじゃないか。","voiceIndex":165,"id":"exchange-065"},{"speaker":"石田委員","kind":"質問・要望","question":"そういう中で、どうしても行政は遅い遅いとよく言われるのが、こういうところじゃないのかなといつも思っておりますので、それの足かせが人事委員会とかということでありましたら、そういうところは早く外していただきたいなと、これはお願いをしておきます。それから、先ほど行った件は、必ず土木費でもう一回やりますので、ちょっと見解を調べていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-066"},{"speaker":"山路委員","kind":"質問・要望","question":"私のほうからは、６８ページ、国庫補助金、土木費補助に関連した内容の質問、次に、１０款使用料および手数料の中から、５８ページ、区民斎場使用料に関連して、７４ページ、福祉施策包括補助金の活用について、８３ページ、寄附金について、８６ページ、雑入の広告料収入について、お伺いいたします。","respondent":"早津高齢福祉課長","answer":"歴史的に見ますと、バリアフリーのほうが早い概念というふうに言われている中で、ユニバーサルデザインという考え方のほうが出てきた。","voiceIndex":170,"id":"exchange-067"},{"speaker":"山路委員","kind":"質問・要望","question":"今、福祉の部門からお話があったんですけど、できたら、土木の部門からもお話をいただきたいんですね。","respondent":"岩田管理工事課長","answer":"今、高齢福祉課長がご説明させていただきましたけれども、私どもでやっているのでは、例えばトイレ、公衆トイレ等が従来は身障者トイレという表現を使っておりました。","voiceIndex":172,"id":"exchange-068"},{"speaker":"山路委員","kind":"質問","question":"その辺についての健常者に対する障害者の方のバリアを除く、あるいは新しいものに対しては、今だれでも使用できるといいますか、そういう形ですけど、この辺の検討というのは事業執行に当たって、どういうふうにやられているかお伺いいたします。","respondent":"岩田管理工事課長","answer":"事業執行上、特に土木関係では道路とか公園の、いわゆるバリアフリーについて、これまでもバリアフリー事業という表現は使っておりますけれども、例えば同じ障害を持っている方、目の不自由な方とあるいは車いすを利用する方にとっての。","voiceIndex":174,"id":"exchange-069"},{"speaker":"山路委員","kind":"質問・要望","question":"わかりました。そういう観点から事業執行のときにはいろいろ縦分けて取り組んでいただきたいことを要望しておきます。次に、雑入の広告料収入についてお伺いいたします。成果報告書を見ますと、平成１３年度３４２万７，７５０円収入があったと計上してありますけど、内容としては、どのような広告収入があったのかお伺いいたします。","respondent":"山田広報広聴課長","answer":"広告料の収入の内訳についてご説明します。広報「しながわ」の広告料というのが３２９万５，０００円、それと品川ガイドのほうの広告料ということで、１３万２，７５０円、全体の件数といたしますと５６件ということで、広報紙はご案内のとおり毎月１回掲載をしています。","voiceIndex":176,"id":"exchange-070"},{"speaker":"山路委員","kind":"提案","question":"企業広告というのは、品川区も徐々に増えてきているのかなと思いますけど、ここで提案を一つさせていただきたいんですけど、バーナー広告、インターネット、広告入りで収益をということで、今各自治体でも徐々に増えてきつつありますけど、その辺のお考えについてはどういうふうに考えていらっしゃるかお伺いいたします。","respondent":"山田広報広聴課長","answer":"私のほうも、できましたら、来年度その計上ができるかどうか、区内の企業者または教育関係者と広告にふさわしい団体等含めて、いわゆる検討に入ってまいりたいというふうには考えてあります。","voiceIndex":178,"id":"exchange-071"},{"speaker":"山路委員","kind":"質問・要望","question":"次にまいりまして、区民斎場使用料について、なぎさ会館年４５０回、２，９２５万円を今回計上されおりますけど、超高齢化社会に入りまして、また平塚橋会館もありますし、平成１５年度には臨海部の斎場も完成するですけど、この数年の実態はどのような推移を経てきたか、その辺について、ちょっとお伺いをいたします。","respondent":"宮地区民課長","answer":"平成１１年度に４３４件、平成１２年度が若干落ちまして３９５件、平成１３年度が４５０件といった推移です。","voiceIndex":180,"id":"exchange-072"},{"speaker":"山路委員","kind":"質問・要望","question":"現在のところ、大分安定してきているのかなという感じもしますけど、ところで、利用者による意見とか、要望が多々あると思うんですが、どういう形で伺っていらっしゃるのか、また、特に要望の多いことがあったら、お聞かせいただきたいと思います。","respondent":"宮地区民課長","answer":"その中ですのは、例えば入り口の受付案内のところの照明がちょっと暗いのではないかとかというのも中にはございました。通り沿いの案内板、それから入り口部分、道路から入る部分で、ちょっと急なスロープがあるといったところは伺ってあります。","voiceIndex":182,"id":"exchange-073"},{"speaker":"山路委員","kind":"質問","question":"そこで、斎場側の、今坂があると言われましたけど、出入口のほうなんですけど、ここに年中チェーンでとめてある。自転車もここからは入れない。この期間はチェーンを常時取り外しまして、斎場に近いほうの出口を開放して、駐車場の危ないと、人と車と一緒に出るほうを何とか整理できないかですが、どのようにお考えでしょうか。","respondent":"宮地区民課長","answer":"仮駐車場が設置できますと、今度は本管の工事を、立坑を掘るのに、もう一度敷地の使い勝手の見直しをいたしますので、そのときに今スロープのところを車止め柵がおいてありますが、そこを撤去して、車と人とが別々に通れるような形で、今要望しておりますので。","voiceIndex":184,"id":"exchange-074"},{"speaker":"山路委員","kind":"質問","question":"考えていらっしゃるようですので、どうぞよろしくお願い申し上げます。次に、福祉施策包括補助金の都の補助金１億５，９９９万９，０００円と計上してありますが、これはどういう内容で、どういう人に使われているものなのか、お伺いいたします。","respondent":"日下部障害者福祉課長","answer":"この補助金につきましては、各区で地域の実情に応じた独自の事業につきまして、補助金が東京都のほうから交付をされるという事業でございまして、平成１３年度につきましては、高齢者の関係、それから障害者、子育ての関係ということで、あわせて２４件の事業に対しまして。","voiceIndex":186,"id":"exchange-075"},{"speaker":"山路委員","kind":"意見","question":"内容についてはわかりました。午前中にも福祉改革推進プランという東京都のお話がありましたけど、この中でも、各区のアイデアとか、主体性を発揮するとか、いろいろ充実、強化戦略プロジェクトということで、東京都は言っておりますけど、品川区でも区民のアイデア、あるいは主体性を発揮するということでの今後の取り組みについては、今言われた事業のほかに計画があったらお知らせを願いたいと思います。","respondent":"日下部障害者福祉課長","answer":"例えばその中におましては、平成１４年度の予算の執行の関係で申しますと、例えば保育園のインターネットの映像配信サービスであるとか、そういったものも含めて品川区ならではのアイデアを最大限この補助金のほうに活用してまいりたいと、このように考えております。","voiceIndex":188,"id":"exchange-076"},{"speaker":"沢田委員","kind":"質問・要望","question":"２点質問します。一つは区の財政状況の中でも、特に目立っております基金の問題について質問させていただきたいと思います。平成１３年度の基金の残高、取り崩し型で見てみますと、５２３億７，８００万円余と。前年対比で６８億６，１００万円余が増となっておりますけれども、この中身はどのようなことかということと、それから、品川区の基金に対する基本的な考え方を教えていただきたいと思います。","respondent":"市岡企画財政課長","answer":"基金の考え方ですが、午前中の審議の中で、財政の健全性ということが一つテーマになりましたが、収支が均衡していることと同時に、将来に備える、しかも計画的な事業、とりわけ投資的な事業にきちんと対応できるような備えをすると。","voiceIndex":191,"id":"exchange-077"},{"speaker":"沢田委員","kind":"意見","question":"それにしても、５２３億円という、１，２００億円ぐらいの年間の一般会計に比べても、かなりこれが多額になっているというふうに私は思うんですけれども、先ほどの２３区で中位の話ではないんですけれども、２３区全般で見て、基金の残高が多いというと、品川区はどれぐらいになるのかということが一つと、それからもう一つは、将来的にこの基金はどこまでためれば区の。","respondent":"市岡企画財政課長","answer":"今後の基金ですが、これは端的に言いますと、基金は先ほど申し上げたような視点に立って、活用するために現在保有しているものでありまして、ちょうど第二次の総合実施計画の策定も今ちょうど山場に差しかかっておりますので、これから区民のために必要とされる大きな投資的事業。","voiceIndex":193,"id":"exchange-078"},{"speaker":"沢田委員","kind":"意見","question":"そこで、来年度の予算編成を今やっているところでしょうけれども、区民の今置かれている生活の実態をどう把握しているのか、区側として予算編成をしていく上でとらえていることなどがあれば、ぜひ聞かせてほしいというふうに思います。","respondent":"市岡企画財政課長","answer":"現在の経済状勢、景況のもとで、区民生活がいろいろ困難な局面にあることは、これは全国どこでもそうですが、それに対して区として最も切実な生活課題に対応していくと、こういう視点で財政運営をしているものでございまして、予算のことはこれからの問題ですので。","voiceIndex":195,"id":"exchange-079"},{"speaker":"沢田委員","kind":"提案","question":"私は提案なんですけれども、もちろん長期的な展望を見通していくことは大事ですから、それをやりつつも、当面区民の暮らしや経営を支えていくものについては、この基金の中から計画的に取り崩して、区民のための施策を私は講ずるべきだなというふうに思います。だから、この際だから、住宅をつくる、公的な住宅をつくるという問題、これをやってほしいと思います。","respondent":"市岡企画財政課長、田村住宅課長","answer":"最近の経済の状況、それから今後増大するさまざまな行政課題にきちんと対応できるだけの将来的な財政力を持つために、このような財政運営をしているものでございまして、そういう意味では。ただ、実際に建設関係４団体のほうでは、すべての住宅の工事にというような内容でございましたが、やはり環境プラス地域産業の活性化というような柱で、それが眼目ですので、その中で見直しを含めて。","voiceIndex":197,"id":"exchange-080"},{"speaker":"沢田委員","kind":"質問・要望","question":"今の区政が区民の皆さんの要望を得て、サービスを他区に先駆けてやっているかどうかの評価はちょっとここでは避けさせていただきたいというふうに思います。ここは、私は反省があってしかるべきだというふうに思うんですが、反省があるのかないのか、あるいは実際に再開発用地として買ったものを購入目的のためにどのように使われたのか、ちょっと説明願いたいと思います。","respondent":"西島経理課長","answer":"そういう中で、この土地をいかにして有効に活用していくかというところで検討してまいったところですけれども、このたびサンウッドから共同開発の話が持ち上がりました。そういうことで、ちょうどいい機会だということで、この共同開発に乗ったです。","voiceIndex":200,"id":"exchange-081"},{"speaker":"沢田委員","kind":"質問","question":"この７億１，２００万円の財源構成は何でしょうか。それから、今再開発目的のために使われたと言いますけれども、具体的に再開発の目的にどう使われたのか説明願いたいと思うんですが。","respondent":"市岡企画財政課長、南雲都市開発課長","answer":"これは財調で国公有地、都有地も含めて特別な算定がありまして、当時それが、その算定の対象になりましたが、性質としては一般財源です。この用地の主辺が、ちょうどシンボルとなる空間として、サークル状の広場に整備されるということで、周辺部はすでにそのように整備されておりまして、そういうことで、天王洲の再開発によりよい方向に誘導するということで。","voiceIndex":202,"id":"exchange-082"},{"speaker":"沢田委員","kind":"質問","question":"しかし、その後にスポーツメーカー、くつのメーカーであるナイキジャパンにしばらく貸していたと、これも再開発のために貸していたんでしょうか。私は７億円からの大変なものを、目的があって一般財源を投入したのに、長期間にわたってこうした使い方をしているというのは、やっぱり大問題だというふうに思います。そのことだけお尋ねして終わりたいと思います。","respondent":"西島経理課長","answer":"そういうところから比較いたしますと、目減りはかなり少なくなった。さらに、ここを独立創業支援事業として活用することで、また一定の収入が得られますので、そういう指摘には当たらないというふうに考えてあります。","voiceIndex":205,"id":"exchange-083"},{"speaker":"佐藤委員","kind":"質問・要望","question":"それからあと、第一勧業銀行と富士銀行がみずほ銀行、あと、三和銀行と東海銀行、これが一緒になってＵＦＪ銀行ということになっているんですが、こういうふうに銀行が四つの大きなグループに統合されたわけですけども、この際に、品川区に対して、本店ということはないんでしょうが、区内の営業している支店長なり何なりから、こういうふうな形になりますというような事前の通知、報告。","respondent":"小野副収入役","answer":"現在の資金の運用の状況ですけれども、ペイオフになりましてから、資金管理に関しては非常に重要な問題だと考えてございまして、公金ですということですので、まずは安全、健全ということで、その中でいかに効率性を求めていくかという視点でこれまで運営してまいりました。","voiceIndex":208,"id":"exchange-084"},{"speaker":"佐藤委員","kind":"質問","question":"それで、その報告がおありになったということなんですが、内容はどういう報告なんですか。ただ単に、名称が変わりましたというだけの報告なのか、一番身近な例として、何か昨日さわやか信用金庫というのが発足したらしいんですね、旧同栄信用金庫、それから港信用金庫が変わった東都中央信用金庫、それと東京産業信用金庫、これは役所のほうにはどういう報告をされていますか。","respondent":"小野副収入役","answer":"かなり前にそういうことになるということで、支店長のほうからごあいさつ方々、こういうことで合併いたしますということでごあいさつをちょうだいしておるとともに、文書でもってちょうだいしています。","voiceIndex":210,"id":"exchange-085"},{"speaker":"佐藤委員","kind":"質問","question":"私が立ち会うわけにいかないので、それを信用するしかないですけれども。それで、今は大東京信用組合ですか、そこと一緒になっている。それで、聞くところによりますと、ペイオフが万が一生じた場合に、自治体の場合は区の幹部が責任をとるというふうなことをちょっとお聞きしたことがあるんですが、こういうことは実際おありになるんでしょうか。","respondent":"小野副収入役","answer":"責任についてですけれども、自治法によりまして、一応基金それから公金については安全にかつ効率的に運用するということがございまして、その中で、だれが見ても怠慢、基金管理に対して怠慢だったというようなところで。","voiceIndex":212,"id":"exchange-086"},{"speaker":"佐藤委員","kind":"質問","question":"基金の運用を間違った場合は、そういう個人的な責任をとる場合もあるというご答弁ですが、これはそうすると、ペイオフの場合は、いくらそれによって損害が生じても、単に専決処分に似たような形で特別損失かなんかで財政上処理すればいいと、こういう理解でよろしいんですか。何か収入役が個人的に責任をとらなきゃいけない場合があるというようなことをどこかで私聞いたことがあるんですが。","respondent":"相川収入役","answer":"今回、ペイオフにつきまして、金融調査会を設けまして、弁護士の方にも入っていただいたわけですが、やはり、その点につきましては、区民の皆様に、もしくは議会もそうなんですが、ちゃんと説明できる対応策をとっておかなければ、賠償の責任は免れられないと、こういう解釈です。","voiceIndex":214,"id":"exchange-087"},{"speaker":"佐藤委員","kind":"質問","question":"もう一つの私の疑問なんですが、万が一ペイオフが生じた場合、収入役のほうに個人的なミスはないということになった場合、例えば定期預金が今ですと１０億円なら１０億円ペイオフで犠牲になったと、こういう処理はどういうふうになさるんでしょうか。","respondent":"相川収入役","answer":"その後、同じ普通預金でも、東京三菱銀行でありますとか、三井住友銀行でありますとか、これまで預け入れても非常に金利の低いところにもオファーをかけたわけですが、正直、ありがた迷惑のような対応でございました。","voiceIndex":216,"id":"exchange-088"},{"speaker":"佐藤委員","kind":"質問","question":"その金利のつかない決済性預金をつくって、そこに預金を移して、ペイオフの対象から外すような法律をつくろうという動きもあるようですが、この都道府県の知事会とか、市町村の長会ですね、市長、区長、こういうところで地方自治体として財務省なり金融庁なりに急いで安心して行政財源を金融機関に預けられる特別立法をしろというふうな動きは今でもないのでしょうか。","respondent":"小野副収入役","answer":"今般、特別区長会におきまして、平成１５年度の予算要求の中で、ペイオフ解禁後の公金預金等の保護ということで、自治体の公金預金については保護するようにということで要望を出しています。","voiceIndex":218,"id":"exchange-089"},{"speaker":"伊藤委員","kind":"質問","question":"私は成果報告書５８ページの区民保養所使用料、それから総合区民会館使用料に関連して質問いたします。明日の総務費で私質問しようと考えていますので、答弁のほう、よろしくお願いいたします。今までいろんな会合に行ったらしいんですけど、そういうことは初めての経験だったので、なぜそんなことをなさったのかということが一つと、それからたまたまそこにある時計が１０分進んでいたらしいんですよ。","respondent":"宮地区民課長","answer":"それ以降は８時に片づけ始めるということもありますけれども、利用者の方のご希望に応じて、柔軟に対応しています。","voiceIndex":221,"id":"exchange-090"},{"speaker":"伊藤委員","kind":"質問","question":"まさかこれだけで質問を終わるわけにいきませんので、あれなんですが、それはそれで対応をお願いいたします。今契約のお話をされました。多少数字を調べていきますと、３億２，８７０万円の経費を品川荘、暖景苑で使っています。延べ人数で２万９，０００人の方々が利用されていらっしゃる。課長も今の嫌な質問を受けなくて済む。そのことを考えてみたらいかがかと思うんですが、答弁ありますか。","respondent":"宮地区民課長","answer":"保養所のあり方のやはり今後の考え方として、以前も行財政改革の中でご提案いただきましたけれども、部屋借り上げ方式とか、いろいろなやり方があるだろうということで、今後の検討課題としますというふうにお答えしています。","voiceIndex":223,"id":"exchange-091"},{"speaker":"伊藤委員","kind":"質問","question":"品川区の職員の皆さんはクアパーク倶楽部というところと契約されていらっしゃいますよね。これは部屋の借り上げです。年間３，９００万円の費用で動いている。だれがどう考えても、固定施設を持って、そこに人を置いといて、そこにお客さんを呼ぶというよりは、借り上げしたほうがはるかに安いし、それから区民のいろんなサービスの選択肢も広がるわけですよ。お願いします。","respondent":"宮地区民課長","answer":"せっかくのご提案ですので、それも勉強し、それから今借り上げ方式もご提案を受けましたので、引き続きいろいろ情報は集めておりますので、よりいい形で検討ができればと考えています。引き続き検討してまいります。","voiceIndex":225,"id":"exchange-092"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これは私ども自民党はずっと言い続けてきた内容ですので、なるべく早く結論を出していただきますように強く要望しておきます。これはちょっと単純に考えてもおかしいんじゃないですか。例えば、ガスとか水道代がかかった実費を負担するならまだわかるんですけれども、調理のそこにはテーブルを使うだけでお金がかかるというのは何なんでしょうかという素直な疑問があったのが一つ。お願いいたします。","respondent":"上山区民生活事業部副参事","answer":"もう一点、小ホールの音響ですけれども、音響設備そのものにつきましては、数年前に一部改修をさせていただきました。今回改修工事の中では大ホール等につきまして力を注ぎまして、より音響のいいようにということで改修をさせていただいているところです。","voiceIndex":227,"id":"exchange-093"},{"speaker":"伊藤委員","kind":"質問","question":"テーブルのほうの話は、確かに調理台ですから、特別なことはわかりますけど、ただ素直に考えて、それは部屋代で取ったらいいんじゃないですか。それから小ホールですけれども、ちょっと私の質問の仕方が悪かったかもしれませんが、もう一度聞きますね。あの小ホールの設計のときには、音響の設計とか、それから音の響き方ということを十分に踏まえて設計したんですかということ、それをお聞かせください。","respondent":"上山区民生活事業部副参事、太川区民生活事業部長","answer":"小ホールのほうですけれども、開館当時につきましては、大ホールということでの区別も一つありますし、面積的にはある程度音響については対応できるということで、例えば演劇とか、そういうものでの活用も一つ想定したかと思います。これはきゅりあん全体の備品関係につきまして、いろいろとご意見をちょうだいいたしますけれども、例えばマイク１台お幾らとかという形でいただいてありますので、そういう基本的な考え方に基づいているものです。","voiceIndex":229,"id":"exchange-094"},{"speaker":"伊藤委員","kind":"質問","question":"でも、そうじゃない。だから、その中で、例えば音響パネルというんですか、専門的なことはわかりませんけれども、音響パネルを使って音響効果を上げていくとか、要するに多目的に使われているんだったらば、ピアノのコンサートにも十分耐えるような仕組みを考えてみたらどうですかと思うんですが、いかがですか。","respondent":"太川区民生活事業部長","answer":"そうしますと、いわゆる調理台の部分ですけれども、もし、部屋一つでまとめてということですと、やはり料金設定を多少変更するようになるかなというふうに考えてあります。","voiceIndex":232,"id":"exchange-095"},{"speaker":"伊藤委員","kind":"確認","question":"きゅりあんですから、非常に区民の利用が多いし、それから区民外の方も使っているところですね。確かに今さら天井を高くすることはできませんから、それはわかりきっている話で、だから、その仕組みの中で音響パネルを使っていくとか、それから検討していくとか、そういうことをもう一度確認の答弁を部長からいただいて、お願いします。","respondent":"太川区民生活事業部長","answer":"今伊藤委員のほうからご指摘ございましたけれども、それらにつきましては、私ども十分今後運営の中でまた検討研究をさせていただきたいと思いますので、よろしくお願い申し上げます。","voiceIndex":234,"id":"exchange-096"},{"speaker":"土井委員","kind":"質問・要望","question":"それからもう一点は、水族館ですが、いろいろと新たなものを導入するという形で、おかげさまでまだここに運営費収入という形でなってきている、いわゆるまだ黒字の状態だというふうに思うんですけれども、これが今どうなっていて、これからの趨勢で、また起死回生の何かを打ち出せば、それなりにお客が増えるのかどうかということも問題がありますので。","respondent":"市岡企画財政課長、太田保険年金課長、松代道路公園課長","answer":"地方消費税交付金がなぜ増えているかというのは、なかなか難しい問題なんですが、我々のほうも国や都にいろいろ問い合わせをしたりして聞きましたが。国のほうで執行予定が、年内にその分のお金が区のほうへ入るというふうな予定で聞いております。私のほうから水族館の運営のことについてお答え申し上げます。将来の見通しというようなことですけれども、まず現状を申し上げます。","voiceIndex":237,"id":"exchange-097"},{"speaker":"土井委員","kind":"質問","question":"私も地方消費税交付金が増えたというのはどうしてなのか、こんなに消費が冷え込んだ、冷え込んだとさんざん言われているのにと思っていたんですが、グッチだとか何とか、いろんなのがお店を出してくれたせいなのかどうかわかりませんけれども、そんなことなんですか。その意味では、どうも私どもの先輩がお話をしてできた経過もあるものですから、少しいろいろと我々も注視をしながらやってきております。","respondent":"市岡企画財政課長","answer":"とは言うものの、今年の前半を見てみますと、やや落ち込んでおりまして、今後はあまり期待できないかなと思いますので、委員おっしゃられるとおり、これはもともと地方税財源の拡充を目指した交付金ですので。","voiceIndex":241,"id":"exchange-098"},{"speaker":"飯沼委員","kind":"質問・要望","question":"目黒線連続立体交差事業の予算について、総事業費、あと４事業者のそれぞれの負担、あと工事の進捗率と平成１３年までの品川区の負担額の合計を教えていただきたいのと、今事業が当初の計画と比較して区民にどのような利便性をもたらせているのか、区はどう評価をしているのか、その点についてお伺いしたいと思います。","respondent":"中島街路事業担当課長","answer":"１点目の目黒線の連続立体事業の進捗率ですけれども、平成１３年度末で、予算ベースでいきますと４７％です。それと２点目の、これまで品川区として負担した額ですけれども、累積でいきますと、平成１３年度末で８２億７，２００万円です。","voiceIndex":244,"id":"exchange-099"},{"speaker":"飯沼委員","kind":"質問","question":"２点目は、目黒線の輸送力の増強というのも含めて、この工事が行なわれて、目黒線を活用した東横線の複々線工事、これもあわせて行なわれているということでは、東急の輸送力のアップに大きく貢献していると思うんですけれども、しかし、地元の不動前とか、武蔵小山とか、西小山を利用している方々にすると、車両が４輌から６輌、さらにまた８輌になるわけですけれども、そういったことで。","respondent":"中島街路事業担当課長","answer":"そういった中では、事業が満了する間近な中で、まちづくり等についても具体的な検討に入れるものじゃないかなというふうに考えてあります。","voiceIndex":246,"id":"exchange-100"},{"speaker":"飯沼委員","kind":"質問・要望","question":"まちの分断が行なわれるということでは、まちづくりの視点からして、私は区民の代弁者としての区の責任が果たせていないのではないかなと思っています。東急と都と同じような立場に立っていては困ると思うので、都と東急にどのように働きかけていらっしゃるのかお伺いしたいと思います。その点について、車を通さない確約をいただきたいと思うんですが、いかがでしょうか。","respondent":"中島街路事業担当課長","answer":"それと、そういう点では、東京都と東急、私ども目黒区もあわせて、４事業者としてそういった考えで進めているところです。","voiceIndex":248,"id":"exchange-101"},{"speaker":"飯沼委員","kind":"提案","question":"７２名の方が参加したと報告がありましたけれども、事業者の提案を認める人は１人もこの中にはいらっしゃいませんでした。この点については、ほんとうに例え百歩譲って道路をつくっても、通さないんだということをはっきり住民の方に示すべきだと思いますが、この点、いかがでしょうか。","respondent":"中島街路事業担当課長","answer":"１点目の８月２８日に開催いたしました代替施設計画の変更の説明会ですけれども、今委員言われましたように７２名の方に参加していただきました。私ども当然その場で説明者側としていたわけですけれども、確かに閉鎖に反対だという意見の方もいらっしゃいました。","voiceIndex":250,"id":"exchange-102"},{"speaker":"飯沼委員","kind":"質問・要望","question":"とにかく区の役割というものを追求して、区民の方の合意形成を図られるように強く要望して終わります。大変助かっているところなんですけれども、審査項目の中身によってはとても分厚い資料が提出をされて、目を通すことができなかったり、あと事前の調査が十分にできないようなケースがありますので、１週間前までに出していただくように、さらなる改善をしていただきたいのですが、いかがでしょうか。","respondent":"福田区議会事務局長","answer":"したがいまして、今たかだかといっては何ですけれども、２年後の今にもう一声１週間前だということにつきましては、一応議長にはそういうご発言があったということは、ご報告をしますが。","voiceIndex":252,"id":"exchange-103"},{"speaker":"飯沼委員","kind":"意見","question":"新人のときもそう思いましたけれども、現在に至っても思っているのはなぜかというと、例えば新しい制度を審査するとき、例えば今回の住基ネットにかかわることとか、あと支援費制度とか全く新しいものが出てきたときに、やはりいろいろ勉強したいわけですよ。","respondent":"福田区議会事務局長","answer":"したがいまして、議論するならば、もう一度その場で正式な議論をする必要があると思いますが、申しましたように、今まだその時期ではないと私は考えております。","voiceIndex":254,"id":"exchange-104"},{"speaker":"辻委員","kind":"質問・要望","question":"５時になりましたが、簡単に２点お伺いいたします。一つは、都区財調関係から見て、この７月に議員の研修会があったとき、要するに合併、市町村合併の問題を、例えば財調から見ていったときにどう考えるのかというのを、ちょっとお考えをお聞きしたいのと、それから住民基本台帳に関してお伺いしたいと思います。そのときに、例えば２３区なんかが合併問題について全く触れないで過ごすわけにいかないだろう。","respondent":"高橋区長","answer":"率直に申し上げまして、２３区の合併につきまして、区長会で具体的に何も検討してございません。今特例法がありますが、たしかあれは平均３０万都市にしていこうというふうな構想だと考えています。","voiceIndex":257,"id":"exchange-105"},{"speaker":"辻委員","kind":"質問","question":"ただ、ちょっと質問の仕方が後先になっちゃって申しわけない。要するに、東京都が何年か前にもだれかが、私も聞いたかと思うんですけど、要するに固定資産税が各区でどうなっているんだというのは、下の都税事務所が全く明らかにしないんですね。どうなっているというか。要するに、合併の中で、２３区はどこかで研究なり検討して結論を出す必要があるのかなと思うんですけど、その辺の考えはいかがですか。","respondent":"高橋区長","answer":"それは財源というものを持っていて、その中での誘導されますと、かなり弱い面があります。そういう面を各区が自覚をし、どのように東京都に対応していくか、これからの区長会の大きな使命じゃないかなと考えています。","voiceIndex":259,"id":"exchange-106"},{"speaker":"辻委員","kind":"質問・要望","question":"まさしく区長が一つやっていただきたいのは、そのことなんですね。要するに、私たち党の中でもいろいろ研究、勉強会をやっているときに、この合併問題というのは、２３区だけ避けて通れない話になってきている。例えば区長は品川区の住民ですから、私が区長の住民票の一部を閲覧したいということなんか、その数というのは基本的にこの閲覧制度というものについてちょっとお知らせいただきたい。","respondent":"冨田戸籍住民課長","answer":"基本的には通常ご本人あるいは同一の世帯の方であれば、特に理由は問いません。それ以外の方がご請求される場合には、不当な理由、特に差別とかプライバシーを侵害するような形の目的であれば、これはお断りするということになっております。","voiceIndex":261,"id":"exchange-107"},{"speaker":"辻委員","kind":"質問","question":"ただ、今回の場合ですと、６７９万１，３００円入っている場合、どういう人がどういう形で行なわれているんですか。例えば、私が考えているのは、申請に行ったときに、手続はどういう手続をするんですか。この辺はどうなんですか、その辺の不特定多数を見ることができるのか、その辺の閲覧の制度というものはどういうことで行なわれているのか。そして、６７０万円になっているのか。","respondent":"冨田戸籍住民課長","answer":"歳入決算に書いてあります６７０万円のうちのほとんどが大量閲覧によるものです。個別のものは１０件単位の件数です。それ以外は通常３０分１，０００円という形で、一定の簿冊をつくりまして、それでご覧いただいております。","voiceIndex":263,"id":"exchange-108"},{"speaker":"辻委員","kind":"質問","question":"要するに、例えばこんな本だと３０分１，０００円と言ったでしょう。その間だったら、何冊見ようと、メモしてもいいわけですか。そのときに、例えば私が行くときに、地域の住民の住所、氏名を知りたいからという理由でやって、ダーッと速記してもいいんですか。","respondent":"冨田戸籍住民課長","answer":"申請をいただくときに、どういう理由でお調べになるのか、それをチェックします。それが不当であるかないか、その場で判断をしますけれども、不当でなければお受けするということになります。","voiceIndex":265,"id":"exchange-109"},{"speaker":"辻委員","kind":"質問","question":"じゃあ理由で、例えば私が商売を始めて、そのときにダイレクトメールを送りたいから住所を調べたいという理由でもいいんですか。","respondent":"冨田戸籍住民課長","answer":"ただ、単純にダイレクトメールという形では、ちょっともう少し具体性に欠けるということですので、実際申請いただいたときに、個別具体的に過去の実例等も参照しながら判断をしているのが実態です。","voiceIndex":267,"id":"exchange-110"},{"speaker":"辻委員","kind":"意見","question":"というのは、今住基ネットの問題で、今言ったまさしく見れる４項目というものが、どこで漏れるか漏れないかと、これは不当に使っちゃいかんというか、そういうものについてはきちっとするというふうになっているわけですよ。要するに、その４項目はプライバシーを守るというけど、閲覧でずらずらだれでも正当な理由があればどんどん見えていく、その理由は政省令にあるんでしょうけど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":269,"id":"exchange-111"},{"speaker":"塚本委員","kind":"質問","question":"ちょっとその点についても触れておきたいと思います。財政の問題もそうですし、なかんずく、人事のほうが離脱の可能性というのはかなりあるわけですから、その手順を考えるべきときに来ていると思います。どの部署で区長会のスタッフがどれほど有能か、そうでないかわかりませんけれども、そういうものを準備する時期に来ている、官僚に下命する時期に来ていると思いますけれども、いかがお考えですか。","respondent":"高橋区長","answer":"人事権の独立ですか。","voiceIndex":271,"id":"exchange-112"},{"speaker":"塚本委員","kind":"質問・要望","question":"まして、人事権を握って２３区の人事委員会は大変な権限を持っておるところが、みずからの育成について云々して、なかんずつ解体の方向に向かおうということは困難を極めるわけですから、ほかのところに特別区協議会の中で、そういうものを研究する機関をつくって、手順を研究する、問題点を洗い出す作業がいつの時点かになければ、そういう制度は変わらないと私は思います。端的にお答えいただきたい。","respondent":"高橋区長","answer":"私は再三この清掃の問題、私は清掃の部会の部会長をやっておりますが、清掃の問題について物を言うわけですが、いや、それは区長会でやりますからというので、一切その話はぬぐわれてしまうわけでして。","voiceIndex":275,"id":"exchange-113"},{"speaker":"塚本委員","kind":"質問","question":"１００分の１、これが２割上がっても１.２％になるだけですが、そのことが十分に仕事をすれば、大きな全体の１割カット、１０倍の仕事をするという可能性があるわけですから、そういう意味でも、現在の事業の強化をお願いしたい、そのことについての見解を伺いたいということと、もう一つはハードの部分なんですが、私どものスペースというのは大変限られておりまして、中でもＯＡ化。","respondent":"福田区議会事務局長","answer":"ただ、今までのことを振り返ってまいりますと、執行機関側に、大きな組織改正ですとかがありまして、それに伴ってレイアウト変更が行なわれる、そういう場合につきましては、例えば５階の第５委員会室の隣にある議員応接室、こういうものがわずかといえばわずかかもしれませんが。","voiceIndex":277,"id":"exchange-114"},{"speaker":"塚本委員","kind":"意見","question":"職員の練度のことですけれども、私も十数年おりますけれども、ここ１０年、見違えるように意欲が高まって、能力がアップしているとつくづく思います。心強い限りですけれども、やはり、絶対量がもう少しあればいいな。その二つは置いといて。そういう意味で、議会のプレゼンテーション、広報の仕方の方向性というものを今事務方はどのように見ているかということの見解を確かめておきたいと思います。","respondent":"福田区議会事務局長、原委員長","answer":"その一つの証左といたしまして、年内にできれば試行的に立ち上げたいと考えています議会独自のホームページ、こうしたことにも手がけていく、どういう認識かということでお答えをいたしました。以上をもちまして、本日予定の審査はすべて終了いたしました。次の会議は明日午前１０時から開きます。本日はこれをもって閉会をいたします。","voiceIndex":279,"id":"exchange-115"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1196#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":114675,"voices":281}},{"id":"h14-20021003-4","meetingId":"h14-c-settlement","date":"2002年10月3日","dateIso":"2002-10-03","committee":"決算特別委員会","time":"午前１０時０５分～午後５時３５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を139件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"初めに、目黒川の水位が１.７ｍになると危険水位で、２.７ｍだと警戒水位ということで、立会川ですと１ｍで危険水位、１.５ｍで警戒水位ということになるわけですが、災害時のサイレンの出し方について、それぞれ種類があるんだと思うんですが、その種類と区内何箇所ぐらいにサイレンを発信しているのか、平成１３年度の稼働状況を教えていただきたいと思います。","respondent":"久保田防災課長","answer":"立会川も同様です。それから、平成１３年度は４回ほど水防本部を設置していますけれども、その中でサイレンを鳴らしたのは２回です。","voiceIndex":4,"id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"平成１３年度は比較的雨量の多い日が少ない年だったのかもしれなんですが、まだ年度途中なんですが、今年度の状況を把握しているところで教えていただきたいと思います。","respondent":"久保田防災課長","answer":"平成１４年度の状況ですけれども、既に８回水防本部を設置しています。台風６号・７号の接近、８月２日、８月４日、８月１９日も台風の接近です。９月６日、９月７日は集中豪雨です。それから、直近では１０月１日の台風２１号です。","voiceIndex":6,"id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"ケーブルテレビの区民チャンネルで、満潮時刻ですとか水位なの防災情報も最近はわかりやすくなっているんですけれども、そういった面でアナウンスの仕方はどういう状況なのか。当然、豪雨のときは音も大分潰れてしまうのかなと思うんですけれども、光化学スモッグ注意報を発令したときと水害のときの音量などの内容について教えていただきたいと思うんです。","respondent":"久保田防災課長","answer":"この中には、台風の情報とか土のうの用意の情報を流して何回か巡回しておりますので、そういう形での広報も組み合わせながら、より効果的な周知の方法を今後検討していきたいと考えております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"事前に取組んでいただけるということで、伝達の効果が一層上がりますようによろしくお願いいたします。医薬品のそれぞれのものによって期限が異なって、適宜入れ替えをしてやっていくという見直しをしたわけですけれども、その辺の状況を教えていただきたいと思います。","respondent":"久保田防災課長","answer":"そういう形で薬品等についての対応はしていますけれども、そのほか医療資機材として１３の学校に救護所を予定しておりますので、救護所に医療セットを配備しています。","voiceIndex":10,"id":"exchange-004"},{"speaker":"本多委員","kind":"確認","question":"今現在ではランニングストックをしっかりやっているということで、管理をされているということで期限を過ぎたものがないと思うんですが、期限を過ぎたものは在庫していないという確認だけをしたいと思います。","respondent":"久保田防災課長","answer":"期限を過ぎたものはないと確認しております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"それと実際問題、我々自民党も民間委託ということを言っているんですが、その辺についての設計図書の品質というのでしょうか、でき上がったものの品質について、その辺の状況についてお聞かせいただきたいと思います。","respondent":"片田施設担当課長","answer":"平成１３年度の事業部制の中で組織改正されて、営繕課は新しく施設課になりました。設計実績ですので、平成１３年度につきましては、細かい小破修繕も含めて５１１件ほどの設計実績を持ってあります。民間委託した件数については、２件ほどあります。","voiceIndex":14,"id":"exchange-006"},{"speaker":"中島委員","kind":"質問","question":"大抵災害が起きるのは役所が終わってからのほうが多いものですから、仕方がないと言ってしまえばそれまでなんですけれども、どこか窓口を一本化するなり明確に指示をして、今人が足りないからこういう状況なんだとか、そういった対応ができるような工夫はできないのかなという点を１点お伺いしたいと思います。なぜ張られなかったのかという点について、お伺いしたいと思います。","respondent":"久保田防災課長、矢部下水道河川課長","answer":"翌日に行っても当事者が留守だったということもありますし、そういうのでちょっと時間がかかるということもありますけれども、緊急対応という要請の場合には、即行って対応している態勢を取っているところです。立会川を鉄板によるかさ上げの件ですけれども、立会川につきましてはけた下の低い立会川橋の上流部や、川が急曲線で曲がっている場所など、水面が波立って河川水が護岸を越えやすい場所につきまして。","voiceIndex":17,"id":"exchange-007"},{"speaker":"中島委員","kind":"質問・要望","question":"床上浸水は緊急性を要していないのかということで、その人の言い方にもよったのかもわかりませんが、そういったことも二、三聞いているものですから質問いたしました。「私たちだけが被害を受ければほかにいかないから、ここで緩和しているんじゃないか」と、こんなふうにも言われておりますので、この点に対してはどのようにお考えでしょうか。","respondent":"矢部下水道河川課長","answer":"先ほどのかさ上げ鉄板を他の場所にも設置をという件ですけれども、かさ上げ鉄板をやる場合、護岸に面した建物の状況とか設置した場合の効果、逆に一部の場所に鉄板が張られなかった場合に、危険度が上がってしまうという場合もありますので、その辺を総合的に検討しまして。","voiceIndex":20,"id":"exchange-008"},{"speaker":"中島委員","kind":"質問","question":"今、建物の状況とおっしゃられましたが、東大井側のことではないかと思います。私が申し上げているのは、道路に面した南大井側です。一部鉄板が張られていないために、そこの地域が被害を大きく受けているわけですから、地元の方たちはこの辺のところを非常に憤慨した気持ちでこれからの区のやり方を見ていると思うんですが、その辺をもう一度よろくしお願いいたします。","respondent":"矢部下水道河川課長","answer":"その辺の危険度を調査をさせていただいて、その後の対応について検討させていただきたいと思います。","voiceIndex":22,"id":"exchange-009"},{"speaker":"中島委員","kind":"質問","question":"よろしくお願いしたいと思います。確かに、鉄板を張っただけでは解決する問題ではないと認識しております。それとともに、第二立会川幹線を待つということは、非常に長い話でありまして、ここのところの川底を掘るとか、その他の方法がこれから取れないのか、どういった対策をお考えなのかどうか、その辺をお伺いしたいと思います。","respondent":"矢部下水道河川課長","answer":"それが完成しますと、立会川に雨天時に流れ込む下水が、立会川幹線を通じまして京浜運河まで流される予定になってあります。一応、立会川幹線の整備を優先させたいと考えております。","voiceIndex":24,"id":"exchange-010"},{"speaker":"中島委員","kind":"質問・要望","question":"いずれにしても、早急な手だてが必要ではないかと。この辺のところも再度調査をお願いしたいと思います。土のうを運ぶと起きられないぐらい体が痛くなってしまうとか、持ち上げるのが大変だとおっしゃっている方もいるんですが、何か軽い水を入れて土のうのかわりになるものとか、いろいろ開発されていると思うんですが、この辺のところも何か検討していただきたいなと思いますが、この辺はいかがでしょうか。","respondent":"松代道路公園課長","answer":"私どもとしましては、今、お話のありました立会川も含め、目黒川も含めまして、なるべく被害があったところの直近に土のう置き場を今回も１０カ所ほど増設しまして、少しでもご利用いただけるように努めているところです。","voiceIndex":26,"id":"exchange-011"},{"speaker":"中島委員","kind":"質問","question":"最近、町会も高齢化しているので大変なんだけれども、この機械の改良ができないのかという質問も受けております。時間がありませんので、これは後でお答えを伺うことにします。次に、地域センターと管理運営費に関連してですが、区民の方が学習したり集会を行ったりする地域センターですが、ここにピアノが置けないのかという質問を受けております。これはどうなんでしょうか。","respondent":"長田地域活動課長","answer":"ですから、そういった意味では、ピアノは当然音が出るものですので、ほかの集会室にも影響が出てくるということで、今のところ置いてございません。集会室の利用目的を考えた上で、そのようにさせていただいていますので、ご理解いただきたいと思います。","voiceIndex":28,"id":"exchange-012"},{"speaker":"中島委員","kind":"質問・要望","question":"音がとおっしゃいましたが、荏原第５地域センターで確か太鼓の練習をされていたと思うんです。そういったことも考慮して、地域の方でコーラスをやっている方の要望があります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"ファミーユ南大井の件が出ましたので、この点に限ってご質問します。ファミーユ南大井でも、かなりこの間浸水がありました。あそこの地域は浸水が結構出るところなので、あそこの施設に限って防災無線をつけていただけないかという話が居住者から出ておりますので、町会長のお宅には全部つけているという話なんですが、公共施設ということもあって、これはいかがなのかなと考えていますが、お願いします。","respondent":"久保田防災課長","answer":"防災無線の件ですけれども、ファミーユ南大井の状況をつかんでおりませんので、今、防災無線をつけているところは、例えば町会長も常時いらっしゃるという条件があってつけてるものですので、そういったところの面の調査もしながら。","voiceIndex":32,"id":"exchange-014","title":"町会・自治会支援"},{"speaker":"南委員","kind":"質問・要望","question":"防災課長として区民の方々に区の施設の住居を提供しているところで、被害の状況を把握していないというのは問題な発言だと思いますので、そこはきちんと訂正をしていただきたいと思います。それと公共施設ですから、防災無線をきちんと設置をして、これ以上の被害を出さないように、事前に対策がきちんと取れるようにしておくべきだと思うんです。検討ではなくて、考えていただきたいと思います。","respondent":"久保田防災課長","answer":"いずれにしましても、今後防災無線の活用の仕方については全体的な問題もありますので、そういったところの中で検討していきたいです。","voiceIndex":34,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"私からは成果報告書９０ページの品川文化振興事業団助成金について、お聞きしていきたいと思います。第一回定例会、第二回定例会と、この問題はいろいろ論議をされましたけれども、６月の評議員会で副理事長が、「三菱銀行がアルゼンチンの財務省と交渉を始めたところなので、推移を見ていく」という発言をされていますけれども、その後の状況を簡単にお知らせ願いたいと思います。","respondent":"太川区民生活事業部長","answer":"アルゼンチン債の件ですけれども、直近の情報といたしまして管理会社の東京三菱銀行からは、「債権者の権利を最大限に守るべく慎重に検討を行った結果、現段階では管理会社の裁量による期限の利益損失宣言を行わず。","voiceIndex":37,"id":"exchange-016"},{"speaker":"菊地委員","kind":"確認","question":"状況の推移をこれからも見ていくということです。まだすべて集約したわけではありませんけれども、「知っている」と答えられた方の９６％は「区長に責任がある」と答えていらっしゃるんです。区民に損害をかぶせるということにつながっていくわけですから、ルールそのものを守らずに債券の格付けに関する確認書に理事長印を押した元副理事長をなぜ告発しないのか、ここの理由をまずお聞きしたいと思います。","respondent":"高橋区長","answer":"アルゼンチン債を買うのは合法的な行為、ただ手続上の問題があったですので、これは違法の購入ではございません。手続上の問題があったというもので、これは不適切だということを再三申し上げているわけですから、誤解をしないようにお願いいたします。","voiceIndex":39,"id":"exchange-017"},{"speaker":"菊地委員","kind":"確認","question":"確認書そのものも実際にリスクが高いことを承知で買ってくださいということが書かれていて、責任はあなたにあるんだということをはっきり書かれているわけです。これだけの違反行為をしながら、元副理事長を告発をしないということであれば、若干の違反はあったけれども、組織的に購入をしたんだということであれば、元理事長が損害の賠償をすべきことではないのでしょうか。","respondent":"高橋区長","answer":"やはり、そこで利潤を生むということは、それだけのリスクを伴う。そのリスクの大きさを勘案しながら、投資をするのが一番適当な投資の方法ではないかと考えています。私だったらそれをやらないというのは、そういうことで言ったわけです。","voiceIndex":41,"id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"理事長が認めたわけではないということは、やっぱり最初の質問の戻ってしまうんですけれども、元副理事長が勝手に買い付けて、結局損失を出すという事態を招いたことになります。どう考えても、今の区長の答弁では副理事長を告発をしないという理由にはあたらないと思いますけれども、もう一度そこをお願いいたします。","respondent":"高橋区長","answer":"このような一連の処分はさせていただきました。告発するかしないかという問題は、我々の中で決める問題でございまして、おたくから言われる筋合いはないと思います。","voiceIndex":43,"id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"これが何といっても、皆さんの財産を守っていく立場なのではないかと思うんです。品川文化振興事業団も公益法人ですね。膨大な利益を生むためにつくられたわけではない。得た利益そのものが文化振興を通じて区民に還元されていくのは当たり前のことですから、やはり今区長がきちんと区民の声にこたえて、区民が区長に対して問いかけをしているわけですから、そのことについて。","respondent":"高橋区長","answer":"「区長、区長」と言っておりますけれども、区長がただ財団の理事長をやっていたわけですが、理事長としていろいろ言われることにつきましてはお答えできます。区長の行為云々ということでしたら、お答えはできません。それをまず第一に申し上げておきます。","voiceIndex":45,"id":"exchange-020"},{"speaker":"菊地委員","kind":"質問","question":"前理事長は高橋区長、同一人物であります。前副理事長は当時の助役ですから、品川区の財政を預かる、そして区民の生活を守るために働いておられるトップの二人が理事長と副理事長を務められていたわけですから、理事長の顔だとか区長の顔だとかといって区民に通用するような話ではないと思うんです。","respondent":"高橋区長","answer":"財団の問題は理事長の責任です。したがいまして、私は責任を取って理事長を辞任いたしました。区長がやった行為ではないんです。理事長の行為として起きたことですから、私は責任を取ったわけです。区長の責任だというのなら、区に弁償をしろというお考えですか。","voiceIndex":47,"id":"exchange-021"},{"speaker":"菊地委員","kind":"質問・要望","question":"私は先ほどから申し上げていますし、予特の総括質疑のときにも申し上げましたけれども、この問題というのは区長自身が損害賠償を含め、区民に対して求められる説明についてしっかりと説明をすべきだと考えているわけであります。区民の皆さんから問いかけられたものについて、区長が説明責任を果たしていくことをしっかりとやっていただきたいと思っていますけれども。","respondent":"高橋区長","answer":"したがいまして、財団の負債があった場合、それをなぜ区長という名前で請求を受けるんですか、それどの法律で言っているんですか、どのような根拠で言っているんですか、それをはっきりお示しになって。","voiceIndex":49,"id":"exchange-022"},{"speaker":"菊地委員","kind":"質問","question":"区長は元理事長の立場で考えたときに、損害賠償についてもその気はないという発言をされております。私がこの間お聞きしているのは、区長の道義的、政治的責任の部分であります。区長の答弁というのは全くそのことについて触れていないということでありますけれども、最後にその辺について。","respondent":"高橋区長","answer":"ここは財団の理事会または評議員会ではございません。財団の評議員会、理事会でご承認をいただきました。私はそこで謝罪もいたしました。これで一件落着になっております。","voiceIndex":51,"id":"exchange-023"},{"speaker":"菊地委員","kind":"意見","question":"最後に申し上げておきますけれども、区長はこれで幕引きだというような発言をなさいましたけれども、実際には１億６，０００万円がどうなるかわかっていない。これで幕引きというのは絶対許されない話だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私は成果報告書の９３ページ、特別区協議会等に関連して質問いたします。当然、自治体の規模、財政規模は違うわけですから、そこに求められるいろんな行政事情も違ってくるのは当然です。確認したいのは人事委員会がつくられてきた背景、本来２３区が区長の責任のもとでやるべき内容を、どうしてここにいろんなものを集中せざるを得なかったのか、その背景を簡単にお聞かせください。","respondent":"桑村人事課長","answer":"その中で人事機関をどうつくるかという検討の中で、これまで東京都の職員の身分でなったものが区の職員になってくる形の中で、これまでと同じように共通の一定の人事制度を維持していくことが大切であろうという判断をして。","voiceIndex":56,"id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問","question":"経過は理解できるんですが、自治体として基礎的自治体によくなったと最近言われておりますけれども、どうしてこれだけ大きな財政規模を持つ２３区が同じ基準で同じ給与水準、同じ採用の水準でいかなければいけないのでしょうか。今の法律の弊害のおかげで人事委員会の縛りがある。２３区は中途採用とか、いろんな弊害があるということを感じているんですけれども、区長はいかがですか。","respondent":"高橋区長","answer":"今、人事委員会ができました経過については、課長からご説明させていただきました。その後、平成１２年に都区制度が改革されました。それぞれの区が基礎的自治体として発足いたしました。","voiceIndex":58,"id":"exchange-026"},{"speaker":"伊藤委員","kind":"確認","question":"アメリカの自治体は、全く違うことを平気でやっているわけです。隣の市がどうであろうが、おれの市はこうやっていこうと。でも、これは法律がそう決めているわけであります。清掃事業を品川区なり２３区に持ってくるだけでも相当時間がかかってきたわけです。その制度がこの地方自治法にあるのだったら、そのことの法改正なりを区長会なりで真剣に考えていったらいかがかと思うんですが、どうでしょうか。","respondent":"高橋区長","answer":"「脱退はできない」「なぜできないんですか」、「２３区が合意をして決めたものだから、２２区の合意がなければできないんだ」という言い方です。それは法的に根拠があるわけですので、解釈の問題です。「では、わかりました。","voiceIndex":60,"id":"exchange-027"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、首長以下がこのことについて真剣に取り組んでいって、私の区はこういうようなことをしていきたい、だから人事制度をこうしていくんだというふうにはっきり物事を先立っていって、そういうふうにしたいがゆえに、今区長が言うような人事制度改革をしていくんだということを言い続けていかないといけないし、少なくとも品川区は先頭に立っていただきたいと考えています。","respondent":"高橋区長","answer":"今、そのようなものの考え方が順次浸透していくのではないかと思っています。一番端的なのは、千代田区が品川区と同じような歩調を取りつつあります。１区より２区、２区より３区というものの考え方、安易な人事、安易な労務交渉を考えるならば、統一交渉が一番楽です。","voiceIndex":62,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"私は９１ページの国際交流事業についてと人事も含めて職員研修費についてお伺いしたいと思います。初めに国際交流事業のことをお尋ねいたしますが、昭和５９年にアメリカメイン州ポートランド市の交流を始めてから今年で２０年目になると思いますが、それから国際交流都市も３都市に増えたと思います。初めに国際交流事業の現状についてお尋ねします。","respondent":"古川総務課長","answer":"現実にそういう形で、この十数年間実施してまいりました。","voiceIndex":65,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"交流の中で最も大切なのは、やはり人同士の交流だと思います。今、答弁の中で青少年がホームステイ等で交流しているということなんですが、青少年たちはどのような感想を持っているのか教えてください。","respondent":"古川総務課長","answer":"そういった意味におきましては、十数年間の中で三つの都市を主体としたホームステイを約３００名経験していますけれども、これからの成長の中で大きな糧になるのではないかと感じてあります。","voiceIndex":67,"id":"exchange-030"},{"speaker":"藤原委員","kind":"意見","question":"今、経済的にバブルが崩壊して、本当に厳しい経済情勢が続いておりますが、国際交流という形で他区などは交流を現状規模より縮小したりする自治体も多いと思いますが、品川区としては今後この事業に関してはどのような方向でいくのかお尋ねします。","respondent":"古川総務課長","answer":"そういう意味合いにおきましては、それぞれ都市との交流基盤は既にできつつありますので、これからの時代を担う青少年のホームステイ事業あるいは語学研修を中心に、そして区内におけるさまざまな外国の方との交流を柱に据えながら。","voiceIndex":69,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"私はこの事業は本当に長く続けていただきたいと考えています。情報だけいただくのであるならば、インターネット等で取れるかもしれません。本当にこれから交流という意味で、この事業は続けていただきたいという要望をします。続きまして、職員研修費についてお伺いします。品川区の研修として、特徴をお伺いしたいと思います。２３区の研修との違いがあれば、そこもあわせてお伺いしたいと思います。","respondent":"桑村人事課長","answer":"そのためには、各個人の能力をどうやって発揮させていくかということだろうと思います。私どもは、平成１４年度から研修プランニング制度を始めてあります。","voiceIndex":71,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"今回の一般質問で、「区長の区政に対する熱き情熱を職員にどのように示していかれますか」という質問をさせていただきました。そのときに区長が「失敗をおそれずにチャレンジ精神を持って行いなさい」ということを職員に伝えているということをおっしゃっておりましたが、その区長の思いは研修にどのようにあらわれているのでしょうか。","respondent":"桑村人事課長","answer":"そういう意味の反省も含めまして、職員につきましては積極的に課題に取り組むこと、そして新しい課題についてはチームワークあるいは管理職等のヒアリングを通して。","voiceIndex":73,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"今、管理職というお話が出ましたが、品川区において理事者の配置等を決めるのはどなたがなさっているのでしょうか。","respondent":"桑村人事課長","answer":"これは区長です。","voiceIndex":75,"id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"そこで質問なんですが、区長はどこの課にどこの部にだれを配置するかと考えられるかと思うんですが、決めていくプロセスというのがあると思うんですが、どのようなお考えでこの課はこの方がいいと決めていくのでしょうか。","respondent":"高橋区長","answer":"定期異動等を行う場合、権限は私にありますが私一人で決めるわけではございません。四役に集まっていただきまして、それぞれ意見を言っていただきまして、最後の決定は私がしています。そういう面では、四役会議が審議をする場になります。","voiceIndex":77,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"最後に一つ質問をしますが、品川区の職員の中で、夫婦で区の職員をやらている方がいらっしゃると思うんですけれども、多くはないけれども少なくもないと思います。人事配置といいますか、人事をするときに夫婦でやられているときに、どのような配慮をしているのでしょうか。","respondent":"桑村人事課長","answer":"ただ、これはかなり民間企業でもやられておりますけれども、同じ課に夫婦でいるというのは、やはり仕事の関係上、周りの職員も気にしますし、夫婦同士も仕事の関係がうまくいかないということがありますので、それについては外しているというのが現状です。","voiceIndex":79,"id":"exchange-036"},{"speaker":"本間委員","kind":"質問","question":"私からは９２ページの水と緑の市町村との交流事業、そして与えられた時間が短いのでそこまで及ぶかどうかわかりませんが、９６ページの区民施設費にいければという観点で質問します。","respondent":"宮地区民課長","answer":"は８事業ほど早川町を利用させていただきまして、実施している親子で田植え体験とか、渓流釣りとか、ホームステイとか、そういった事業がありますが、そちらの参加者の参加費をいただいた残りの部分を区が一定の助成をしておりますので、それらを合わせたものです。","voiceIndex":82,"id":"exchange-037"},{"speaker":"本間委員","kind":"意見","question":"早川町といいますと南アルプスということで、非常にネームバリューそのものがあるわけですけれども、品川区から行くということになりますと、遠い距離だな、交通の便で難があるなという部分を聞くわけですが、実際に私は縁がありまして今年に限っては３回ほど訪ねる機会がございました。その経験等も踏まえながら、再度進めします。今、行事の部分、利用状況についてお話がございました。","respondent":"宮地区民課長","answer":"そうした温泉と何よりも素朴な町の人たちの人柄、それから水と緑、そしておいしい食べ物、鍋料理で言いますとしし鍋料理がおいしくて、２月にはしし鍋料理、温泉めぐりとしし鍋料理を実施しております。","voiceIndex":84,"id":"exchange-038"},{"speaker":"本間委員","kind":"意見","question":"しかし、１回目は下見でしたけれども、２回とも地域の青年にあたる年代の四、五十代の４０名と、夏には子どもたちを中心とした地域のボランティアの団体４０名と２回行く機会がございました。それはどういうことかと言いますと、交通の便について難があるなと先ほど申し上げました。これまでは往復４００km圏内で非常に遠くの距離にある。","respondent":"宮地区民課長","answer":"区内点在ではなくて、２０名、３０名まとまってここから出発したいという場所がございましたら、言っていただければそこまでお迎えし、またお送りするということもやっていただきましたので、今後もそういった方向でＰＲをしていきたいと考えております。","voiceIndex":86,"id":"exchange-039"},{"speaker":"本間委員","kind":"確認","question":"足の便が非常によくなったです。２５ｍのプールがあります。当日２日間の間では雨は降りませんでしたけれども、雨天の際は体育館を利用できるということを確認してまいりました。夏には浅瀬のところが多いですから、「本来なら水をせき止めて魚などを放し、手づかみで子どもたちが遊べるようなこともできるけれども、残念ながら今年はできませんけれども」というお話もございました。","respondent":"宮地区民課長","answer":"先ほどの南アルプス号というバスもそうですけれども、なるべく多くの方に来ていただきたいということでバスを買い替えていただいて、品川区の皆さんの利便性のために考えていただいたという町長のお気持ちは、私たちも交流を進める上でありがたく思っております。","voiceIndex":88,"id":"exchange-040"},{"speaker":"本間委員","kind":"質問","question":"非常に物静かそうな感じですけれども、熱意がふつふつと伝わってくる姿勢を伺いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-041"},{"speaker":"須藤委員","kind":"質問","question":"その前に、どなたかの質問で区長の答弁の中に、長の判を押すのは事務方がやるので、私はわからないみたいな話があったように、私は耳が悪いのでその辺の理解がつかめなかったんですけれども、長として判を押すということを事務方がやるにしても、長としての責任はずっとついて回ると思うんですけれども、その辺はいかがでしょうか、私が勘違いをしているのか。","respondent":"高橋区長","answer":"失礼しました。私は直接な責任という意味でお話をさせていただきました。間接的な問題につきましては、当然長ですから責任があります。今回もその責任を取って理事長をやめたわけです。","voiceIndex":92,"id":"exchange-042"},{"speaker":"須藤委員","kind":"意見","question":"わかりました。防災センターを休日・土日に利用する方がいらっしゃると思うんですけれども、その方々がどの程度いらして、本庁舎のほうへは柵をしておいて立入禁止としているんですけれども、本庁舎のほうに対して事故があったかどうかということをお聞かせ願いたいと思います。","respondent":"久保田防災課長、西島経理課長","answer":"防災センターの利用ですけれども、現在防災センターは土日については閉館しています。第２日曜日だけあけて、シアターをご覧いただくようになってありますけれども、１日いらっしゃる方は数名という状況です。防災センターがあいている日に事故があったかというご質問ですけれども、防災センターがあいている日は３階の収入役室に渡るドアは閉めてあります。","voiceIndex":94,"id":"exchange-043"},{"speaker":"須藤委員","kind":"質問・要望","question":"そうすると、区民の方々の要望と庁舎管理という非常に難しい問題が入ってきてしまうと思うんだけれども、あそこは区民に対してこういういい形があるという一つのＰＲの場所です。そのためにはどういう方法を取るのか、あるいはこれから学校等でやっていくので、そういったところに見ていってくださいという方法を取るのか、ＰＲの仕方について教えたください。","respondent":"西島経理課長","answer":"屋上庭園ですけれども、委員ご指摘のとおりヒーリングということで癒しという部分ももちろんありますけれども、各ご家庭で屋上緑化をする際に参考となるようなものも展示していますし、また資料も置いてありますので、できればその部分についてもお役に立てればと考えています。","voiceIndex":97,"id":"exchange-044"},{"speaker":"須藤委員","kind":"質問","question":"ルーフ１、ルーフ２という形で表示してありますけれども、海外に行って見てきたら、ルーフガーデン（ＲＧ）という形でしっかり表示があるので、逆に下りるところもエレベーターの面にルーフガーデン（ＲＧ）という表示があるので、そんなことも考慮してもらうと、来る人たちがこうなっているなという一つの目安になると思うし、ルーフ２のほうはどうなっているのかなと思ってのぞきに行ったら。","respondent":"西島経理課長","answer":"Ｒ１、Ｒ２という記載になていますけれども、ご指摘のルーフガーデン（ＲＧ）という点については、今後検討してまいりたいと考えています。それから、Ｒ２ですけれども、基本的に機械室になってございまして、そのための入り口という形になってあります。","voiceIndex":99,"id":"exchange-045"},{"speaker":"須藤委員","kind":"意見","question":"臨海部広域斎場ですけれども、９月に建築の入札が終わったんですけれども、このときの入札の仕方が、普通ですと何点以上という基準で来るんだけれども、何点以下でというつくり方をしたことに対して、いかがお考えかということと、入札の落札率が９８.５％という数字自体はどういうふうに考えていらっしゃるかお聞かせ願いたいと思います。","respondent":"宮地区民課長","answer":"９８.８％ということですけれども、これも実際にはかなり予算に近い形での契約金額であったわけですけれども、これにつきましてはきちんと執行をしたということを業者を呼びましてヒアリングと、それから一定の質問表を出しまして、それについて回答してもらったところ。","voiceIndex":101,"id":"exchange-046"},{"speaker":"須藤委員","kind":"質問・要望","question":"中小企業の育成自体はいいんだけれども、その辺のところでもう少し方法があったのではないかなという思いがします。これから運営だとか、そこで売るものだとか携わってくると思うんですけれども、それに関してもほかから見ておかしくないよ、やはり品川区もそれなりの関心を持っているわけですから、そういった方向へ進んでいっていただきたいと思うんですが、いかがでしょうか。","respondent":"宮地区民課長","answer":"いよいよ運営ということになってまいりますので、この運営の方法につきましても一般競争入札になるのか、プロポーザル方式になるのか、こちらについても５区の協議会の中で検討しながら進めてまいりますが、だれから見てもおかしくないような形で。","voiceIndex":103,"id":"exchange-047"},{"speaker":"藤田委員","kind":"質問・要望","question":"私からは３点お伺いしたいと思います。９２ページの庁舎管理に関する質問、２番目に９４ページのＣＡＴＶに関する質問、３番目に９１ページの夜間・休日の宿日直の関係です。例えば、商店街のイベントが放映されているんです。それから、宿日直の関係ですが、仕事の内容とどういう体制でだれが行っているのか、その辺をまずお伺いしたいと思います。","respondent":"西島経理課長、山田広報広聴課長、古川総務課長","answer":"２点目の自動販売機ですけれども、都税のところに置いてあるものも含めまして、自動販売機は６台あります。そちらのほうに商店街の連合組合と連携を取りまして、各商店街を紹介していくという手法を取って放映していると伺っておりますので。宿日直の仕事内容と体制ですけれども、庁舎の閉庁時あるいは休日等の一般的な区民対応です。","voiceIndex":107,"id":"exchange-048"},{"speaker":"藤田委員","kind":"質問・要望","question":"自動販売機は６台あると、電気はつけっ放しなんですね、電気量はかなりかかっているのではないかと思いますけれども、この辺の仕組みはどういうふうにされているのか、６台をどこがどういう管理でどういうふうに設置しているのか、その辺の経過を教えていただきたいと思います。と言いますのは、夜間・休日というのは緊急な対応を求められているのではないかと。","respondent":"西島経理課長、古川総務課長","answer":"そうしますと、大変膨大な金額がかかりますので、すぐには難しいかなと思いますけれども、確かに委員ご指摘のとおり清潔指向ということで、健康にもいいということもありますので、少し研究をさせていただきたいと考えております。そういう観点から、委託等ということにつきましては、現在警備の職員１名を委託で宿日直業務にあたってありますけれども、さまざまな対応を考えていく中では、区職員ＯＢ等の経験のある者について一定の対応ということも。","voiceIndex":111,"id":"exchange-049"},{"speaker":"藤田委員","kind":"質問・要望","question":"温水洗浄便座については、すべてのトイレに全部つけろと言っているわけではなくて、清潔と職員の健康を考えて各フロアの男女１カ所ずつぐらいはつけていいのではないか思っているんですけれども、その辺はまた考えを聞きたいと思います。これについて品川区はどのようなお考えなのか、お聞かせいただきたいと思います。最初の２点だけお伺いしたいと思います。","respondent":"西島経理課長","answer":"ほとんどの家庭が温水洗浄便座になってきているということもありますので、どういうふうにつけるかということも、あそこだけついてここだけつけないという問題、利用勝手の問題も出てまいりますので、その部分も含めて検討してまいりたいと考えています。","voiceIndex":114,"id":"exchange-050"},{"speaker":"上山委員","kind":"質問","question":"９８ページの住民基本台帳費、住基ネットの関係で幾つか質問します。質問します。最初に、住基ネットそのものですが、一番最初に考えていた目的はどういうことが想定されていたのでしょうか、それが１点です。それから、お金の問題なんですけれども、勉強不足で申し訳ないですけれども、全部品川区の負担になっているのか、その辺も教えていただければと思います。","respondent":"冨田戸籍住民課長、市岡企画財政課長","answer":"これに関するシステム開発、主にテスト関係ですけれども、それが平成１５年度の予定です。ランニングコストですけれども、額は今後決めることになりますけれども、大体１，０００万円ぐらいかかる予定です。今の戸籍住民課長がご説明した残りの部分については、財調で措置をされてあります。","voiceIndex":117,"id":"exchange-051"},{"speaker":"上山委員","kind":"質問","question":"品川区で新しく条例を出そうとしているんですけれども、セキュリティーの関係で少し伺いたいんです。セキュリティーの対策を取り始めていると聞いているんですけれども、これで漏洩の問題だとか不適正使用の問題が解消される、あるいは大丈夫だという保障についてはいかがでしょうか。","respondent":"田中情報システム課長","answer":"その辺のところでは、人間のやっていることですから絶対ないとは言い切れないところがありますが、それぞれポイントになるところについては、きちっと対応した体制と規定整備、教育研修等を含めて体系的に行っているところです。","voiceIndex":120,"id":"exchange-052"},{"speaker":"上山委員","kind":"提案","question":"５３号議案を総務委員会でも審議されているところかと思いますけれども、これは私の感想です。目的の第１条なんですけれども、「もって住基ネットの運用に対する区民の信頼を確保することを目的とする」。こういうところに区民を守るためにだとわかるんですけれども、住基ネットをというとどうなのかなと思うので、今度の条例提案した基本的な考え方を説明いただけませんでしょうか。","respondent":"山田広報広聴課長","answer":"総務委員会でもご説明をさせていただきましたけれども、今回提案をしています条例につきましては、現在施行しております品川区情報公開個人情報保護条例を基本として、特に住基ネットの運用にあたって、区民の皆様方のさまざまな不安の声に迅速にお答えをしていくということで。","voiceIndex":122,"id":"exchange-053"},{"speaker":"上山委員","kind":"質問","question":"品川区に対して、この間住基ネットがスタートしてから１，３００件ぐらい意見が寄せられてということで、区民の方がいろんな心配をするのは、ある意味では不思議はないかと思うんです。そういう意味で言えば、非常にバラ色だけえがくのではなくて、「大丈夫です」と言われると、その辺でいまいち心配なんですが、そういう問題はないのでしょうか、もう一度答弁をお願いしたいんですが。","respondent":"田中情報システム課長","answer":"その点で危険だからネットワークを使わないということは、今の中ではちょっと難しいと考えております。その点でいろいろクリアするためにセキュリティーの技術、暗号化ですとかを含めて取られています。","voiceIndex":125,"id":"exchange-054"},{"speaker":"上山委員","kind":"質問","question":"いろんな決意をお聞かせいただきました。大事なプライバシーが侵害される可能性もあるということで、区は条例をつくってやっていることは評価していると述べたとおりですから否定はしません。ただ、そういう危険性があるという点で、危険性があるからつくったと思うんです。","respondent":"田中情報システム課長","answer":"一応、緊急性のレベルについては、内部の規定の中で３レベルに分けております。","voiceIndex":127,"id":"exchange-055"},{"speaker":"上山委員","kind":"意見","question":"今の関係をお尋ねして終わりにしたいんですけれども、システムの切断などを含めて考えているということですが、区民あるいは国民的な問題になっている中で、区民の情報を守るためにこういうことをやるんだということなのか、そこのところだけお願いしたいと思います。","respondent":"中尾根企画部長","answer":"情報社会における宿命は、セキュリティー対策をどうしていくかということです。これは総合的に対策を取るということがベストの状況ですので、そのことを目指して頑張っていきたいです。","voiceIndex":129,"id":"exchange-056"},{"speaker":"田中委員","kind":"質問・要望","question":"私は９４ページの広報費全般についてお伺いしたいと思います。情報弱者ということがよく言われておりますが、情報弱者が今後もますます増えていくということで、広報という観点から情報弱者対策というのでしょうか、弱者と言われるのは特に高齢者が対象になってくると思いますが、まずその辺の広報としての考え方をお聞かせいただきたいと思います。","respondent":"山田広報広聴課長","answer":"そこに着目いたしまして、今回はホームページの全部はとても無理ですから、緊急性のある内容について携帯電話にも対応できるようにシステムを開発しておりますので、ご理解いただきたいと思います。","voiceIndex":132,"id":"exchange-057"},{"speaker":"田中委員","kind":"質問・要望","question":"今後、ＩＴ化が進む中で、平成１４年度はひとり親家庭のパソコン教室とか障害者向けというものもありますが、さらなる今後の情報弱者対策ということも含めまして、ぜひ力を入れていくべきだと考えていますが、その点再度お願いしたいと思います。","respondent":"田中情報システム課長","answer":"ただ、低所得の方等を含めて、この辺のところについては既存の機器等を使って何らかの対応を検討していく必要があると思いますし、身近なところで公開端末みたいなところで利用できる環境を整備することも課題だと考えております。","voiceIndex":134,"id":"exchange-058"},{"speaker":"田中委員","kind":"質問・要望","question":"一つ例にとって申し上げたいんですが、今も議論の出ておりました住基ネットの問題は大切な問題で、品川区としても慎重に取り組んでいらっしゃるんですが、このことに関してホームページはどこに載っているのかと見たところ、住基ネットですから区民生活事業部のホームページに載っているかと思ったら載っていなくて、最新情報というところに８月２６日付で。","respondent":"山田広報広聴課長","answer":"その中では、区民の皆様方の声もありますけれども、分析をさせていただいた結果として、掲載の内容、条文をその中でご紹介していきたいという予定を組んでおります。","voiceIndex":136,"id":"exchange-059"},{"speaker":"田中委員","kind":"意見","question":"さらにＩＴ化が進む中での情報伝達あるいは情報管理ということで、ぜひ受け手の立場に立った管理をぜひお願いしたいと思います。まだ、たくさんありましたが、これで終わらします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":138,"id":"exchange-060"},{"speaker":"山路委員","kind":"質問","question":"私自身も話している途中で、ぷつんと切れたりするんですけれども、アンテナ設置についてはどのようになっているか教えていただけますでしょうか。","respondent":"西島経理課長","answer":"これだけ携帯電話が普及してまいりますと、どこでも携帯電話が使っていいかという別の問題もありますけれども、一度機械的な部分について調査をして確認してまいりたいと思ってあります。","voiceIndex":140,"id":"exchange-061"},{"speaker":"山路委員","kind":"質問・要望","question":"一部ということですけれども、かなり古くなっているとかいろんなことが考えられますので、調査検討されて整備をしていただくようにお願いをしておきます。奨学金につきまして、悩んでいる方もいらっしゃるんです。そこで、何点かお伺いをしたいんです。１点目は、現在何人ぐらいの方が利用され、また利用対象の方たちにはどういう周知をされているのかお聞かせいただきたいと思います。","respondent":"宮地区民課長","answer":"現在の貸付者数ですが、平成１３年度決算数字で２６８人です。それから、全体の貸付総数は２，６４２人ですが、その中でも完了が１，１７８人ありますので、貸付者数は２６８人、完了した人を除きまして返還中の方たちが１，０１８人いらっしゃるです。","voiceIndex":142,"id":"exchange-062"},{"speaker":"山路委員","kind":"質問","question":"利用実態と周知方法はわかりましたけれども、学校でお話はされていると思うんですけれども、父兄の方が意外とご存じないといいますか、子どもが聞いて父兄に伝えるということが少ないといいますか、保護者が知らないということで、基準、規則についていろいろ相談を受ける場合があるんです。そこで、基準、規則はどのようになっているか、もう一度教えていただけますでしょうか。","respondent":"宮地区民課長","answer":"ただ、やり方としましては、申込みいただきましても途中で貸付審査会がありますので、そこで審査をした上で決定をするということが内容として書いてありますので、その他については相談に応じるということでお話はしています。","voiceIndex":144,"id":"exchange-063"},{"speaker":"山路委員","kind":"質問・要望","question":"答弁なされた中で悩んでいる方がいらっしゃるので、その内容をちょっと申し上げます。今年の１月に失業して、子どもの高校進学のための入学金の都合がつかなくなり、品川区の奨学金貸付制度の窓口へ相談に行ったという方の悩みです。例えば、２月、３月が一番多いと思うんですけれども、１１月に締切というのは何か理由があるのでしょうか、そこを聞かせていただきたいと思います。","respondent":"宮地区民課長","answer":"入学準備金と申しますのは、来年度進学をされる方がその準備のために必要だという金額になってまいりますので、基本的には申込むまでの１１月までの間に、どういう高校を目指しているのか、公立なのか私立なのか、そういったところが決まってくるです。","voiceIndex":146,"id":"exchange-064"},{"speaker":"山路委員","kind":"提案","question":"公立はぎりぎりになって入学金を払うというパターンが多いですので、やっぱり借りに来る人は緊急性、利便性を求めて奨学金制度を活用したいということですので、１１月末に締切るのではなくて４月上旬といいますか、入学ぎりぎりまで考慮していただきたいと思いますけれども、どのようにお考えでしょうか。","respondent":"宮地区民課長","answer":"基本的には大多数の方は１１月８日の中でおさまってくるというふうに考えますが、例えば公立の場合ですと、入学準備金は７万円、私立ですと２０万円ということになりますが、７万円のお金がないばかりに進学すらできないという、非常に特例というと極端かもしれませんが。","voiceIndex":148,"id":"exchange-065"},{"speaker":"山路委員","kind":"質問","question":"ご丁寧な答弁みたいに感じますけれども、１万円、２万円のことで、支払いができなくて非常に悩んでいる切実な方が現実にいらっしゃるわけです。子どもが直接借りて、親に迷惑かけないという意思で、そういう方たちの思いを奨学金制度で、将来の偉大な品川区の人材になる可能性のある方たちですので、そういう思いで独自のサポート制度をつくるべきではないかと思いますけれども、どのようにお考えでしょうか。","respondent":"宮地区民課長","answer":"私もそういう思いは同じです。ただ、方法としましていろいろ考えられるかと思います。","voiceIndex":150,"id":"exchange-066"},{"speaker":"山路委員","kind":"質問・要望","question":"保護者も一緒に相談に行きまして、保護者が品川区は話にならないと怒っていたパターンもありました。どうしてもこの制度をできないという壁があるのでしょうか、その辺についてもう一度お聞かせいただきたいと思います。","respondent":"宮地区民課長","answer":"基本的な制度は制度としてある中で、特別な方法としてそういうことができるかどうかにつきまして、研究をさせていただきたいと思っていますので、ご理解のほどをお願いします。","voiceIndex":152,"id":"exchange-067"},{"speaker":"山路委員","kind":"質問","question":"課長の顔がだんだん真剣になられてきたから、区民の方の思いが伝わったかと思います。どうぞよろしくお願い申し上げます。喜ばれているわけですが、現場に行きますと現実に泥棒に入られたとか、危険を感じているとかあるんです。これは警察がやるべきことだと思いますので、非常に難しいと思うんですが、この辺について研究・検討をお願いしたいわけですが、どのようにお考えになっているでしょうか。","respondent":"長田地域活動課長","answer":"先頃の一般質問にもお答え申し上げましたけれども、なかなか犯罪については区が責任を持って実施できる部分が少ないということがありまして、現実問題としてアドバイザーを設置しても、いかにしていくのかというようないろいろな問題があろうかと思います。","voiceIndex":154,"id":"exchange-068"},{"speaker":"金高委員","kind":"質問","question":"私は用地特別会計ならびに総務費の中の防災関係について、質問します。平成１３年度決算書の２２４ページの中に、一般会計から繰入金として７億３，４３１万円あまり実際に出ているわけでありますし、決算でもそのまま公債費として支出されているわけです。最終的には１２億１，４００万円あまりは補正になっておりますけれども、その辺の当初の考え方と決算の考え方をお聞かせ願いたいと思います。","respondent":"市岡企画財政課長","answer":"今回の決算は、返すほうのお金については予定どおり返したんだけれども、新しく買う土地については該当する用地がなかったので、補正で財産取得費については全額を落としたという内容の決算になっております。","voiceIndex":157,"id":"exchange-069"},{"speaker":"金高委員","kind":"意見","question":"これでいきますと約７億７００万円の元金と約２，７３１万５，０００円の利子ということで合計で出てくると思うんですけれども、この分については何年度の分についての償還になっているか、それをお聞かせ願いたいんです。","respondent":"市岡企画財政課長","answer":"これは平成４年度に大森貝塚の遺跡公園整備、それから小山六丁目公園、江戸見坂公園だと思いますが、この二つの物件を用地会計で買いました。これの償還経費としての公債です。","voiceIndex":159,"id":"exchange-070"},{"speaker":"金高委員","kind":"意見","question":"この部分が平成４年でありますから、ちょうど１０年前という形になると思います。それらについてはまたの機会にしますけれども、平成４年度あるいは５年度とずっと来ていると思うんですけれども、まだ残っている残債の債権があるのかないのか、あるいはこの時点である程度終わりになってくるのか、その辺のところをお聞かせください。","respondent":"市岡企画財政課長","answer":"用地会計で起債をした残債ですが、ちょうど平成１３年度決算ですべて返し終わりまして、平成１４年度からは公債費として返す必要はないです。","voiceIndex":161,"id":"exchange-071"},{"speaker":"金高委員","kind":"意見","question":"こちらのほうに平成１３年度元利償還金が６３億２，２４８万円あまり出ているわけですけれども、当然この中に今回の公債費７億３，０００万円あまりが含んでいるのかどうか、それもあわせてお聞かせ願いたいと思います。","respondent":"市岡企画財政課長","answer":"決算委員会の資料としての一覧表は、一般会計と用地会計をすべて含んだ総計の内容です。委員、ご指摘のとおりです。","voiceIndex":163,"id":"exchange-072"},{"speaker":"金高委員","kind":"意見","question":"そういたしますと、この中に出ております平成１３年度６３億円あまりが実際に返還されているわけですけれども、成果報告書の決算状況一覧表の中にあります目的別歳出の中で公債費の項目があります。ここの数字を見てみますと、目的別では５９億８，５００万円あまり、性質別では５９億７，７００万円という形で若干数字が違うんですけれども、この辺の違いを説明していただけますか。","respondent":"市岡企画財政課長","answer":"元金および利子の計算は全く同じですが、成果報告書のほうはこれに支払事務費等が入ってありますので、その事務費分だけが違うです。","voiceIndex":165,"id":"exchange-073"},{"speaker":"金高委員","kind":"意見","question":"若干の数字の違いがあるのはわかりました。目的別、性質別の中において違いがあるということと、特別区債償還計画表の元利合計の差というのは事務費であるということで認識すればいいかどうかお願いします。","respondent":"市岡企画財政課長","answer":"そういうことで各会計を整理する物差しがいろいろ違いますので、若干数字が違って出てまいりますが、全体としてはそういう構造になってありますので、よろしくお願いいたします。","voiceIndex":167,"id":"exchange-074"},{"speaker":"金高委員","kind":"質問・要望","question":"続きまして、防災につきまして質問します。固定型として６３９局、移動型１２３局ありますけれども、町会関係においては２０５町会がそれぞれ数字に出てくるわけですけれども、固定型の部分について、それ以上の各学校とかあると思うんですが、固定型・移動型の主だった内容等についてお知らせ願いたいと思います。","respondent":"久保田防災課長","answer":"もう一つ地域防災無線局というのが３６局ございまして、地域センター、警察・消防の関連団体の中に配備しているという状況です。","voiceIndex":169,"id":"exchange-075"},{"speaker":"金高委員","kind":"質問","question":"例えば、無線ですから周波数等いろいろあると思いますし、発信するときに受信するほうの受信機材、例えば水のよく出るところとか、あるいは目黒川あるいは立会川近辺の方で、そういう情報をいち早く察知したいといったときに、自分で費用を出してもいいから区の防災無線を自宅で傍受したいという希望があった場合に、そういうことが可能なのかどうか、技術的な面も含めてお聞かせ願いたいんですが。","respondent":"久保田防災課長","answer":"したがいまして、現在個別受信機の中で配備しておりますけれども、聞こえないという部分につきましては、先ほど答弁しましたけれども、ほかにもっと効果的な方法がないかどうかも、今後検討していきたいと考えているところです。","voiceIndex":171,"id":"exchange-076"},{"speaker":"金高委員","kind":"質問・要望","question":"そういう面でしますと、やはりここの費用は全部配備することは不可能ですけれども、個人が購入して情報をいただきたいというのであれば、当然内容的には狭まった受信であると思いますけれども、それについてもぜひ前向きに考えて、そういうことができるのかどうかも含めて検討していただきたいと思います。次に、防災ポンプと防災資機材を格納する倉庫等についてお伺いします。","respondent":"久保田防災課長","answer":"ただ、どうしても適当な場所が見つからないという場合につきましては、１町会１カ所、５m2の範囲内で公園等の一部を貸しているという状況です。","voiceIndex":173,"id":"exchange-077"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私からは総務管理費の中から国際友好都市交流、水と緑の市町村との交流、奨学金関係、すべて今までの質疑に出ているので違う観点から質問させていただきたいと思います。その方だけでなく全体を考えた場合、迎え入れた方たちに対して、例えば終わってからでも感謝状みたいなものがどこかから出ないかなという質問です。","respondent":"古川総務課長","answer":"いずれにいたしましても、そういうことにつきましては今後ともホストの方々にご負担のかからないように、そして私どもの誠意をもって対応していきたいと考えています。","voiceIndex":176,"id":"exchange-078"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"２点目に、水と緑の市町村との交流事業ということで、決算特別委員会ということで数字面で確認をさせていただいたんですが、山北町の交流負担金が１，２５８万円出ております。何かもうちょっとつなげて広く、検討材料としてはＣランクになっているということはお聞きしておりますが、せっかくの機会、地域として何かできないのかなということでお答えをお願いしたいと思います。","respondent":"宮地区民課長","answer":"東大井、松田町、山北町のつながりですけれども、ご提案は確かにそういったつながりもあるのかなと考えていますが、山北町との交流そのものを見直す段階に来ております。そうした中で、全体を含めて検討させていただきたいと考えています。","voiceIndex":178,"id":"exchange-079"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ、見直しと同時に進められるときは考えていただければ、産業振興という意味で大井町と大井銀座で、このまえバス２台に向こうに行って、向こうも町長はじめ助役、収入役、皆さんが歓迎してすごい対応でした。その辺だけ頭に入れていただければと思います。ぜひ考えていただきたいということで、よろしくお願いします。その辺の状況がわかるかどうか。","respondent":"谷田部学務課長","answer":"私立中学校から区立中学校への転校ですけれども、今年度におきましては９月末現在で８件あります。平成１３年度で申し上げますと１２件、平成１２年度が１２件という状況になってあります。","voiceIndex":180,"id":"exchange-080"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そういう場合、義務教育ですから奨学金という形はないのと同時に、公立に行くか私立に行くのかという問題もあるかとは思うんですが、何か支援体制が取れないのかなという質問です。厚生労働省の子育て支援ということで、奨学金という問題が出たと思うんですが、その辺で何か対応策はないかお答えをお願いしたいと思います。","respondent":"宮地区民課長","answer":"そうした中で、奨学金制度そのものはＣですので、先ほどの件も含めまして、そろそろ社会状況もあわせまして見直すこと必要だと考えておりますので、その中で検討てまいりたいと思います。","voiceIndex":182,"id":"exchange-081"},{"speaker":"辻委員","kind":"質問・要望","question":"昨日に引き続きまして、住民基本台帳の閲覧制度について確認しておきたいと思うんです。閲覧については住民基本台帳法第１１条で定められておりますが、平成１１年に何点か改正されております。現実問題として、実際上はどういうことが行われているのか、決算書でもそれなりの費用で実績として上がっているわけですので、概略を説明していただきたいと思います。","respondent":"冨田戸籍住民課長","answer":"住民基本台帳法の閲覧制度ですけれども、住民基本台帳法の前の旧法に住民登録法というものがあります。これは昭和２６年にできて、現在の住民基本台帳法は昭和４２年にできたものです。閲覧制度は旧法の住民登録法の時代からあります。原則公開ということで来ております。","voiceIndex":185,"id":"exchange-082"},{"speaker":"辻委員","kind":"質問","question":"例えばダイレクトメールあるいは名簿を使って、私たちだったらニュースレターみたいなものをつくって送りたいけれども、こういう地域の人についての住所氏名を知りたいといった場合は可能なんですか。","respondent":"冨田戸籍住民課長","answer":"詳しくいろいろ聞くことになると思うんですけれども、基本的には可能であると思われます。","voiceIndex":187,"id":"exchange-083"},{"speaker":"辻委員","kind":"確認","question":"だから、個人を特定するということの意味あいというのはどういうことなんでしょうか。土井委員のところも閲覧することは可能だということと、固有の人のプライバシーを特定するときにやる、先ほど言ったように「こういう人は住んでいるんですか、どうなんですか」とやったときの確認する場合は微妙だという、この辺の線引きはどういう形になっているんですか。","respondent":"冨田戸籍住民課長","answer":"資料提供を求めることもできますので、市場調査ということであれば、どういった形の依頼文を出す予定なのか、そういったあたりは書類があれば当然出していただくという形で事務は取っております。","voiceIndex":189,"id":"exchange-084"},{"speaker":"辻委員","kind":"確認","question":"私はこの問題と住基ネットのオンラインの部分は、改めてどこかの機会でやりたいと思っているんですが、個人情報の問題とこれから電子自治体、電子政府というＩＴ時代になっていったときに、個人をどう特定して本人確認をするかという問題と、同じ情報が使われながら、片一方ではある部分オープンにされて社会生活の中でいろいろな形で使われる。","respondent":"太川区民生活事業部長","answer":"今の件ですけれども、住民基本台帳法第１１条のところで、一部写しの閲覧が可ということになってあります。今、課長から状況につきましてはご説明申し上げましたけれども、閲覧そのものが本人確認情報とほぼ一致している部分です。","voiceIndex":191,"id":"exchange-085"},{"speaker":"辻委員","kind":"質問・要望","question":"もう一つ、今言った住基ネットという新しい制度が入ってきて、もう一つは電子自治体、電子政府ではネットワーク社会の中で、どう個人を認証していくかという大きな課題の過渡期だと思うんです。そういう面で、ただ昔からの部分である閲覧制度の中でもきちっとした形を、ぜひお願いしたいということを要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":193,"id":"exchange-086"},{"speaker":"桜井委員","kind":"質問","question":"私のほうから２点質問します。それから、その関係で委員の公募についてと情報公開について、どういうふうにそれぞれの機関として位置づけられているのか、基本的なといいますか統一的な考え方をまずお聞きしたいと思います。","respondent":"山田広報広聴課長","answer":"ただ、審議会につきましては、それぞれの所管が持っている目的別の審議会ですので、法に基づいて審議をしている例えば社会教育委員会というものありますので、それは個々について目的を持って実施をしているということでご理解いただきたいと思います。","voiceIndex":195,"id":"exchange-087"},{"speaker":"桜井委員","kind":"意見","question":"一番直近では今年の９月３０日に制定されている規則の改正があって、都市計画審議会では議事録の公開と会議の公開となっているわけです。例えば２２の附属機関のところで、委員の公募を改正されてやっているところがあるのかどうか。それから、情報公開の関係では会議録の公開とか、実際には条例を改正しないまでもやっているところがあるかどうか、それを聞きたいと思います。","respondent":"山田広報広聴課長","answer":"ほかの審議会については、それぞれの所管ということになっておりますのでお答えしかねるんですけれども、情報公開等審議会におきましては、内規の部分ということでかなり個人の識別情報を取扱う関係で、傍聴等の公開は難しいということ。","voiceIndex":197,"id":"exchange-088"},{"speaker":"桜井委員","kind":"質問・要望","question":"例えば、議事録をいただきたいと申し出た場合には、そういうふうに判断をするところもあるし、なかなか判断を示さないところもあるし、しかも大事な検討されている区民の声を聞く、あるいはそこで積極的に改善をしていくという場合になれば、ぜひ附属機関、さらに最近つくられた８カ所でしょうか、そういうところでの区民参加あるいは情報公開について。","respondent":"古川総務課長","answer":"全体を統括しているところはあるのかというお尋ねでしたので、必ずしも総務課というわけではございませんけれども、附属機関についての基本的な考え方は、条例あるいは法律等に基づく機関ですので、基本的には先ほど来から議論になっております委員の構成において。","voiceIndex":199,"id":"exchange-089"},{"speaker":"桜井委員","kind":"質問","question":"先ほどご紹介申し上げた都市計画審議会の１点だけ聞きたいんですが、審議委員のメンバーからの情報提供については、どういうふうに基本的にお考えになっているのでしょうか、お答えください。ですから、どれだけ開かれた区政にしていくのか、どれだけ区民の意見を制度として確保していくのかということが基本だと思いますけれども、その考え方についてお知らせください。","respondent":"山田広報広聴課長、伊佐都市計画課長、中尾根企画部長","answer":"しかしながら、非公開の情報もあるというところで、９条の中にホとして、「実施機関の附属機関等である合議制の会議に係る情報であって。都市計画審議会の議事録の公開についてご質問がございました。１０月１日より都市計画審議会の規則を改正しまして、会議の公開を原則といたしました。方向につきましては、公開制ということをより明確に、区民の参加というものをより充実させていくという方向は間違いございませんけれども。","voiceIndex":201,"id":"exchange-090"},{"speaker":"桜井委員","kind":"提案","question":"時には非公開ということもあると思いますので、ぜひ開かれた区政にということで、一歩、二歩進めていただきたいと思います。次に、防災センター絡みで９５ページをお聞きします。議会側でもいろいろ利用もさせていただいて、感謝しているところですけれども、ぜひ提案申し上げたいのは、防災センター３階の展示室を区民に開放していただきたいということを申し上げたいんですけれども、いかがでしょうか。","respondent":"久保田防災課長","answer":"防災センター３階の活用ですけれども、これまでも３階についてどういうふうに考えていくのかというご質問をいただいて、検討をしていくということがあったかとは思います。","voiceIndex":205,"id":"exchange-091"},{"speaker":"桜井委員","kind":"質問","question":"実際に区民の施設でありますし、かなり多額な投資をして、そして３階の利用は皆さんもご苦労されて使っていると、私たちもよく見ております。実際、６月、７月、８月はいろいろと水害等の関係があるので、それとそれとしてわからないではありませんけれども、検討委員会をつくって、その結果防災の機能だけという結論なんでしょうか、どういうことなんでしょうか。","respondent":"久保田防災課長","answer":"いろいろなことを検討したわけですけれども、やはり防災的な機能をまず継続していこう。","voiceIndex":207,"id":"exchange-092"},{"speaker":"桜井委員","kind":"質問・要望","question":"改めて、区民の利用に供していただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-093"},{"speaker":"松澤委員","kind":"質問","question":"３点にわたってお聞きしたいと思います。１点目ですけれども、９３ページの品川区町会・自治会館建設補助費３４４万６，８９６円。平成１３年度の町会会館の補助は建設がどのぐらいあったのか、あるいは葬祭補助なのか、内容をお聞きしたいと思います。","respondent":"長田地域活動課長","answer":"平成１３年度の地域活動基盤整備補助事業ですけれども、町会会館建設につきましては、平成１３年度は０件でございました。それから、葬祭設備助成が８件、町会・自治会館登記助成が４件、こういった件数になってあります。","voiceIndex":212,"id":"exchange-094","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問","question":"すべての町会・自治会に会館があるわけではないですから、それぞれないところもあるということで、このような形での助成だと思うんです。実は私のところに今年２件ばかり相談に来ています。そうしますと、出てもらったものですから、すぐまたお金をかけて葬祭設備をする。要綱をもらって見てみますと１０年と書いてあって、想定の仕方というのが、普通木造の建物だとだめになるのが２０年ですか。","respondent":"長田地域活動課長","answer":"そういう意味におきましては、建設をして例えば３年経って、またこの制度が使えるかということになりますと、現状では難しい、無理であるということでお答えをします。","voiceIndex":214,"id":"exchange-095","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問・要望","question":"そのときにやはり木造よりお金がかかる、また耐用年数も長いということで、耐火建築の場合は町会そのものが災害のときの拠点、学校に何だかんだ逃げるんだといっても、その前に町会に集まってという話があるものですから、耐火建築の場合の助成を考えられないでしょうか、お願いします。","respondent":"長田地域活動課長","answer":"１点目の、区長特認事項で何とか補助できないものだろうかですけれども、現状は先ほど申し上げました１０年で運用していますから難しいですけれども、確かに考えてみれば、この間台風２１号もございましたけれども、例えば町会会館が地震ですとか台風。","voiceIndex":216,"id":"exchange-096"},{"speaker":"松澤委員","kind":"質問","question":"９５ページの防災関係でしょうか、ＣＡＴＶ関係でしょうか、昨年の決算特別委員会の中で我が党の鈴木委員が、ＣＡＴＶで５チャンネルで何かできないのという話の中から、今年の７月からＣＡＴＶで放送されるようになりました。大変好評なんです。私も消防団員ですから、自宅待機ということで水防本部からかかりますとずっと待っているんですけれども、その間それを見ながら情報を取っているんです。","respondent":"矢部下水道河川課長","answer":"こういう課題もありますけれども、戸越幹線の水位情報をケーブルテレビに掲載するにつきましては、もう少し時間をいただきまして、検討させていただきたいと思います。よろしくお願いします。","voiceIndex":218,"id":"exchange-097"},{"speaker":"松澤委員","kind":"質問","question":"何か課長から力を込めて「よろしくお願いします」と言われましたけれども……。実は一番心配しているのは、確かにリアルタイムでやるというのではなくて、ワンクッション置いてもいいと思うんですけれども、都の下水道局から水防本部に直結して情報が入るのかどうか。その点、はっきりここへ来るんだという証明ができるんでしょうか。","respondent":"矢部下水道河川課長","answer":"ただ、それをケーブルテレビに送るにあたっては、かなり水位変動が大きいものですから、たびたび危険水位を突破したとか、警戒水位を突破したと、そのたびに画面が極端に変わる可能性がありまして、その辺の技術的な問題をもうしばらく検討させていただきたいというわけです。","voiceIndex":220,"id":"exchange-098"},{"speaker":"松澤委員","kind":"質問・要望","question":"よくわかりました。しかし、一番大事なのは水があふれると言ってあふれなかったというよりも、情報がなくてあふれるほうが区民にとっては大変なので、その辺を考えていただきたいと思います。３番目は９８ページの選挙啓発費に関連して、実は電子投票なんです。","respondent":"野田口選挙管理委員会事務局長","answer":"最高裁の国民審査を含めて五つの投票をするということであれば、すごく効果を発揮するとは思ってありますけれども、先ほど申しましたように、不在者投票の問題、国政への適用の問題、それからコストも見積もったところ２億５，０００万円から３億円といったことで。","voiceIndex":222,"id":"exchange-099"},{"speaker":"松澤委員","kind":"質問","question":"リースもあるわけですから、買い取りの値段からいうとやる気がないのかなという気がしたんですけれども。２３区横並びではなくて、品川区独自でやれるということがあるのでしょうか、時間がないので、その１点だけ聞いて終わりたいと思います。","respondent":"野田口高齢事業課長","answer":"これは条例で定めれば、品川区独自でできます。","voiceIndex":224,"id":"exchange-100"},{"speaker":"北野委員","kind":"質問","question":"私は９１ページの人権啓発費、９４ページのイメージアップ経費、９８ページの住民基本台帳ネットワーク開発費、この３点についてお伺いします。１点目の人権啓発費ですけれども、こちらが「男女共同参画社会を目指す品川プラン」ということで、行動計画の推進会議のほうで作成されていますが、現在の進捗状況をお伺いいたします。","respondent":"阿部人権啓発課長","answer":"委員ご指摘のとおり、今、行動計画推進会議のほうで、第９期で検討しています。来年の３月末に第９期の行動計画推進会議のほうから提言をいただくという予定で、行動計画推進会議で盛んに議論していただいているという状況です。","voiceIndex":227,"id":"exchange-101"},{"speaker":"北野委員","kind":"質問","question":"事務事業評価ではＢになっているということで、Ｂの評価は事業方法の新たな工夫が要するが事業水準を維持する場合という評価なんですが、こちらは２年任期で公募の方たちが入られて運営されているわけですから、運営のされ方のどこが見直しが必要なのかということと、Ｂとした評価についてお伺いしたいと思います。","respondent":"阿部人権啓発課長","answer":"Ｂというのは、今後も継続してやっていくです。そもそも行動計画が１０年のスパンですので、この間は当然のことながら行動計画推進委員会の意見を聞きながら、区と共同して進めていくという意味で、継続して進めていくという評価のＢにしているです。","voiceIndex":229,"id":"exchange-102"},{"speaker":"北野委員","kind":"質問","question":"この中では男女共同参画ということを目指す社会として拡大していくべきものでもあるはずですので、その点についてこちらはいろいろな部分での評価をされるところがあると思いますが、それについてお伺いしたい。その評価が事務事業評価の中に反映されるような仕組みになっているのか、その点についてお伺いしたいと思います。","respondent":"阿部人権啓発課長","answer":"今後とも継続して１０年の間で第三次行動計画を推進していくという意味で、これからも継続していくです。もう１点、個々の事業の評価の話ですけれども、これは提言を受ける中で行動計画推進会議の委員が各所管のところにヒアリングに入っております。","voiceIndex":231,"id":"exchange-103"},{"speaker":"北野委員","kind":"質問","question":"提言の中に各事業部に行ってヒアリングをした結果の評価が入るということなんですけれども、その評価が事務事業評価の中にどのように反映されていくかお伺いしたかったんです。こちらのほうも公募が入られて、確かに進められていると思いますが、そういう部分でもやはりあらゆるデータで評価を進めていくことが必要だと思うんですけれども、いかがでしょうか。","respondent":"阿部人権啓発課長","answer":"要するに、行動計画推進会議の方は、それぞれの所管に事業の進捗状況を聞きながら、それ以降に具体的に区としてこういう形で進めてくださいという提言が入ってきますので、そういう意味で先ほど申し上げたとおり、委員の評価が提言の中に盛り込まれてくると思ってあります。","voiceIndex":233,"id":"exchange-104"},{"speaker":"北野委員","kind":"質問","question":"それが事務事業評価の中にどのように生かせていくのかなという情報提供ですよね、こちらの中への、そのことをお伺いしたのと。それから、次にイメージアップ経費ですが、決算報告によりますと２１６万６，７７３円、職員報発行１３回ということが成果として上げられていますけれども、内容についてもう少し詳しく伺いたいと思います。","respondent":"阿部人権啓発課長、山田広報広聴課長","answer":"繰り返しになりますけれども、行動計画推進会議の委員の評価を踏まえて、当然それを踏まえて３年度以降を実施していくということになりますので、そういう意味では委員の評価が当然次期に生かされていくというふうに考えております。例えば、区民生活事業部などは大変窓口が多いということで、個別に接遇研修、保健高齢事業部などでも同じように、よりよいコミュニケーションのための信頼関係づくりということで、高齢者の方々が来て介護保険だとか。","voiceIndex":235,"id":"exchange-105"},{"speaker":"北野委員","kind":"質問","question":"２００１年度の予算額を見ると、４１５万５，０００円ということで、執行率が５２.１％、品川区の各会計決算審査意見書を見ましても、３０％以上差がある事業内容ということなんですが、残りの４８％はどのようなものが執行できなかったのか、その点についてお伺いしたいと思います。","respondent":"山田広報広聴課長","answer":"言ってみれば、同じ事業の対比で言いますと、平成１２年度については１８３万８，３００円、ほぼ同じような金額ということで、事業のくくり方の違いの部分ということでご理解いただきたいと思います。","voiceIndex":238,"id":"exchange-106"},{"speaker":"北野委員","kind":"質問","question":"２００１年度の予算を見ますと、決算との合わせだと思いますが、イメージアップ経費で４１５万５，０００円、職員報発行１２回、区民憲章、品川憲章１００件の普及経費として合わせて４１５万５，０００円が、決算額で見ますと２１０万円ということになっているので、その差についてお伺いしたいということです。","respondent":"山田広報広聴課長","answer":"大変失礼いたしました。今、印刷関係というのは大変落差が出ているところですけれども、報告書等を含めて印刷関係の落差が出ております。職員報につきましても外部で印刷ということで出しておりますので大きな落差額が出て、このような執行額になっております。","voiceIndex":240,"id":"exchange-107"},{"speaker":"北野委員","kind":"質問","question":"確かに「気軽に行ける」「親切」という回答はありますけれども、２０００年度では「暗い」というイメージがアップして、「近寄りがたい」というイメージもアップ、逆に「庶民的」というところが０.５ポイントぐらい下がっているところなんですけれども、やはり研修に対しては、こういう形でやりたいという意欲がうかがえるんですけれども、そういう見解については。","respondent":"山田広報広聴課長","answer":"これは区長まで当然上がるわけですけれども、「イメージアップは何をやっているか」というお叱りもいただきながら、こういう研修を重ねてまいりまして、昨年度は職員に対する８月末までの数字が２６件あったのが、本年度は１１件までおさまったというところで。","voiceIndex":242,"id":"exchange-108"},{"speaker":"北野委員","kind":"質問・要望","question":"事務事業評価の中では評価されていますけれども、そういうところで障害者や高齢者の目線に立った公共サインということで、ぜひ品川区のイメージアップをしていただきたいと、これは要望しておきます。しかし、国も品川区と同じ９３事務含めて使うときに、国は利用者としての経費は払わなくていいのかどうか、それは何か決まりにあるの、そこを伺いたいと思います。","respondent":"冨田戸籍住民課長","answer":"住基ネットで情報提供した場合の利用料ですけれども、国１件当たり１０円で、収入は都道府県のほうに入ります。","voiceIndex":244,"id":"exchange-109"},{"speaker":"北野委員","kind":"質問","question":"都道府県に１０円入るということですけれども、区にはどういう形でおりてくるのでしょうか、伺います。","respondent":"冨田戸籍住民課長","answer":"区には情報提供するだけで、来ません。","voiceIndex":246,"id":"exchange-110"},{"speaker":"北野委員","kind":"質問","question":"区には情報提供だけでおりない、何の形もないという、国の税金になる、財政になってしまうということなんでしょうか。国が都道府県に１０円を払うということで、区には一切何も来ない、どういう形でも来ないということなんでしょうか。","respondent":"冨田戸籍住民課長","answer":"国は都道府県に１件当たり１０円を支払います。都道府県から区市町村には手数料としては来ません。","voiceIndex":248,"id":"exchange-111"},{"speaker":"北野委員","kind":"質問","question":"区長にお伺いしたいのですけれども、品川区の中での個人情報保護の中では、問題があったときに切断できるというできる規定ですけれども、やはりきちっと「できる」ではなく、「切断する」というように、区民の安全を守るというところではっきり断言されたほうがいいのではないかということをお伺いしますが、いかがでしょうか。","respondent":"冨田戸籍住民課長、中尾根企画部長","answer":"業務経費の一部に１件当たり１０円が充てられると聞いてあります。なお、住民は住民票を取る必要がなくなりますので、住民の負担は当然軽減されるということになります。切断の問題でございましては、今回の条例の切断の件につきましては、委員のおっしゃっているような表現もあり得るかと思いますけれども、システム全体が品川区独自のものではございませんので。","voiceIndex":250,"id":"exchange-112"},{"speaker":"北野委員","kind":"質問","question":"そういう思いであるならば、ぜひ区長の直の答弁をお伺いしたかったと思います。それから、センターのほうに入るということですけれども、これは都道府県も含めて市区町村もセンターのほうには加入ということで払うというところで、国もそれで払うということで、どういうところで払うという違いがあるのか伺いたいと思います。","respondent":"冨田戸籍住民課長","answer":"説明が悪くて恐縮なんですけれども、１０円は都道府県のほうに入るということです。この１０円につきましては、都道府県の条例で額が決まっていると聞いております。","voiceIndex":253,"id":"exchange-113"},{"speaker":"高星委員","kind":"質問・要望","question":"最初に質問に入る前に教えていただきたいんですが、もうそろそろいつまでも黙っていられないな、何とかしなければならないなと思っているのが、学校におきます空調設備の、昔の運輸省の航空機騒音の関係の無用の長物、あれが文部科学省のものではないのでしょうか、その辺がわからないんだけれども、それを撤去するには教育ではなかなか対応できないだろうと思うんですけれども。","respondent":"高橋区長","answer":"航空機騒音によります防音の空調施設を設置をいたしました。品川区で騒音規制にかかりますところはどこもなくなりました。したがいまして、空調施設は全部無用の長物になってしまった。騒音対策審議会で、国のほうで補助金を出してつけさせていただきました。","voiceIndex":257,"id":"exchange-114"},{"speaker":"高星委員","kind":"質問・要望","question":"これから質問に入ります。一つ目は、成果報告書９０ページの成人式の関係、２点目に９４ページから９５ページのケーブルテレビの関係、３点目に９６ページの消防団の関係、ケーブルテレビと消防団の関係につきましては、前回に質問した部分について、どうも会議録、速記録を見ても腑に落ちないところがあるものですから、後処理というような形で聞かせていただきたいと思います。この問題が一つ。","respondent":"山田広報広聴課長、古川総務課長、西島経理課長","answer":"有料加入世帯についても１万８，２０３世帯、１０.９％ということで、徐々に上がってきているです。成人式に関するご質問です。最初の部分ですけれども、式典の簡素化等々によりまして、今年実施しました成人式につきましては一定の評価をいただきました。先ほど総務課長が宿日直のあり方のソフト面についてご答弁いたしましたけれども、ソフト面の検討を併せまして。","voiceIndex":259,"id":"exchange-115"},{"speaker":"高星委員","kind":"質問・要望","question":"もう一度、広報広聴課長に確認しますけれども、視聴可能世帯というのは、いわゆるケーブルテレビの引かれているところですね。わかりました。だから、そういうことも含めて、随分これまでも啓発してきているわけですけれども、もう少しきちんと連携を取って、例えば品川区に何箇所、何本の地域ケーブルがあるということも含めて、きちっと話をして大幅な情報改善をしていただきたいと、これは要望いたします。","respondent":"小野（孝）政策担当課長","answer":"したがって、都のほうが４分の１、区とケーブルテレビ会社が４分の３を負担して事業をしているです。","voiceIndex":263,"id":"exchange-116"},{"speaker":"高星委員","kind":"質問","question":"いずれにしても、平成１３年度で７８４万円、これは補助の打切りと延長の時期の多少のタイムラグもあるのだろうと思いますけれども、平成１４年には６００万円で大分減ってきているなという感じはするんだけれども、最後の意気込みをお聞きしたい。経理課長には、夜間窓口は将来に向けてもう少し整備すべきだと思います。そのことの決意もお聞きしたいと思います。","respondent":"山田広報広聴課長、西島経理課長","answer":"これの大きな理由は、八潮団地の都営住宅が従来加入できないという、東京都の住宅局の判断だったんですけれども、都営住宅であってもケーブルテレビを引くという判断のもとに。宿日直のあり方につきましては、運営の仕方のソフト面の検討と併せましてハード面についても十分検討してまいります。","voiceIndex":265,"id":"exchange-117"},{"speaker":"高星委員","kind":"確認","question":"よろしくお願いします。最後に消防の分団の話ですけれども、品川消防の６分団の中に４分団の事務所がありますということは、前回も確認したと思うんです。品川４分団というのは、目黒駅の向こうのほうから今の第二日野小学校のところまで全部カバーしている。その向こうが６分団で、そっちに第４分団の倉庫がある。そこを把握しているかどうか聞きたいと思います。","respondent":"久保田防災課長","answer":"今の消防団のお話ですが、消防団の倉庫は基本的に消防庁の管轄でございまして、消防庁のほうで手当てしているものです。今、第６分団のお話ですけれども、第６分団につきましては資機材倉庫はあります。御殿山小学校と品川小学校を借りて資機材倉庫を置いているです。","voiceIndex":268,"id":"exchange-118"},{"speaker":"高星委員","kind":"確認","question":"私は地元の品川消防団の人に聞いているんです。それがそういう倉庫なのかどうかも後でもう一度確認して、後日また質問いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":270,"id":"exchange-119"},{"speaker":"石田委員","kind":"質問・要望","question":"今区民はさまざま要望が多いわけで、今みたいな借上げ施設をやっていけば、例えば互助会でも３カ所、旅行代理店を通じれば結構多くあるわけですけれども、品川区の中で区民サービスを考えるのであれば、５カ所でも１０カ所でも借上げをして、それには経費がほとんどかからないと思いますが、保養所の部分の下がった部分をちょっと充てるだけで全体を賄えると思っておりまして。","respondent":"宮地区民課長、山田広報広聴課長、西島経理課長、松代道路公園課長","answer":"多分、借り手がなかなか厳しいなというのもちらほら出ていますが、多分杉並方式というのはまさにそれで。夏休み工事の件について、私からお答え申し上げます。平成１３年度の夏休み工事は、５月・６月で４７件発注しています。それまでの間、当面都道ですので第二建設事務所と品川区、また警視庁等と連携を図りまして。","voiceIndex":272,"id":"exchange-120"},{"speaker":"石田委員","kind":"質問・要望","question":"最後のほうからいきます。今の第二建設事務所のお話、ぜひ急なときにポンプアップをして川のほうに流すとか、何か考えていただきたい。それから、夏休み工事は、ぜひこれも来年に向けて準備をしていただいて、そういう方がいらっしゃっても体制は体制として区の体制ですから、すぐ体制ができるようにしていただきたいと思います。それから、保養所もぜひもう一段進んで考えていただきたいなと考えています。","respondent":"山田広報広聴課長","answer":"これはマーケティングにお願いするということになれば、かなたの経費等がかかります。これは教育委員会の皆さん方とご相談をしながら、例えば別な取り方があるかどうか、ちょっと研究をさせていただきたいと考えています。","voiceIndex":277,"id":"exchange-121"},{"speaker":"石田委員","kind":"質問","question":"もう一度言っておきます。それは多少経費がかかっても最低のラインを１回実質の数字をつかんで、それから上がってくるということも必要だと思いますので、ランダムに抽出してやるという普通の企業がやっている抽出方法もやってみて、それを大切にしてもう１回見直すということも必要だし、もし教育委員会のほうでやれるというのであれば、その辺も一言あればお聞きしたいと思います。","respondent":"中尾根企画部長、指田教育次長","answer":"広報紙は読まれることが第一番ですので、素直に区民の方の声に耳を傾けて全力を尽くしてまいりたいと思ってあります。広報紙の関係です。事業部制を取りました。事業部制というのは切磋琢磨すると同時に、お互いに連携するというのが事業部制のポリシーですので、一緒になって取り組んでまいりたいと考えています。","voiceIndex":279,"id":"exchange-122"},{"speaker":"沢田委員","kind":"質問","question":"私は成果報告書９６、９７ページの臨海部広域斎場あるいは区民斎場に関連して質問したいと思います。それから、管理運営の検討も進んでいるようですけれども、いつぐらいに方向が確定するのか、その辺について教えてほしいんです。","respondent":"宮地区民課長","answer":"それも生かしながら、今後の運営において細部に詰めていくところですが、基本的な方針といたしましては、やはり経費を極力かけずに適正なサービスを提供していこうという大きな方針を掲げまして、それに基づいた使用料の設定等、いよいよこれから本番で詰めていくところです。","voiceIndex":283,"id":"exchange-123"},{"speaker":"沢田委員","kind":"質問・要望","question":"一つは、今言った利用料の問題です。区民委員会の議事録を読んでみましても、「できるだけ安く」「無料に」という意見もあって、全体としては安い方向にというのが、議事録で見る限り多いんですけれども、コストに見合う利用料負担というのは、どんな論議が５区の間でされて、品川区としてはどういう主張をしてきたのかということを教えていただきたいと思います。","respondent":"宮地区民課長","answer":"極端なことを申し上げますと、なるべく安く、ただというふうになりますが、コストに見合うということで、今大体身近なところにあります桐ケ谷斎場、都営で言えば瑞江が公立になりますけれども、桐ケ谷と同じセッティングでは公営斎場のよさがありませんし。","voiceIndex":285,"id":"exchange-124"},{"speaker":"沢田委員","kind":"質問・要望","question":"その点についてもう一度お考えをいただきたい。区民委員会では「無料」あるいは「無料が一番いい」というのを含めて３人いらして、「瑞江の料金ぐらいがいいのではないか」というのが１人、その他の方は表明はしなかったように思うんですけれども、ちょっと議会とのずれもあるのではないかと思うんですが、その辺はどう考えているのでしょうか。","respondent":"宮地区民課長","answer":"品川区議会としてまとめたということではなくて、そういう意見がありましたという伝え方をしてありますので、あとは５区の協議会、それから当然のことながら議会が、それも一部事務組合ですからありますので、その中での決定ということになってまいります。","voiceIndex":287,"id":"exchange-125","title":"町会・自治会支援"},{"speaker":"沢田委員","kind":"質問・要望","question":"もしわかっていれば、これは正確でないかもしれないんですが、私が前に瑞江に行ったときだったと思うんですが、大人一体を火葬するに必要な燃料というは石油缶１缶ぐらいだということからすれば、ほとんど全体の人件費だとか、その他もろもろの管理がかぶって高くなるというふうに思うんですけれども、その辺はどれぐらいのコストを考えているのかということと、これは要望ですけれども。","respondent":"宮地区民課長","answer":"当然のことながら各区の分担金という形で、またそこで経費が生じてまいりますので、できる限りコストも安く抑えますが、それに見合う負担をしていただかないと、やはり全体の経費にしわ寄せが来ますので、その試算でいきたいと考えております。","voiceIndex":289,"id":"exchange-126"},{"speaker":"沢田委員","kind":"質問","question":"２番目は足の便の問題なんです。経緯としては、そういうところだったわけです。モノレールの流通センターが５分ちょっとでしょうか、平和島になるとかなり遠くなってしまうということになると、品川区民の利用の便となると、どうしても大井町との間のバス利用をかなり積極的にやる必要があるのではないかと思うんですが、その点についての考えと現状をお聞かせ願えればありがたいと思います。","respondent":"宮地区民課長","answer":"バス路線は、特に京浜急行が大森駅から隣接している大田スタジアムに向けて本数がありますが、ただ増発をしませんと利便性がよくなりませんので、今現在事務局のほうで京浜急行本社の自動車部と交渉中で、増便の予定で話が進んでいるということですので。","voiceIndex":291,"id":"exchange-127"},{"speaker":"沢田委員","kind":"質問・要望","question":"せっかく駅があんなに立派になっているんですから、案内所みたいなものを、例えば桐ケ谷斎場、博善社と葬儀屋と東急が話して、そこに行けば地図だけではなくて、こうですよというような場所を駅の下に案内所をつくるようなことを考えるべきときに来ているのではないかと思うんですが、その点について、いきなりかもしれませんけれどもいかがでしょうか。","respondent":"宮地区民課長","answer":"これは東京都葬業共同組合品川支部がありますので、そちらと特に品川区ではなぎさ会館の運営を委託しているという関係がございまして、直接役員の方ともお話する機会がありますので、そういう場をお借りして、今委員の言われたことをお伝えすることはできますが。","voiceIndex":293,"id":"exchange-128"},{"speaker":"沢田委員","kind":"質問・要望","question":"「葬祭場の設置に関する環境指導要綱」を、地元の要望で全国に先駆けてつくっていただきましたけれども、ここの中では「葬祭場の設置の計画および管理運営に関して必要な指導内容を定め、住民との紛争を未然に防止」という、どちらかというと葬祭場の建設にウエートを置いているんですけれども、管理運営でも近隣に迷惑を及ぼさない、近隣町会長も近隣住民の定義の中に入っているという。","respondent":"田平建築課長","answer":"斎場の設置指導要綱につきましては、私どものほうでも十分ただいまの意見を念頭に置きまして、事業主のほうと調整してまいりたいと考えております。","voiceIndex":295,"id":"exchange-129","title":"町会・自治会支援"},{"speaker":"沢田委員","kind":"意見","question":"今日、ある方から聞いたんですけれども、どうしても案内所みたいなものができなければ、大きな掲示板にしてボタンを押すと自分の行くところがここだという、それもあまり大きくするとおかしな方向に入ってしまうかもしないんですが、そういうことも考えられると思いますので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":297,"id":"exchange-130"},{"speaker":"鶴委員","kind":"質問・要望","question":"その際に、人生の最終章のお別れにあたっての施設は、本来的には自治体、つまり行政側が責任を負うべきではないのかという視点から、城南地域に都立の火葬場を誘致するよう東京都あるいは関係機関に働きかけを提言し、都立が無理であれば一部事務組合方式で設立できる可能性があるのではないか、今が絶好のチャンスではないか、前向きに対処してほしいと強く求めました。あるいは要望があったかもしれません。","respondent":"宮地区民課長、阿部人権啓発課長","answer":"臨海部広域斎場ですが、今お話にございました施設運営にあたると思いますが、９月に区長会、議長会を開きまして、その中でおおむねの基本的な方針を確認し合ったところです。インターネットによります差別事象が増えている、あるいはそのことによって人権を傷つけられる人が増えてきているということは認識しております。","voiceIndex":299,"id":"exchange-131"},{"speaker":"鶴委員","kind":"確認","question":"私のことで恐縮ですが、３月２２日、予算特別委員会である議員の一連の発言について、それが事実か否かということを確認いたしました。ところが、どうしたわけか４月２１日、「公明党鶴議員の恥ずべき総括質問。そして、２１日に質問した当事者がこう言っているんです。ネチケットについて、人権擁護の立場からどういうふうに対処していこうとしていくお考えなのか見解をお聞きしておきたいと思います。","respondent":"本間総務部長","answer":"ただ、いずれにいたしましても時代が変わろうが、心理的な差別が依然としてあるというのは厳然とした事実ですので、私ども行政といたしましては人権尊重都市品川宣言の趣旨を踏まえまして、人権の心理的差別の解消に向け、今後も地道に施策に取り組んでいくという考えですので。","voiceIndex":302,"id":"exchange-132"},{"speaker":"鶴委員","kind":"質問・要望","question":"ぜひ、そういう取り組みを強化していただきたい思うんです。私に対する公開質問状の冒頭に何と書いてあったかというと、「このまま放置すすることは○○議員の名誉を著しく傷つけるだけではなく、区民に大きな誤解を与えることになる」と書いてあるんです。誤解を与えたのは本人ではないか。ちゃんと、そういうことはいけないことだとか教えていっているのか、人権教育の中でお伺いしておきたいと思います。","respondent":"若月教育長","answer":"人権尊重教育につきましては、例えば法に決められているからこうであるとかということではなく、人が生きる態度として常に人権を大事にしなければならない、このような教育を日夜続けているところです。","voiceIndex":304,"id":"exchange-133"},{"speaker":"塚本委員","kind":"質問","question":"聞き取りようによっては、おれが押したんじゃないから知らないというふうに取られる可能性もありますし、前の質問者の話ではございませんけれども、いろいろな発言の中の一部分を取り上げて、いろいろ喧伝する人がいる昨今ですから、そのことに関してしっかりとお答えいただかないと、私どももちょっと「あれっ」という印象を持って聞いていたものですから。","respondent":"高橋区長","answer":"須藤委員からのご質問のときもお答えいたしました。私は短絡的に話を申し上げましたけれども、品川区では公印規則がございまして、それにのっとりまして公印を押しているわけです。","voiceIndex":308,"id":"exchange-134"},{"speaker":"塚本委員","kind":"質問","question":"お答えが固定したようですから、それ以上進まないように思いますのでやめておきます。政策評価で外部評価委員会をつくったと。皆さんおよそご存じでしょうが、あらましと今どの辺まで会議が進んでいるのかということを伺いたいと思います。","respondent":"榎本行財政改革担当課長","answer":"実際には、ある程度評価の仕組みの手法の具体的な検討に入りまして、ベンチマーク方式を取るですとか、コストを加味したほうがいいとか、住民満足度の評価書も取ってほうがいいとかという形で議論が進んでいるところです。","voiceIndex":312,"id":"exchange-135"},{"speaker":"塚本委員","kind":"質問","question":"公募型の人もいらっしゃいますし、学識経験者の方が委員長だと思いますが、大変見識の深い方です。評価の一つの手法としてベンチマーク方式を取ろうとしているやに伺っておりますが、その辺のところも確かめておきたいと思います。今伺っていると、そういうことではないように思いますけれども、そういう心配が杞憂であることを願っておりますけれども、いかがでしょうか。","respondent":"榎本行財政改革担当課長","answer":"そういった意味で、委員おっしゃるような官僚主導型という形は取らずに、ゼロベースでまず政策評価というのを区のレベルでどういうふうにしたらいいかという議論からスタートいたしまして、今現在その議論が徐々に進んできたところです。","voiceIndex":314,"id":"exchange-136"},{"speaker":"塚本委員","kind":"質問","question":"２年のスパンでやっていると思いますけれども、ある種の評価委員会の成果物ですが、それをどのように表現されるつもりであるか、そのところを最後にこの件に関しては伺っておきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"やはり区長の附属機関としての審議会ですので、諮問いたしまして、それに対する答申という形をもらうという形式になっておりますけれども、各委員からのいろいろな提言をもらって、それを次の政策に反映させて活用していきたいと考えております。","voiceIndex":316,"id":"exchange-137"},{"speaker":"塚本委員","kind":"質問","question":"私立幼稚園の援助策はさまざまなレベルでなされております。保護者に対するもの、園に対するもの、そこに働いている人に対するもの、業界に対するもの、それぞれ政策目的が少しずつ違いますので、ありがたいことです。そして近年、私立幼稚園に通われる園児も決して少なくなっていない。一定の期間を経ておりますので、この施策に対する自己評価と申しますか、その辺を伺っておきたいと思います。","respondent":"古川総務課長","answer":"委員から私立幼稚園の置かれている状況、あるいは幼稚園・保育園も含めた就学前児童に対するさまざまな施策ということのご説明がございました。基本的に、私もその方向でとらえてあります。","voiceIndex":318,"id":"exchange-138"},{"speaker":"塚本委員","kind":"質問・要望","question":"幼保一元化への大きな流れがある。子どもを長時間預かって、その前後何をしたらいいのだろうという思いがあります。そして、７時半から６時半まで１１時間の預かり時間、こういう人は滅多にないと思いますけれども、そういうことをすることが教育的にどうなんだと。教育者ならではの心配だと思いますので、そういうこともあるんだということをしっかりとご記憶いただきたいと思います。","respondent":"原委員長","answer":"以上をもちまして、本日予定の審査はすべて終了をいたしました。次の会議は明日、午前１０時から開きます。本日は、これをもって閉会をいたします。","voiceIndex":320,"id":"exchange-139"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1198#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":104748,"voices":321}},{"id":"h14-20021004-4","meetingId":"h14-c-settlement","date":"2002年10月4日","dateIso":"2002-10-04","committee":"決算特別委員会","time":"午後５時４３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を144件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"おはようあります。外はちょっと曇っていますけれども、秋晴れですので、さわやかな質問をしていこうと考えています。介護保険のことで質問するんですが、３年間やってまいりました。３年間運営してきて、品川区としてどう評価されているか。それから、当然、毎年４０歳、６５歳以上の方が新しく介護保険に入っているわけですから、その方々に対する周知はどうされているかということ。","respondent":"高橋介護保険担当課長","answer":"平成１２年度から、３年間、介護保険を実施してまいりましたけれども、やはり、平成１２年度に導入されたころにおいては、品川区におきましては、導入前からの準備がありまして、他区から比べると順調によく進んできたと考えています。","voiceIndex":4,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"これを見るとすべてわかります。介護保険の仕組み、それから、どこに業者がどういうふうにあってと。だから、これから質問しますけれども、例えば、こういうものを区の予算でつくるということではなくて、事業者と連携をしながら、費用負担を按分しながらつくっていって、６５歳以上の方に配れば一目瞭然なんですよ。だから、そういうことをなぜ考えていかないかということを一つ聞きたい。","respondent":"新美保健高齢事業部長","answer":"ご質問の件につきましては、第２期へ向けまして、今後、どのようにしていくか検討をしてまいりたいと思います。","voiceIndex":6,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"それは、相談してきたら教えてあげるとか、そういう態度じゃだめなわけで、そうでなくて、こういうふうな介護保険制度だから、どうですが、ご理解していただけませんかということを積極的にしていかなければ、これからも６５歳以上の方は、間違いなく増えていくわけですから、安定的な介護保険の運営はできないと思いますので、広報周知に対する考え方を、もう１回、お聞かせください。","respondent":"新美保健高齢事業部長","answer":"ケアマネージャー、ヘルパー等、介護サービスの事業者同士の連絡体制、あるいは定着問題等々も含めて、競争という問題ですけれども、これにつきましても、第１期は、どうしても移行期、安定のためにという課題でしたが、これからは介護保険制度の定着、あるいは。","voiceIndex":8,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問","question":"保健高齢事業部長の思いが伝わってきました。介護保険の本来の趣旨からすると、被保険者の方々は業者を選んでいくことになっております。それから、四、五年ぐらい前でしょうか、保健高齢事業部長がドイツに海外調査に行かれていますよね、介護保険の勉強で。いろいろなメニューがあるかもしれませんけれども、それをどう設計していくか、これからの方向性をお答えください、お願いいたします。","respondent":"新美保健高齢事業部長","answer":"確かに、ドイツに勉強に行かせていただきました。いろいろドイツの介護保険と日本の介護保険の共通性、あるいは違いといったものを、短時間ではありましたけれども、認識をしてまいりました。","voiceIndex":10,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、品川区標準方式を守ってほしいということを、一つ要望しておきます。そのことに対して、品川区としては、どう対処していくのか。ですから、そうでない部分を、できればうまくいくように。議事録に残りますので、なかなか言葉を選んでしゃべっていますので、わかってほしいんですけれども、もっとはっきり言っていいんでしょうかね、派遣先で品川区の感覚で仕事をされる方がおられる。","respondent":"早津高齢福祉課長","answer":"大規模な法人で、３００人を超える職員を抱え、またさまざまな補助金をはじめ、財源措置の工夫をしたりというような中で、常勤職員としてさまざま活躍されていると考えておりますし、そこに当たっては。","voiceIndex":12,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"でも中には、なかなか品川区のお役所感覚で仕事をされていらっしゃる方がいる。確かに退職された方ですから、直接的なことはできないかもしれませんけれども、でも、これはどこになるんでしょうか、保健高齢事業部長でしょうか、ともかく社会福祉法人を通して、そういう元ＯＢの方をご指導していただくとか、そういうことをもう少し検討していただけないでしょうか、お答えください。","respondent":"新美保健高齢事業部長","answer":"ご質問ですけれども、区内の社会福祉法人に区のＯＢ等の職員を派遣する形で行っていることは、各施設の運営と区の施策との連携、あるいは整合性をきちんと図っていくということで、これは二十数年前の品川区が社会福祉法人立で施設整備をしてきたときからの基本的な方針です。","voiceIndex":14,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"意見","question":"そういうふうにいろいろなところの人たちが、介護保険のことを真剣に考えて、保健高齢事業部長の情熱、それから区長の情熱にこたえて、すばらしい介護保険をつくっていっていただきますように、お願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-007"},{"speaker":"中島委員","kind":"質問・要望","question":"私は、３款民生費、社会福祉費と高齢福祉費の中から質問いたします。初めに社会福祉費、この中に権利擁護の仕組みづくり事業というものができておりますが、これは、今までの社会福祉協議会で行われている財産保全管理サービスを引き継ぐ形で、再構築していくとあるわけですけれども、このことについて、少し教えていただきたいんですが。","respondent":"中川原福祉事業部副参事","answer":"従来やっておりました財産保全管理サービスの実績をもととしまして、さらに契約行為とかにつきましてもフォローする内容として、現在、進めているものです。","voiceIndex":18,"id":"exchange-008"},{"speaker":"中島委員","kind":"質問","question":"１点お聞きしたいんですが、これまでの経過の中で、利用者はどのぐらいあったのでしょうか。それから、どのぐらいの財産から管理してもらえるのか。この点をお伺いします。","respondent":"中川原福祉事業部副参事","answer":"財産保全サービスの実績ですが、平成１２年度末までで、管理サービスが７名、保全サービスが６名、全部で１３名いらっしゃいました。ただし、両方のサービスを利用している方がいらして、１１名の方おりました。","voiceIndex":20,"id":"exchange-009"},{"speaker":"中島委員","kind":"質問","question":"そうしたら、財産が幾らとか、そういうのは関係なく見てくださるということですか。わかりました。これは利用料は、支払いをするんでしょうか。","respondent":"中川原福祉事業部副参事","answer":"今度の権利擁護サービスといたしましては、貸し金庫を利用される場合は、実費として月５００円程度をいただきまして、預かったものについて、定期的にお届けしたり、料金の支払いをする場合は、それに応じて１回１，３００円程度をいただくような形で、今、構成しています。","voiceIndex":22,"id":"exchange-010"},{"speaker":"中島委員","kind":"質問・要望","question":"そういったことからしても、やはり、こういうサービスは充実していただきたいなと、私も願っているところです。その中で、ちょっと難しいなと思うのは、まだ健康である、まだまだ大丈夫だと思っていらっしゃる方、そしてきわどいすれすれのところに来て、こういう管理サービスを受けたほうがいいのになと思うけれども、難しい境目のところにいらっしゃる方に対して、区はどのようにお考えでしょうか。","respondent":"中川原福祉事業部副参事","answer":"今、高齢福祉課の在宅介護支援センター、それから障害者福祉課等々と、区役所のワーカーと連携しまして、発見のシステム、それからそこをどうやって私どものシステムにつなげていくかという連携をしまして、発見からケース会議、そして。","voiceIndex":24,"id":"exchange-011"},{"speaker":"中島委員","kind":"質問","question":"とても進歩されているということで、今、とても安心したんですが、もう一つお伺いします。既にもうわからなくなってしまって、周りの方が自主的にお世話しているという方に対しては、取り組んでいただけないでしょうか。","respondent":"中川原福祉事業部副参事","answer":"その場合は、その関与者の方と一緒にご相談しまして、その方にとって、その方の意思を尊重した形で、どのような形が最善の方法なのかというのを一緒に考えて、この制度につなげていくような形で進めております。","voiceIndex":26,"id":"exchange-012"},{"speaker":"中島委員","kind":"質問・要望","question":"今、まちの中で、こういう点が一番周りの人の悩みの種となっているような感じもしますので、ほんとうにこの制度をしっかり充実させていただきたい、このように要望しておきたいと思います。この辺のところは、区のほうでは、受けとめていらっしゃいますでしょうか。","respondent":"早津高齢福祉課長","answer":"在宅介護のほうでも、巡回ヘルパーとかいうことで、例えば夜間ということもあるわけですけれども、介護施設におきましては、２４時間を基本としておりますので、そういう点では、労働時間を含めまして、負荷の要素というのはあろうかと考えています。","voiceIndex":28,"id":"exchange-013"},{"speaker":"中島委員","kind":"質問","question":"これは、特定の施設とは申しませんが、中には、介護学校を卒業して、すぐにもう現場の仕事をして、そこで失敗をしてしまって、すぐに辞めたという方がいらっしゃいます。こうした教育面でも、不十分な点があるんじゃないかと思われますが、この辺のところは把握されているでしょうか。","respondent":"早津高齢福祉課長","answer":"研修につきましては、福祉カレッジというような制度もありますけれども、私どもで、実際上の人材の育成というものが、非常に大事だと考えています。これは法人も同じ気持ちでいると思います。ご指摘のあったようなことが、今後ないようには努めていきたいと考えています。","voiceIndex":30,"id":"exchange-014"},{"speaker":"中島委員","kind":"質問・要望","question":"サービスの向上を目指す品川区としても、やはり大事な区民の方々をお任せするわけですから、そういったところの管理というのは、区としてしっかり対処していただきたい。ところが、夏場などは１週間に１回しかないので、お風呂に１週間に１回しか入らないと、あせもはひどいし、臭くなるしということで、こういう方たちは、ほかの手立てはないんでしょうかという質問を受けたんです。","respondent":"早津高齢福祉課長","answer":"介護保険のサービスの中では、自宅を訪問する巡回入浴サービスというようなこともありますが、デイサービスを嫌わずに、そちらのほうにも行っていただければ、思わぬお友達もできたり、さまざまな可能性が開けておりますので、そちらのほうにもお話しいただければと考えています。","voiceIndex":32,"id":"exchange-015"},{"speaker":"中島委員","kind":"質問","question":"よくわかりますが、高齢者の方だとやはりすごくこだわって、絶対に施設は嫌だという方もいらっしゃるわけなんです。介護をされている方にしてみれば、もう少しお風呂に連れて行ってあげることができないかということで、在宅介護の家事援助の中の最後のメニューの中に、こういうものをもう少し組み込めないのかなと思うんですが、いかがでしょうかか。","respondent":"早津高齢福祉課長","answer":"入浴をお手伝いするというのは、ホームヘルプサービスの中には、身体看護のメニューとしてはあります。そういったことがらも、さまざま活用していただければと思います。","voiceIndex":34,"id":"exchange-016"},{"speaker":"中島委員","kind":"質問","question":"わかりました。ただ、介護をされている方が、こういうところで悩んでいらっしゃるんです、どうしたらいいかということで。こういう方たちが気軽に相談できるような、ご自分が勤めている施設で聞けばいいのかもわかりませんけれども、やっぱりさまざまな細かい問題というのはあると思うんです。そうしたことが、気軽に聞けるような窓口というのはないんでしょうか。","respondent":"早津高齢福祉課長","answer":"支援センターのケアマネージャーは、要介護認定を受けていない方でありましても、高齢者のご相談に応じますので、ぜひ、お気軽に相談していただければと思います。","voiceIndex":36,"id":"exchange-017"},{"speaker":"中島委員","kind":"質問","question":"そのケアマネージャーとヘルパーの連携、先ほど、伊藤委員も触れられておりましたが、ここら辺のところがスムーズにいけばいけばいいんでしょうか。やはり、こちらにヘルパーから相談があるということは、そのところで聞けないんじゃないかなと思うんですが、どうでしょうか。","respondent":"早津高齢福祉課長、新美保健高齢事業部長","answer":"ヘルパーとケアマネージャーの間に、どうやら齟齬が見られるというような場合ということでございましょうか。そういう意味では、ケアマネージャーはどうしても現実の仕事をしておりますので、なかなかそれをということにはなりませんので、そういうお声、ご意見等につきましては。","voiceIndex":38,"id":"exchange-018"},{"speaker":"中島委員","kind":"質問・要望","question":"明解なお答えをありがとうあります。確かに、最前線の方はいろいろ悩みを持ったり、迷ったりして、仕事をされておりますが、こういう方たちがいないと介護保険も成立していかないし、高齢者の方も安心していけないという部分もありますので、介護をしてくださる方が働きやすい条件づくりというものも、しっかりこれから基盤整備のほうをお願いしたい、このように要望して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"私は、介護保険の会計のところで伺います。１点は、決算表のところで、保険給付のところが、予算１０７億円で、決算が９６億円、執行率が８９.６％ということだったんです。昨年は、この原因は療養病床の計画と実際のところで大分差があったということだったんですけれども、今回の原因については、どういうふうにお考えなのか、それが１点。この２点、伺いたいと思います。","respondent":"早津高齢福祉課長","answer":"当初予算に対します執行率ということで８９.６％という数字です。当初の見込みとの乖離で大きな点と申し上げれば、それは療養病床の当初予定との差が、やはり一番大きいと考えています。それから、基金への積立です。","voiceIndex":43,"id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問・要望","question":"第２期目の事業計画、保険料の見込みについて、今度、厚生委員会で資料を出されるということでありますので、詳しくはそっちのほうで聞きたいと思うんですけれども、特に中心点で、２点ほどちょっと伺いたいんです。総事業費、総介護費のところで、平成１２年、１３年度、どういう推移だったのか。１号被保険者の人数、事業計画のところで、今後どういうふうに見ているのか。","respondent":"早津高齢福祉課長","answer":"第２期の予測につきましては、現段階で最終の詰めということになっております。当然、高齢者の増、とりわけ後期高齢者の増ということが考えられる中では、当然、増傾向があるということが見込まれます。","voiceIndex":45,"id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私が伺いたかったのは、事業計画のところで、総介護費用と１号被保険者の数の見込みを聞きたかったわけです。今の時点で、話ができるのかどうなのか。わかったら教えていただきたい。私ども、これは当初の見込みとの差で生まれているものですから、これは次の保険料の算定のときに、この分は取り壊すということは当然だろうと思っているんですけれども、そこの考え方をお聞かせいただきたいと思います。","respondent":"早津高齢福祉課長","answer":"これに当たって基金をどうするのかです。第２期目につきましては一定の需要増が見込まれますので、必要な場合には、基金の一定の取り崩しも視野に入れているです。","voiceIndex":47,"id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問・要望","question":"基金の取り崩しは、私は当然だと思います。次に移りますけれども、低所得者の対策のところで、ちょっと伺いたいんです。この１，６００人余りは、大体第１段階、第２段階に集中しておるとは思いますけれども、改めて、この１，６００人、第１段階から第５段階までの人数、あるいは割合、どういうふうに分布されているのかお聞かせいただければと思います。","respondent":"太田保険年金課長","answer":"まだ、その時点の数字ですから、おそらく、４、５、６月の３月分の数字ですので、私ども、その詳細についてはまだ検討してございません。これから、１年間の保険料が入ってくるです。","voiceIndex":49,"id":"exchange-023"},{"speaker":"宮崎委員","kind":"質問・要望","question":"特に第１、第２段階に集中しているわけではないということで、これは後で、詳しい数字がわかったら教えていただければと思います。ここでは、「低所得者の理解を得るために６段階」ということを言っているんです。その点で、区のほうの見解と、今後の姿勢はどういうふうにお考えなのか、お聞かせいただきたいと思います。","respondent":"早津高齢福祉課長","answer":"６月のいわゆる中間値の報告を踏まえて厚生労働省が、保険料の設定について６段階というような見解も示してまいりました背景には、全国の自治体の中で、第１期に比べて、保険料がかなり上昇するところが見られる、地方においては倍以上というようなものも見られる中で。","voiceIndex":53,"id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は、ちょっと先ほど言いましたけれども、お年寄りの負担を下げるという点で、いろいろと考えたらどうかと思います。それが一つ。先ほどの厚生労働省の施策は、それはそれで必要な対策だと思うんですけれども、こっちのほうが本命だと思うんですけれども、改めて、低所得者の保険料減額の制度、条件の緩和について求めたいと思うんですけれども、お考えをお願いしたいと思います。","respondent":"早津高齢福祉課長","answer":"これはまだ始まって１年ですので、この基準について変更というようなことは考えてございません。","voiceIndex":55,"id":"exchange-025"},{"speaker":"宮崎委員","kind":"質問","question":"例えば、２号被保険者の負担率が、今まで３３％だったのを３２％に下げた。１号被保険者のほうは、１７％を１８％にするとなっております。それから、基準額を２５０万円から２００万円に変えるということになると、現状は、例えば第１段階ですと２.１％、第２段階３２％と割合が分布しておりますけれども、これがどういうふうに変化していくのか、そこのところの見通しをお伺いしたいと思います。","respondent":"早津高齢福祉課長","answer":"これは、人口動態を踏まえた変更です。それから、基準所得金額第４段階、第５段階の間に設定しております所得基準ですが、これの変更は、第３段階を中心としまして、第１段階、第２段階は軽減をいたします、第４段階、第５段階は、その分だけ負荷をする。","voiceIndex":57,"id":"exchange-026"},{"speaker":"宮崎委員","kind":"意見","question":"先ほど、現状とどういうふうに変更になるかと聞いたんですけれども、それもお願いしたいと思います。","respondent":"早津高齢福祉課長","answer":"パーセントの変化です。全国平均でいきますと、第１段階が。〔「品川区」と呼ぶ者あり〕品川区は、ただいま精査をしているところでございまして、合わせてこれも、厚生委員会でご報告をします。","voiceIndex":59,"id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問・要望","question":"この厚生労働省の全国課長会議の資料を見ると、ほんとうに情報公開をやれと言っているんですよ。ですから、今度、厚生委員会に出すとは言うんですけれども、ここのところだけ改善をしていただきたいと思います。今の件で言うと、やっぱり取りやすいところから取るというふうに思いますので、ここのところは意見を述べていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"仕事を見つける方は、探したい方は数多くいらっしゃると思うんです、元気なんですから。それから、前回の予算特別委員会でもお話があったと思うんですが、奨学金の債権回収に対して、シルバー人材センターの方にご活躍していただく場をつくったとお聞きしていますが、この実績、まだ半年ぐらいですけど、どのような動きがとられているのか、その点について、お答えをお願いしたいと思います。","respondent":"蓼沼高齢事業課長、宮地区民課長","answer":"名称を、元気づくりいきいきプランというふうに変えまして、箱根荘、あるいはしながわ光林荘で、今後とも同様のプログラムで実施をしていく予定です。奨学金の債権回収状況ですけれども、７月、８月、９月で、８０万８，０００円収納しています。これにつきましては、かなり悪質な滞納をされている方を頻繁に訪問いたしまして、回収したものです。","voiceIndex":63,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"区民課長の方なんで、民生費ではなかったということで申しわけなかったですが、やはりそういうふうに専門的に活用できる部分は、これからもいろいろな面で生かしていっていただきたいという思いの中での、質問をさせていただきました。いんで、話を変えていきます。児童手当給付金関係について、質問をさせていただきたいと思います。その辺をお願いできますでしょうか。","respondent":"辻田児童課長","answer":"そういうような関係で、児童手当をもらう方が、区内でも大変増えてきたということです。これは、いわゆる少子化社会における子育て支援という形で、今回、実施されたということで、私どものほうも、大変歓迎しています。","voiceIndex":66,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"児童扶養手当の大綱が変わったということで、そっちのつもりだったんです、すみません、聞き方を間違えました。児童扶養手当のほうで、母子家庭等自立支援対策大綱がまとめられた、そのことについての質問のつもりだったんです。内容を間違えました、すみません。","respondent":"辻田児童課長","answer":"ですから、児童扶養手当の、いわゆる手当部分だけでなく、今後、さらに国のほうでも、子育て支援、また就労支援、それから、母子寡婦貸付金の拡充などという形でいろいろな施策が出てきて、それと一体となって母子の自立に向けて支援していくという形になってあります。","voiceIndex":68,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問","question":"自立支援という面で、品川区としてどのような形の支援体制をとっていらっしゃるのか。具体的に今現状でやっていらっしゃることを、少し教えていただければと思います。","respondent":"辻田児童課長","answer":"それからまた、いわゆる母子のお母さんが就労につながる、また、その会社の中でさらにレベルアップした仕事につけるような技術を身につけるというようなことでパソコンの講習会の運営など、区としては実施しています。","voiceIndex":70,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問","question":"母子寡婦の方の自立という意味で、我々も、母子寡婦福祉連合会の皆様とも、よくお会いすることもあります。そんな中で、皆様方の自立という言葉が、やはりよく出てくるんです。企業に対しては、その辺は区の話でないのかどうかということを、ちょっと教えていただければと思います。","respondent":"辻田児童課長","answer":"こういう世の中ですので、辞めさせられる方も出てくるというような状況に対して、個々の対応ということについては、なかなか、今、私どものほうとしても対応できる状況ではないというのが現実です。","voiceIndex":72,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"現実、大変厳しい問題だと思います。でも、やはりせっかく自立しようしている気持ち、またそれに対して支援していこうということであれば、区の中でも多少、企業に対して声をかける形をとっていただければ、それがどこまで成果になるかわからないと思うんですが、なるべくそのような協力もしていただきたいと思います。","respondent":"辻田児童課長","answer":"今のご要望につきまして、関係機関と連携を取りまして、対応してまいりたいと考えております。","voiceIndex":74,"id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"私は、子育て支援関係の質問をします。その中で、初めに、成果報告書の１０８ページ、非常通報装置整備助成について、お尋ねします。昨年の６月だと思いますが、大阪府の池田小学校で痛ましい事件がありました。そこで質問しますが、この非常通報装置の助成について、まず、どういうものかご説明をお願いしたい。あわせて、財源についても、お願いいたします。","respondent":"金子保育課長","answer":"非常通報装置の助成についてのお尋ねですが、委員、ご指摘のとおり、大阪の事件の後、東京都が緊急に取り組みました事業でして、都内の小中学校、幼稚園、それから児童センター、あるいは保育施設、子どもが通う施設に警視庁直結型の通報装置を設置する。","voiceIndex":77,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"まだ幸いなことに、品川区で実際にこのような事件があったということは聞いておりませんが、設置してから、この装置が実際に機能したことはあるんでしょうか。","respondent":"金子保育課長","answer":"そのときに、警視庁に通報が行ってしまったわけですけれども、直ちに近隣のパトカーが駆けつけてくれました。東京都の説明によりますと、通報が一度あれば、大体５０人規模の警察官がその施設に向かうという約束になっているということでございました。","voiceIndex":79,"id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"今、課長のご答弁で、電気的な誤作動で警察官がすぐに駆けつけてくれたというお話を伺って、ある意味、誤作動であったんですけれども、鳴ったことによって、すぐに警官が来たという現実がある、現実にそういうふうにしていただけるということを伺って、改めて、大変安心はさせていただきました。防犯という意味においても、日ごろはどのような点について注意をしているのか、お伺いさせてください。","respondent":"金子保育課長","answer":"私どもの保育園では、平成１１年度以降、延長・夜間保育事業を充実させてまいりまして、その間、少子化対策臨時特例事業の交付金等々を活用しまして、来訪者の確認をするためにモニターの設置、それから、電気的に鍵を開錠したり。","voiceIndex":81,"id":"exchange-037"},{"speaker":"藤原委員","kind":"質問・要望","question":"まさに、これは保育園の危機管理だと思います。これは要望です。次に、各種助成の一つといいますか、待機児童についてお伺いします。厚生委員会の中でもご報告がありました、認証保育所についてお尋ねをします。今年の４月１日、９月１日の時点での待機児童につきましては、厚生委員会で、それぞれ１８８人、２２３人とお伺いしましたが、１０月１日現在においては、どのようになっているかお聞かせください。","respondent":"金子保育課長","answer":"お尋ねの１０月１日現在の待機児の数ですけれども、２７０人という数字になってあります。","voiceIndex":83,"id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"かなり数が増えたんだなということを実感しますが、今後の傾向について、所管課として、どのような見方をしているのか、あれば教えてください。","respondent":"金子保育課長","answer":"一つには、私どもの所管ではございませんが、９月１日から、幼保一元化事業の二葉すこやか園、つぼみ保育園で３６人在籍しているという部分がありますが、ただ、４月当初の傾向と１０月１日の傾向では、ちょっと増加が鈍いかなとは考えております。","voiceIndex":85,"id":"exchange-039"},{"speaker":"藤原委員","kind":"提案","question":"本定例会に目黒線不動前駅駅舎内の認証保育所が、補正予算として提案されております。たしか、Ａ型とＢ型があったと思うんですけれども、それぞれの現況について、ご説明をお願いします。","respondent":"金子保育課長","answer":"認証保育所のＡ型とＢ型についての現況ですが、Ａ型は、委員、ご指摘のとおりのものが目黒線不動前駅駅舎内は来年１月の予定です。目黒駅の国立予防衛生研究所跡地で予定されていた分がありますが、これについては認証の取得がおくれていると聞いております。","voiceIndex":87,"id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"そのような予定であるということが、今の答弁でわかりましたが、そうしますと、待機児解消との関係というのはどうなるんでしょうか。先ほどの説明によると、多数の待機児がいるわけですけれども、認証保育所が待機児解消として、どのような効果があるかということも、あわせてお伺いします。","respondent":"金子保育課長","answer":"Ａ型については、先ほど申し上げましたとおり、これから設置されるものですので、今のところ、他区の動向を見てみますと、多様な保育の受け皿として効果はあると思いますけれども、品川区としては、今後、検証していきたいと考えております。","voiceIndex":91,"id":"exchange-041"},{"speaker":"藤原委員","kind":"質問・要望","question":"引き続き、待機児の解消に努力をしていただきたいと、切にお願いを申し上げます。最後に、区民の相談を受けました。今、上のお子さんを保育園に預けていて、今度、下のお子さんが生まれるので、育児休業を取ろうと思っていますと、上の子は保育園で引き続き預かっていただけるでしょうかということでした。この点について、どのようなお考えを持っていらっしゃるか、お聞かせください。","respondent":"金子保育課長","answer":"満１歳になるまでといいますと、年度の途中でどうしても預かることができなくなるということでしたので、この６月に、満１歳の年度末になるまで伸ばして上の子を預かる。上の子が、なお翌年度５歳クラスになる場合は、就学時まで預かると変更したところです。","voiceIndex":93,"id":"exchange-042"},{"speaker":"本間委員","kind":"質問","question":"特に高齢者生きがい対策事業費のところから、さまざまな事業が出ておりますが、その件について何点かお尋ねします。その際の対応の仕方、事故の場合の対応の仕方について、お伺いしますのが１点。高齢者生きがいづくり事業につきましては、高齢者作品展、ゲートボール、シルバーダンスパーティ等々がありますが、この中で特にいきいきカラオケ広場の実績が出ておりますが、この評価について、お伺いします。","respondent":"蓼沼高齢事業課長","answer":"いきいきカラオケ広場ですけれども、これにつきましては、平成１３年度から実施をいたした事業ですけれども、非常に参加者が多くあります。","voiceIndex":96,"id":"exchange-043"},{"speaker":"本間委員","kind":"質問","question":"いきいきカラオケ広場については、ありがとうございました。ところで、最近、いきいきカラオケに伴ってマージャンをどうのこうのということを、隣の区の方からお聞きしているんですが、その内容について、簡単にお知らせ願いたいと思います。","respondent":"蓼沼高齢事業課長","answer":"従来、どちらかというと、マージャンは不健康なイメージがあったかと思いますけれども、かけない、飲まない、吸わないをモットーに、高齢者の方の生きがいづくり、仲間づくり、そして、指先を使う知的なゲームということで、介護予防、ぼけ防止といいますか。","voiceIndex":98,"id":"exchange-044"},{"speaker":"本間委員","kind":"質問・要望","question":"しかし、大筋満ぱいだったというお話を伺っておりますので、この辺の部分はやめます。次にいきます。しながわお休み石設置事業ですが、この設置場所についてお伺いします。バス会社との関連で、バス停のところにすべてあるとは思いませんけれども、特にバスの停留所のところなどは、屋根を伴う形でのお休み石の設置という考え方にしていただけないものが、この件について、１点お伺いします。","respondent":"蓼沼高齢事業課長","answer":"なかなか雨の後をきれいにしておくというのは、その都度はなかなか難しいかと思いますけれども、そういった区民の方をはじめご要望に応じて設置場所を定めてありますので、なるべく、ただいまのような屋根のあるところが実現できれば、そのようにしてまいりたいと思います。","voiceIndex":100,"id":"exchange-045"},{"speaker":"本間委員","kind":"質問","question":"時間がないので、最後の一つだけ、簡単にお願いします。高齢者社会参加プログラム策定事業です。この中身について、お尋ねします。かなり多岐の分野にわたるものと思われますけれども、特徴的なものを二、三点教えていただけたらと思います。","respondent":"蓼沼高齢事業課長","answer":"昨年度、報告書をまとめましたけれども、先ほど、サポ品川というお話がございましたけれども、今年度は特に、高齢者の、例えば品川高齢者クラブ連合会の方のボランティア活動の参加が１点と、それから就業についてさらに多様な働き方について支援をしていくというようなところが。","voiceIndex":102,"id":"exchange-046"},{"speaker":"本間委員","kind":"質問・要望","question":"たくさんの人がいれば、それだけ意思があるわけでございまして、多分野の拡大のメニューも含めて、これからも頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-047"},{"speaker":"桜井委員","kind":"質問・要望","question":"実際に１０月申請ということなんですけれども、具体的にはどういうふうな形で受け付けていくのでしょうか。その前段としてお尋ねしたいのは、今、申し上げたところと、それからもう一つ加えてちょっとご説明いただきたいのは、最近行われた説明会を聞いていますけれども、どういう方々を対象に説明会がされて、その中で出た主な意見をご紹介ください。","respondent":"日下部障害者福祉課長","answer":"一番直近の説明会としましては、９月２９日に、品川総合福祉センター、それから福栄会、私ども区ということで、三者共催で、施設の利用者の皆さん方に対する説明会を実施いたしました。参加者は、約１２０名ほどいらっしゃいました。","voiceIndex":107,"id":"exchange-048"},{"speaker":"桜井委員","kind":"質問・要望","question":"その方が一番不安に思っているのは、確かに今、７００人で、この方は通所をしているわけですけれども、既に子どもが４２歳になるということで、親はもう７０歳ということで、とりあえずそこでは、課長でしょうか、今の施設で入所されている方は大丈夫ですよとおっしゃったということなんですけれども、一番不安なのが、１年間はとにかく猶予ということになっているにしても、その後は。","respondent":"日下部障害者福祉課長","answer":"そういった点では、これからもいろいろなところにきちんと配慮をしながら、きめ細かな説明をしっかりやっていきたいと考えております。ただ、肝心なことは、以前も本会議でご答弁申し上げましたけれども、一般的な仕組みの問題はなかなか難しいんです。","voiceIndex":109,"id":"exchange-049"},{"speaker":"桜井委員","kind":"質問","question":"そうなりますと、選ぶ自由はあるにしても、先ほど、手帳をお持ちの方が１，５００人ということでしたけれども、状態が日々変わるというんでしょうか、１年ごとに変わっていくわけですよね。確かに、親がそういうことを熱心にいろいろと見ていると思うんですけれども、その中で、一番力を入れてほしいのが、心身障害者通所、入所施設の拡充ということなんです。これについては、どのようにお考えでしょうか。","respondent":"日下部障害者福祉課長","answer":"ただ、そういった点では、いくら計画的に進めようとしても、いろいろその都度新しい条件が変わってくるということもありますので、第三次長期基本計画については、平成１３年度から新しくスタートしたわけですが、私どもとしましては。","voiceIndex":111,"id":"exchange-050"},{"speaker":"桜井委員","kind":"質問","question":"実際にかかわっている親の立場から言えば、ほんとうに心配なんです。ですから、今、入所されている方も、決して今の状態でいいとはなかなかならない。１点、介護保険のときには、専門に研修されて、試験も受けて、ケアマネージャーが配置されているわけですよね。しかし、一番頼みになるケースワーカーの方々というのは、何か資格というんでしょうか、研修というんでしょうか、持っているのか。","respondent":"日下部障害者福祉課長","answer":"私どものケースワーカーも、それを受講しております。今後とも、その辺の研修内容については充実を図っていくという国の方針等もありますので、これを受けとめてしっかりと内容の充実に努めていきたいと考えています。","voiceIndex":113,"id":"exchange-051"},{"speaker":"桜井委員","kind":"質問・要望","question":"先ほど申しましたサービス基盤と同時に、相談体制、それから、利用料の問題等、きょうは触れられませんでしたけれども、きめ細かい説明会を開いて、きちっと体制をとっていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、特別会計の国民健康保険事業につきまして、お伺いをいたします。大きくは２点ありまして、収納率の向上という観点からが１点と、品川区が平成１２年度から基礎的自治体になりましたが、そういう観点から１点お聞かせいただきたいと思います。収納率の低下傾向を含めた状況について、どのようにとらえていらっしゃるのかをお聞かせいただきたいと思います。","respondent":"太田保険年金課長","answer":"ご質問にお答え申し上げます。ご指摘のとおり、昨今の経済状況を反映して、他の被用者保険から国民健康保険へ加入される方の数というのは増加傾向に入ってあります。それに伴いまして、当然、保険料の負荷が決定されますので、調定額自体も増えてきているです。","voiceIndex":117,"id":"exchange-053"},{"speaker":"田中委員","kind":"質問","question":"もう少し細かくお伺いをしたいと思いますが、例えば、被用者保険から移られた方々で、その方が通常どおりの納付をされていれば特に問題はないんですが、昨今の経済情勢から、それが難しいということから、こういう数字になるんでしょうが、まずそういう方々へのアプローチの方法として、それまでは被用者保険に入っていたわけですから、例えば社会保険事務所等から、その方々の個別の情報というんでしょうか。","respondent":"太田保険年金課長","answer":"ただ、収納率の部分でいきますと、じゃあ、被用者保険のときに収納状況がどうだったかということについては、連携は取ってございませんというか、できないと考えています。","voiceIndex":119,"id":"exchange-054"},{"speaker":"田中委員","kind":"質問","question":"法律上の制限等があるのであれば、やむを得ない部分もあろうかと思いますが、可能であれば、それはぜひ促進をお願いしたいと思います。その他いろいろな要因があろうかと思いますが、例えば、現在、品川区で滞納された方が、他自治体へ転出してしまった場合、その追跡はどういう対応をされていらっしゃるんでしょうか。","respondent":"太田保険年金課長","answer":"私ども、滞納されている方で区外転出された方については、いろいろ住所を追いかけていくという形で、住所の転出先が判明している方については、区内にいらっしゃる被保険者の方と同様に、定期的に滞納の徴収についてのお知らせをするなり、あるいは電話がわかっていれは。","voiceIndex":121,"id":"exchange-055"},{"speaker":"田中委員","kind":"質問","question":"同時に聞けばよかったんですが、逆に、他自治体での滞納者が品川区に来られた場合の対応、その際には、先ほどの社会保険事務所からのデータ云々もありましたが、他自治体からのデータというんでしょうか、その方の内容、情報というのを入手することはできるんでしょうか。","respondent":"太田保険年金課長","answer":"入ってきた場合に、国民健康保険上で、被保険者に調査権がありますので、必要に応じて、転入先の自治体に、例えば所得状況ですとか、収納状況の調査自体はできることになってあります。個々の状況に応じて、私どもも実施しております。","voiceIndex":123,"id":"exchange-056"},{"speaker":"田中委員","kind":"質問","question":"今現在、期待といいますか、予測というんでしょうか、そういう部分になってしまいますが、そのような部分で議論なりがなされているんでしょうか、ちょっとお伺いしたいと思います。","respondent":"太田保険年金課長","answer":"区域外の転出先の滞納対策ということの連携も必要だということで、今後、さらに検討していくというような提言も出てあります。そうしたものの推移を見ながら、私どもも、より収納率を高めていきたいと考えています。","voiceIndex":125,"id":"exchange-057"},{"speaker":"田中委員","kind":"質問・要望","question":"不能欠損額のことについてお伺いしたいんですが、いわゆる消滅時効が２年間ということで、２年経過してしまったもの、あるいは、資格がなくなったものがここに入ってくるんだろうと思います。その辺の傾向、昨今の状況というんでしょうか、この数字を見て、どのようにとらえていらっしゃるのかお聞かせいただきたいと思います。","respondent":"太田保険年金課長","answer":"不能欠損ですけれども、今、平成１３年度について見ますと、いわゆる差し押さえすべき財産が、調べてもない、将来の収入の見込みも明らかにないという方々がほとんどといいますか、失業、営業不振、病気等の関係、あるいは、破産の状態になっている、お亡くなりになった。","voiceIndex":127,"id":"exchange-058"},{"speaker":"田中委員","kind":"質問・要望","question":"それらの方々のご尽力で、収納率そのものは下がってはおりますが、母数、決算額そのものが増えているという評価はもちろんするわけですが、昨今の経済情勢ということも一方ではあるんですが、仮に公務員の方によるこれ以上の母数そのものの向上が厳しいとなったときに、いわゆるほかの分野でも行われておりますが、民間委託ということで、一つは母数を増やすということとか。","respondent":"太田保険年金課長","answer":"私どももそれを受けて、収納率向上を考えれば、今後、委員ご指摘の徴収員、私人への委託を検討していく価値は当然あるかなと考えています。","voiceIndex":129,"id":"exchange-059"},{"speaker":"田中委員","kind":"質問・要望","question":"法制限が、特に国レベルの制限がかかる分野ではありますが、可能な範囲での、ぜひさまざまな工夫といいますか、対応をお願いしたいと思います。品川区としては、保険者として独立をしておりますので、独自の判断で保険料の設定が可能なわけですが、現段階では、東京２３区が統一した保険料方式をとっている。現段階の、２３区での統一方式に関してのお考えをお聞かせいただきたいと思います。","respondent":"太田保険年金課長","answer":"基本的には、委員、ご指摘のとおり、基礎的自治体になったわけですから、各保険者が自主的に保険料を決めていく時代だろうと。なおかつ、所得水準も各区によって違ってきているわけですので、当然、そういう時代を早く迎えるべきだと考えています。","voiceIndex":131,"id":"exchange-060"},{"speaker":"田中委員","kind":"質問","question":"一つ見方を変えれば、民間にたとえるならば、保険サービスを提供する会社が２３社あって、その２３社がカルテルを結んで統一料金を設定しているというようなことでありまして、民間で言えば、これはまさに公正取引上、問題がある内容ですので、平成１２年度からは基礎的自治体となった品川区独自の料金設定も含めた独自性を発揮できるように、さらなるご尽力をお願いし、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-061"},{"speaker":"三上委員","kind":"質問・要望","question":"私のほうから、１００ページ、社会福祉費に関係して、その中でも、やさしいまちづくり計画推進費というのが計上されておりますが、ここのところを、簡単でいいですから、ちょっとご説明いただきたい。初めに、最初に申し上げましたけれども、社会福祉費のやさしいまちづくり計画について、簡単でいいですけれども、どういう事業であるか、ちょっと教えていただけますでしょうか。","respondent":"早津高齢福祉課長","answer":"やさしいまちづくり計画推進費３，０００万円余の内容です。これは鉄道駅のバリアフリー等のためのエレベーター、エスカレーター等の設置に関する助成経費、それから、街角サインの設置費等に使用されたものです。","voiceIndex":135,"id":"exchange-062"},{"speaker":"三上委員","kind":"質問","question":"ちょっと話が変わるかわかりませんけれども、去る９月１０日から３日間、東京ビッグサイトにおいて、第２９回国際福祉機器展が開催されました。障害をお持ちの方も、随分積極的になられたなと。展示出品者の皆さん方と、逆に積極的に、自分がどう使いこなしていけるかというような雰囲気で質問している姿というのが多くみられたわけです。感想でもちょっと。","respondent":"小沼福祉事業部長","answer":"国際福祉機器展ですけれども、私は、９月１０日に、私どもの障害を持っている職員と、車いすなんですが、行ってまいりました。率直に申し上げまして、電子機器を中心とした日常生活の介助、介護機器の発達、あるいは日進月歩ということに非常に驚かされたということが一つ。","voiceIndex":137,"id":"exchange-063"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう中にありまして、その福祉機器をどう使いこなしていくかということも大事になってくる。こういうことを見たなら、それをどういうふうに公共施設で導入していくか。そうすると、そのもの自体を、マンションの管理組合の理事長とか、自治会長とかという代表者が購入する場合に、福祉機器の助成ということができないかどうかということをあわせて、ちょっとお考えをお聞かせいただきたいと思います。","respondent":"早津高齢福祉課長","answer":"ですから、この辺については、今後、私どもが働きかけを関係機関にしてまいりたいと考えておりますけれども、そういったマンションの管理組合の問題等につきましても、それはそれでまた、私どもの制度上の問題との関連も含めまして。","voiceIndex":139,"id":"exchange-064"},{"speaker":"三上委員","kind":"質問・要望","question":"要するに車いすを利用する方が１人という形ではなくて、３人、４人で一つの建物の中にいらっしゃるとすれば、その方たちが共有の立場から使えるということも含めて、制度の検討とかということで、ぜひともやっていっていただきたいと、お願いしておきたいと思います。そこらあたりの現状を、簡単でいいですけれども、ちょっとつかんでいることがあったら教えてください。","respondent":"早津高齢福祉課長","answer":"統計数値は特に取ってはございませんけれども、自宅内でも階段をはじめお風呂、それから居間が非常に多いらしいんですけれども、転倒からねたきりにつながるというケースが大変多いと聞いてあります。","voiceIndex":141,"id":"exchange-065"},{"speaker":"三上委員","kind":"質問・要望","question":"歩幅が狭くなると筋肉が弱ってきていると判断する。要するに歩幅を広く保っていくための筋肉をつけていかなければならない。そうすると、同じ太さの中で、筋力をどう太くしていくかということが大事だということで、大腰筋を強くするということで、ねたきり老人をつくらないという形において、高齢者の施策としての展開ということもやってほしいなという思いもあるわけです。簡単でいいです。","respondent":"早津高齢福祉課長","answer":"区内でも、保健所、保健センターにおきまして、骨折予防教室というようなものも行っておりますし、また、在宅介護支援センターでは介護予防教室というような中で、筋力アップも含めて、さまざまな取り組みを行っているところです。","voiceIndex":143,"id":"exchange-066"},{"speaker":"三上委員","kind":"質問","question":"最後に、児童福祉施設費の中で、平成１４年３月１８日、品川区東五反田保育園で品質マネジメントシステムが国際基準規格ＩＳＯ９００１に適用し、審査登録されました。品川区はこういうことをやっているということで、いろいろな世界的な形で品川区を注目しているというような動きもあればいいんですけれども、今、どういうような状況にあるか、ちょっとお教えいただけませんでしょうか。","respondent":"金子保育課長","answer":"東五反田保育園のＩＳＯ９００１の審査登録に絡みまして、国の評価ということなんですけれども、本会議の一般質問でも答弁申し上げたとおり、ここのところ他自治体、あるいは国からの直接の視察というものもございました。","voiceIndex":145,"id":"exchange-067"},{"speaker":"三上委員","kind":"質問・要望","question":"そうすると、国連の経済協力開発機構が来て、世界の国連の立場から見たときに、品川区の保育事業というのは、どういうふうに、何らかの評価とか、何か発言されていったということがございましたら、ちょっとお教えいただきたいんですが、どうでしょう。","respondent":"金子保育課長","answer":"その中でも、幾つか特徴的なところとしては、私のほうが勉強になったんですけれども、私の所管するところではありませんけれども、例えば幼保一元化の問題についても、品川区は今やっているということでお話申し上げたところ、実は調査の２年目だということで、昨年はデンマーク。","voiceIndex":147,"id":"exchange-068"},{"speaker":"三上委員","kind":"質問","question":"もっと時間があれば、もうちょっと細かなことをお伺いしたかったと思います。別の機会に、改めてお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-069"},{"speaker":"川西委員","kind":"質問・要望","question":"高齢者の在宅サービスについて、関連して伺います。１００ページの訪問介護サービス給付等の実績、数字の内容を教えていただきたい。それから、訪問看護については、区内事業者というのは、今、何カ所ぐらいあるのか伺います。それから、２番目には、このページの、これはもう単純に中身の実績を伺うんですが、高齢者リハビリテーションシステムの検討経費の内容について、実績を伺います。","respondent":"早津高齢福祉課長","answer":"リハビリテーションのほうの検討経費ですが、これにつきましては、昨年と今年と両年かけて検討を行っていく一貫した検討事業なんですが、昨年度におきましては、区内のリハビリテーションを行っておりますケアセンター南大井、それから、デイサービスセンター等の実績ですとか。","voiceIndex":151,"id":"exchange-070"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、リハビリテーションのシステムの検討については、全部の結果が出ると資料が出ると理解していればよろしいですか。はい、わかりました。それから、訪問看護のほうに関連して伺いますけれども、９事業者で、今、在宅でねたきりに近い状態といいますか、かなり重い病気にかかって、これの対象者である方々の需要にはこたえられているかどうか。この辺を伺います。","respondent":"早津高齢福祉課長","answer":"訪問看護を要する方と申しますのは、やはり医療的な措置ということで、典型的なのが褥瘡の措置というものです。必要な訪問看護事業について、十分賄えていると考えています。","voiceIndex":153,"id":"exchange-071"},{"speaker":"川西委員","kind":"質問","question":"１０３ページの訪問介護員の養成研修の、平成１３年度の中身を伺います。それに関連をいたしまして、デイサービスなんですが、これについては、保育園ではないけれども、待機する人たちがかなりいるのかなと思いますが、この辺については、どう把握されているのか伺います。","respondent":"早津高齢福祉課長","answer":"今手元にありませんが、全体としての利用者の満足度は９３％、家族のほうが９５％だったように記憶をしています。さまざまなご意見があろうかと思いますが、全体としてのサービス評価といたしましては、そのような結果が出ているというのが速報値です。","voiceIndex":155,"id":"exchange-072"},{"speaker":"川西委員","kind":"質問・要望","question":"これは、とりあえず要望を一つ申し上げますが、在宅で、お話相手なのか、お掃除なのか、よく中身はわかりませんが、週に一遍ぐらい訪問を受けているケースが、介護度の認定を受けたからだと思いますけれども、大変多くなりました。ですから、そういう点では、やはり、７８歳の夫を７７歳の妻が、銭湯に連れて行って入れるのが大変で、せめて夏だけでも２回にしてもらえないかというのが要望でした。","respondent":"早津高齢福祉課長","answer":"お風呂の増設ということにつきましては、今年度、福栄会のほうで行うということになってありますので、その点からも、ご要望におこたえできるのではないかと考えています。","voiceIndex":159,"id":"exchange-073"},{"speaker":"川西委員","kind":"質問","question":"話がこんなに通じているとは思わなくて質問いたしました。確かに、水曜日と土曜日のデイサービスの利用者でした。そういう点では、土曜日が満ぱいになるということで、よく承知いたしましたので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-074"},{"speaker":"沢田委員","kind":"質問・要望","question":"そのための行政、法整備が必要だと。こうした立場を踏まえて、ちょっと質問をしたいんですが、３月の予算特別委員会で、私のホームレスの方から聞いた話として、支援センターの食べ物は犬猫に等しいようなものだと紹介をいたしました。区としてどうとらえているのか、出していただきたい。それから、大田寮と台東寮の食費の予算は１日幾らで、その財源はどうなっているのか。３点、お尋ねしたいと思います。","respondent":"黒田生活福祉課長","answer":"そのほかにも、対応の仕方、お風呂の入りかた等についても、こたえられる範囲で対応しているということです。それから、食事についてですが、私の記憶では、１食５００円程度と記憶しています。","voiceIndex":163,"id":"exchange-075"},{"speaker":"沢田委員","kind":"質問・要望","question":"そこで、私は一つ紹介したいと思うんですけれども、ある自立支援センターに対して、ホームレスの皆さん自身の団体と支援組織、それから自立支援センターに入っている有志の方が、特別区人事・厚生事務組合の所管に対して要望書や意見書を繰り返し出していると。他の自立支援センター並みに食事の質を上げるべきだと考えます」と書いてある。こうしたことについては、聞いてないんでしょうか。","respondent":"黒田生活福祉課長","answer":"大田寮に入所した方、緊急一時保護センターから自立支援センターに行くというのが、今回のシステムですが、品川区は、こちらの窓口にお出でになった方、所管から連絡があったということで窓口にお出でいただいて、随時大田寮に入所させておりますので。","voiceIndex":165,"id":"exchange-076"},{"speaker":"沢田委員","kind":"提案","question":"ですから、これを軌道に乗せるためにも、改善すべき点は改善して、よりよいものにしていくという立場で聞いているわけです。だから、問題があれば、しっかり改善提案をするべきだと思います。改めて、利用者の皆さんなどにアンケートを取るなりして、意見を特別区人事・厚生事務組合のほうに上げて、改善すべき点は改善するという立場を取るべきだと思いますけれども、いかがでしょうか。","respondent":"黒田生活福祉課長","answer":"現在のところ、緊急一時保護センターが、本来ですと、各２３区で５カ所の予定が、１カ所しかないというところで、相談のおくれがあろうかと思います。","voiceIndex":167,"id":"exchange-077"},{"speaker":"沢田委員","kind":"質問・要望","question":"私は、いろいろな支援団体の要望書などを読みまして、決して食事の問題と、回転という言い方が正しいかどうかわかりませんけれども、効率的に運用するという問題だけじゃなくて、金銭管理の問題、それから、お酒を飲んではだめだと言いながら、実際にはお酒を飲んでいることが是正されなくて、真面目に自立しようと思って仕事探しをしている人たちが、もう何のために来ているかわからないという問題。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-078"},{"speaker":"土井委員","kind":"質問・要望","question":"４カ所にわたって出てくるんです。それから、１９２ページの介護認定審査会、ならびに認定調査等費ですけれども、この辺で、ちょっとお伺いをしたいんです。そして、現実問題、そのために、認定審査会１７５回というのは延べですか。となりますと、チームの数とか、そんなことが今どのようになっているのかということを、しばらくちょっと留守にしていたものですから、お聞かせいただきたいと思います。","respondent":"早津高齢福祉課長、太田保険年金課長","answer":"平成１２年度に国庫支出金、国が負担すべき給付費に対して、２０％プラス５％弱の国が負担すべきものがあります。それがあらかじめ見込みで参っている関係で、精算をした段階で、２億円余の余りがあったので返還をした。平成１２年度が１，５００万円で、３，８５０万円、２.５７倍、平成１３年度が９４０万円で、過誤調整が４，３７０万円で、４.６４倍ということで、年々効果が上がってきているところです。","voiceIndex":171,"id":"exchange-079"},{"speaker":"土井委員","kind":"質問・要望","question":"今のところは大体わかりました。レセプトのところを、ちょっとやらせていただきます。全部見るのか、見ないのか。そして、見た中から、それだけの過誤等が見つかったわけですから、もし何分の１かの抜き取りでそれだけ見つかっていると、全部を見るともっとあるんじゃないかという気もするものですから、その辺がどうなのかということも含めて、ちょっとお聞かせいただきたいというのが一つです。","respondent":"太田保険年金課長","answer":"基本的には、国民健康保険連合会で全件チェックをいたしますけれども、重点的には高額療養費共同事業というものが、東京都の国民健康保険連合会で実施をしていますので、８万点以上、金額でいうと８０万円以上の高額療養分を重点的に。","voiceIndex":174,"id":"exchange-080"},{"speaker":"土井委員","kind":"質問","question":"そこら辺、たしか、私も前に伺ったときは、抜き取りといいますか、全部じゃないというように記憶をしていたものですから、そんなに上がるんだったら、ほんとうはやらなくてもいいのが一番いいんですけれども、残念ながらやらなきゃならないという状況だとすれば、全部やったらとと思っていたもので。大体わかりましたので、以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-081"},{"speaker":"石田委員","kind":"質問","question":"私からは、１１１ページ、学童保育クラブ運営費、または１０９ページ、保育園運営費に当たるところと、１０３ページ、高齢者住宅改修アドバイザー派遣事業についてというところで、お聞きしたいと思います。初めに、大井学童保育クラブに入会している人が対象だということでありますが、入会している人が何人いて、今、チャイルドホームを何人利用しているかということを、まずお聞きしたいと思います。","respondent":"金子保育課長","answer":"大井学童保育クラブの、９月現在の入会人数は２５人です。うち、チャイルドホームに登録されている方が３人です。実績に関しましては、６月からスタートしておりますが、９月終了時点で、延べ５人という数字です。","voiceIndex":178,"id":"exchange-082"},{"speaker":"石田委員","kind":"確認","question":"今、お話がありましたように、延べ５人という利用者があるということで、これは、学童保育クラブに来ている子ども、保育園を使って６時以降８時半までということでありますが、改めて確認をいたしますが、今、これが実施をされているわけでありますが、試行しているのか、あくまでも試行の中の試行と考えてやられているのか、そこら辺の点を、もう一度確認したいと思います。","respondent":"金子保育課長","answer":"チャイルドホームの事業は、保育園の物的資源と人的資源を活用しまして、保育園に弟妹を預けているその上のお子さん、それと、今まで認可保育園で、延長・夜間保育をしていたお子さんといったものを対象に、試行として、現在、実施しているものです。","voiceIndex":180,"id":"exchange-083"},{"speaker":"石田委員","kind":"確認","question":"今、試行というお話がありました。これは学童保育クラブの拡大だと勘違いをする人がいても、非常に困ることがあると思いますので、福祉限定で、拡大とは違うんだと、また、吸収の方向性というのはある程度変わっていないということを、再度、確認をしたいと思いますので、答弁をお願いします。","respondent":"辻田児童課長","answer":"学童保育クラブの見直しということについて、今後、検討していかなければならないと考えております。それから、チャイルドホームですけれども、これは別にその部分とは全然特に関係なく、６時以降の児童の預かりということでの試行をしているです。","voiceIndex":182,"id":"exchange-084"},{"speaker":"石田委員","kind":"確認","question":"もう一度だけ確認をします。６時以降の試行というお話でありました。ある程度、限定をして、その部分を残していくんだと、福祉的な活動をしていくということと、私は理解をしておったんですが、そこら辺の限定をして、今、試行をしているところを、再度、ちょっとそこの部分だけ、６時以降のチャイルドホームについてだけ、確認をしておきたい。","respondent":"小沼福祉事業部長","answer":"試行ということで、現在、取り組んです。基本的なところでは、すまいるスクールのほうへ流れる形になるというんでしょうか、最終的には集約されていく。これはもういろいろな意味でのときの流れですから、そういう方向性は変わらない。","voiceIndex":184,"id":"exchange-085"},{"speaker":"石田委員","kind":"質問・要望","question":"高齢者住宅改修アドバイザー派遣事業のほうにいきたいと思います。派遣をした場合、利用者からお金をいただいているのかどうか、ちょっと私も定かでないので、もしいただいているのであれば、金額等を教えていただきたい。区とアドバイザーと委託契約をしていると思いますが、その契約している金額と人数、そこら辺を教えていただきたいのと、また、アドバイザーの業務内容を教えていただければと思います。","respondent":"早津高齢福祉課長","answer":"施工後の対象者の居宅を再訪問し、住宅改修の確認。あるいは、その場で、改修箇所の説明、それから、具体的な使い方についての、利用者へのアドバイス、こういった事柄が業務の内容です。","voiceIndex":186,"id":"exchange-086"},{"speaker":"石田委員","kind":"確認","question":"何年か前にもちょっとお聞きをしたんですが、厚生労働省からもらった業務内容は、結構緩いというか、やさしいというか、助言とか、相談とか、連絡調整、あとは利用者に対する利用した指導をしなさいとか、そういうものですが、品川区の今のお話を聞くと、施工者に対する改修内容についての指導をしなさい、それで調整をしなさい、なおかつ、見積もりと請求書の精査をしなさい、施工後に。","respondent":"早津高齢福祉課長","answer":"したがいまして、直接の契約関係はご本人と施工事業者が行うわけですので、万が一の事故につきましては、基本的には、事業者と本人との関係という中で整理されるものと考えています。","voiceIndex":188,"id":"exchange-087"},{"speaker":"石田委員","kind":"確認","question":"ちゃんとできているかどうか確認にも行くわけですよ。それが業務内容に入っているということは、もし不幸にして何かあった、それに不備があったということであれば、もちろん施工業者が悪いんだけれども、それをちゃんと確認に行った住宅改修アドバイザーがいるわけですよ、そして確認しきれなかった、それに対して責任が及ぶんじゃないですかということを聞いているわけです。それを、もう一度。","respondent":"早津高齢福祉課長","answer":"おそらく、現実にはそうあり得ることではないわけですけれども、万が一のことを考えたときに、言ってみれば素人でも発見できるようなことを、住宅改修アドバイザーが伺って、確認できなかったというようなことがあったとすれば、ちょっと言葉は下手かもしれませんが。","voiceIndex":190,"id":"exchange-088"},{"speaker":"石田委員","kind":"意見","question":"今の話は、行政としてはそういうことがいいのかなと、非常に思って聞いていたんです。残すなら残すで、考え方を持ってやるとか、残さないなら残さないとか、国の制度だと、相談とか助言ぐらいで済んでいるわけですよ、そのぐらいの内容にするとか、そういう条文の整理とか、そういうものはしておくのが、委託者のほうの役目だと思うんですけれども、そこら辺の点を。","respondent":"新美保健高齢事業部長","answer":"ただし、事前のみならず、事後もあわせてそういう形での点検も含めた全体を見ようと、把握した上で生かそうという趣旨ですので、現在の要綱等の強い調子の文言等につきましては、この際、きちんと見直しをしていきたい。趣旨に沿った表現を、もう１回点検をしてまいります。","voiceIndex":192,"id":"exchange-089"},{"speaker":"石田委員","kind":"質問","question":"ぜひ、そういうことでお願いしたいと思います。もちろん、そういうことも精査していると思いますが、ぜひ、そういうところもお願いをしたいと思いまして、私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":194,"id":"exchange-090"},{"speaker":"鶴委員","kind":"質問・要望","question":"私は、その紹介されたことが事実かどうかを確認を求めたのです。ここで問題なのは、公開質問状によると、「貴殿」というのは私のことで、「貴殿がみずから事実を調べることもなく、担当部長の答弁をうのみにして、事実はなかったと断定していることであります」なんておっしゃっているんですけれども、しかしながら、これはあの発言が事実がどうか、事前に調査をお願いして確認を求めたものであります。","respondent":"金子保育課長、田中健康課長","answer":"私どもも、保育計画、指導計画に基づきまして、先ほど申し上げた午睡を実施しています。いわゆる難病、特殊疾病ですけれども、現在、国と都の指定の疾病数ですが、国のほうが４６、東京都の指定するものが２５、合わせて７１疾病です。品川区の現在の申請状況ですが、２，９８１人です。","voiceIndex":197,"id":"exchange-091"},{"speaker":"鶴委員","kind":"質問・要望","question":"その点は、今後の取り組みについてお伺いしておきたいと思うんです。これは平成１２年度から導入されたわけでありますが、平成１４年度、９園増やして、これで実施園が１９園に拡大されたんですか。食はとっても大事だと、衣食住と言うぐらいですから、食は生きる上での基本であるとの認識を、私は持っております。そういうことを含めてお伺いしたつもりなんですが、よろしくお願いをしたいと思います。","respondent":"金子保育課長、田中健康課長","answer":"例えば、５歳児の１月から３月といいますと、もう４月から小学校に通うような時期になりますので、この時期については、それに合わせて、徐々に午睡をなくす方向で実施するとか、そういうような柔軟な対応をしていますので。障害者福祉のしおりという部分でも、この部分につきましての病名について周知といいますか、一覧を、ページを割いているところです。","voiceIndex":200,"id":"exchange-092"},{"speaker":"鶴委員","kind":"質問・要望","question":"保育園の給食の件につきましては、どっちかというといいことづくめという感じですね、これはいいなと。だから、そこをはっきりさせていくことが大事だと思います。どういうふうにやっていくか、その点を聞いておきたいと思います。だからホームページでもいい、小冊子でもいいから、全部一発でわかるような工夫をしていただきたいと思うんですが、いかがでしょうか。ほかの自治体にはありますよ。","respondent":"金子保育課長、田中健康課長","answer":"調理代行の話に関しましては、今年度の事務事業評価におきましても、こういうふうに実施報告を記述しております。「平成１２年度から代行業務方式を実施し、コストを大幅に削減している。内容ですけれども、私どもも、例えばホームページでは、違う病名で指定された場合に、こちらの項目を参照してくださいというように、できるだけ引っ張れるようにはしていますが、かなり治療。","voiceIndex":203,"id":"exchange-093"},{"speaker":"高星委員","kind":"質問・要望","question":"きょう出番がないもので、手短かにひとつ。その方は、当然、病気ですから、医者に行って治療は受けることはできる。したがって、私が聞きたいのは、７１疾病で特定されていない難病と言われている部分について、行政として、品川区の自治体として、品川区のそういった病気を持った方々の立場を理解して、やっぱりどう上に上げていくのかというシステムみたいなものを、ちょっと教えていただきたいと思います。","respondent":"小林品川区保健所保健サービス課長","answer":"治療研究対象疾病としては、１１８疾病ありますので、その中で幾つかまた、再度医療の助成の対象になるものが増えてくるかとは思いますけれども、私たちはそれに対して、療養上の支援をするということで、患者さんの支援をしていきたいと考えております。","voiceIndex":207,"id":"exchange-094"},{"speaker":"飯沼委員","kind":"質問","question":"１０８ページの各種保育事業の助成について、お伺いします。午前中にも、待機児問題が取り上げられたわけですけれども、認可外保育所を活用して、待機児の解消を図るという、都独自の認証制度について、内容について、もう少し詳しく伺いたいと思います。認可保育園との違い、それから品川区として、認証保育所への評価をどのようにしているのか、まずお伺いします。","respondent":"金子保育課長","answer":"待機児解消策に絡みまして、認証保育所のことですけれども、ご案内のとおり、東京都が昨年の５月に発足させた制度で、従前、なかなか大都市におきましては、認可保育所の設置が十分進めない、あるいは、株式会社が、認可保育所につきましても運営できるようになりましたけれども。","voiceIndex":210,"id":"exchange-095"},{"speaker":"飯沼委員","kind":"質問・要望","question":"質問したいことを先にお伺いします。区が助成をしている保育室と、認証保育所との関係を伺いたいんです。補助金が出ていたおかげで、月６万円ぐらいで済んでいたんだけれども、補助金が打ち切られると、月１０万円ぐらいになって、大変入所が困難であるということで、何とかこれをもとに戻してほしいといった声が聞こえます。ぜひ、その点をお考えいただきたいという声が出ているんですが、お願いします。","respondent":"金子保育課長","answer":"委員、ご指摘のとおり、従前、保育室と呼ばれていた認可外保育室、東京都と私どもで助成している部分につきましては、確かに、歴史的、経過的に見まして、認可保育所を補完する役割を、一定程度担ってきたかなと認識しております。","voiceIndex":212,"id":"exchange-096"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど、評価について伺ったところですが、柔軟な施策であるとか、民間参入に移行していることとか、Ｂ型のレベルアップといった面もありますけれども、私は、ここのところ、保育の専門家の中で言われている問題点、２点についてお伺いをしたいと思います。１点目は、児童福祉法に基づかない無認可の施設であるといったこと、このことの意味をどうとらえているのかということ。","respondent":"金子保育課長","answer":"認証を取得させるのに当たっても、審査会を開いておりますし、その以後につきましても、厳しい指導、検査を実施しておりますので、多様な事業主体を認めるというところで、非常に大きな意味があると思いますけれども、だからといって。","voiceIndex":214,"id":"exchange-097"},{"speaker":"飯沼委員","kind":"意見","question":"最低基準に対して厳しく合致しなければというお話があったんですけれども、あくまでも国基準は最低の基準であって、戦後できた基準を何とか改善をしてほしいという動きが、この間、ずっとある。特に国基準のところでは、一人ひとりの子どもにゆとりのある接し方をしてほしい、人格形成に大事な接し方をしてほしいといったところでは、職員の最低基準改正を願っている声があります。当然、できないと思います。","respondent":"金子保育課長","answer":"職員の最低基準について、いろいろご指摘をされていますけれども、認証保育所に関しては、認可保育所の国の最低基準を踏襲しているものですから、先ほど申し上げたとおり、東京都が指導・検査を厳しく実施しておりますので。","voiceIndex":216,"id":"exchange-098"},{"speaker":"飯沼委員","kind":"質問・要望","question":"自由契約のもとでは保育料も大変高くなってしまうという意味では、待機児の解消をしていくのは、やっぱり子育て支援という立場をとったならば、親が願っている公立、私立の認可保育園なので、ぜひ急いでつくっていただきたい、これは皆さんの要望ですので、ぜひ受けとめていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-099"},{"speaker":"北野委員","kind":"提案","question":"私は、１００ページの社会福祉費に関連しましてと、１０８ページの児童福祉費に関連して、お伺いいたします。その方法は、先ほど、午前中も質問がありましたように、サービス提供事業者のパンフレットが必要ではないかということが、私の提案なんです。ちょっとお伺いいたします。","respondent":"高橋介護保険担当課長","answer":"個々に合うサービス等を説明するということができたんですけれども、第２期に向けては、今、委員のおっしゃるとおり、今後の課題としていかなければならないと考えているところです。","voiceIndex":220,"id":"exchange-100"},{"speaker":"北野委員","kind":"質問・要望","question":"介護保険制度推進委員会の設置というところでは、審議事項に、介護保険事業の収支状況も含め、介護サービスの利用状況、介護サービスの基盤整備状況、その他、介護保険事業計画の円滑な推進のために必要な事項ということがありますので、やはり、今後、収支状況が、今の現状に合っているかどうか、事業量も含めて検討していく中では、そういう資料も必要ではないかと思いますので、お伺いします。","respondent":"高橋介護保険担当課長","answer":"介護保険事業計画策定に当たりまして、今年度、平成１５年からの第２期目に向けての検討事項を行っています。","voiceIndex":222,"id":"exchange-101"},{"speaker":"北野委員","kind":"質問","question":"第４回の介護保険制度推進委員会の中で、情報提供するということですけれども、やはり国に中間まとめとして出されるものが、議論されないということはおかしいのではないかと考えています。それから、１１月６日には、どういうことをシンポジウムの中で、区民の方に公開していくのかということについて、もう少しお伺いしたいと思います。","respondent":"高橋介護保険担当課長","answer":"１１月６日に、テーマといたしましては、「品川区の介護保険の１期の現状の部分と、２期目の展望」というテーマにおきまして、パネリストといたしまして、３名の方を呼んで、荏原文化センターで１時３０分から開催する予定になっています。","voiceIndex":224,"id":"exchange-102"},{"speaker":"北野委員","kind":"質問","question":"１１月６日のシンポジウムということですけれども、わかりました。内容については、やはり区民の方にどういう内容で公開するのかということを、介護保険の検証も含めて、第２期に向けての課題も話しながら、介護保険制度の仕組み自体も知っていただくということが目的になるのではないかなと思いますけれども、いかがでしょうか。","respondent":"高橋介護保険担当課長","answer":"今、おっしゃられました、区民の方につきましては、１０月２１日号の広報紙において、ご案内をさせていただきたいと思います。","voiceIndex":226,"id":"exchange-103"},{"speaker":"北野委員","kind":"質問","question":"知らせるとかではなく、その内容がどういうことについてかということをお伺いしたいんです。知らせて、区民の方がいらして、そこで実際に知るということが、やはり必要だと思うんです。そのときに、どういう内容で皆さんに介護保険制度の仕組みを知っていただくか、それも一つの方法だと思いますので、そのことについてお伺いしたいんです。","respondent":"新美保健高齢事業部長","answer":"この時点で、介護保険制度推進委員会で、この間、都合３年間になるわけですが、とりわけ今年度、集中的にご協議いただいております第１期の課題の検証、ここで出されましたご意見等を中心に、１０月２１日、広報紙で区民の方にお知らせする予定です。","voiceIndex":228,"id":"exchange-104"},{"speaker":"北野委員","kind":"質問","question":"支援費制度についてお伺いしたいんですが、既に国のほうから省令が示されて、課長会で介護サービスの金額とかが示されていると思います。今後、予算を編成していく中では、どのような考えを持って、国の最適基準よりもよりよいものを福祉に対してしていくのか、ちょっとお伺いしたいと思います。","respondent":"日下部障害者福祉課長","answer":"ですから、私どもとしましては、そういう形で重度者に配慮をされた内容でありますので、その辺を踏まえた形で、最終的にはおそらく３月になると思いますが、区の基準について定めてまいりたいと考えております。","voiceIndex":230,"id":"exchange-105"},{"speaker":"北野委員","kind":"質問・要望","question":"品川区では、利用者満足度調査というのを、今年も実施されているわけですけれども、先ほども質問に出ましたけれども、認証保育所が増える、そして、夜間保育、延長保育、休日保育、病後児保育、休日保育については、事務事業評価の中ではＡとして、実施園の拡大に向けて検討していくということなんですけれども、やはり、これに対して第三者評価というのが、公立、私立を含めて。","respondent":"金子保育課長","answer":"東京都におきましては、第三者評価を２本立てで考えておりまして、一つは事業者評価、もう一つは利用者の満足度調査ということで、私どもが、昨年度まで２年間実施していましたのは、利用者満足度調査の部分です。今年度は、ちなみに実施していないわけですけれども。","voiceIndex":232,"id":"exchange-106"},{"speaker":"北野委員","kind":"質問","question":"ＩＳＯを取得した東五反田保育園ですけれども、冊子は出されていますけれども、それが１００％他の園に実施されていくとは限りませんけれども、こういうような保育のビジョンを含めたすごくいいことは書かれていると思うんですけれども、権利条約を保障するためにも、この理念を実践するためにも、きちんとした評価を必要として、第三者評価というのは、区独自で項目をつくるとか。","respondent":"金子保育課長","answer":"私どもとしても、今後、これを実施する場合には、特に他区とは違って、さまざまな事業を展開しておりますので、この部分については、いろいろ項目を加えて実施していきたいと考えています。","voiceIndex":234,"id":"exchange-107"},{"speaker":"北野委員","kind":"質問・要望","question":"昨年度実施した調査の結果なんですが、これをいただくには、情報公開ということでしたけれども、やはり、保育園で見られるようにはなっていますけれども、図書館で見られるとか、いろいろな場におきながら、保護者が選択できるということで、機会を広げていっていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-108"},{"speaker":"松澤委員","kind":"質問","question":"保育園関係で、何点か質問したいと思います。初めに、保育園給食における調理業務代行、先ほども質問が出ましたけれども、私も、これは大変にすばらしい事業だと思います。ただ、私が成功、成功と言っても、まちの声が、あるいは理事者の声、あるいはそれに携わっている人たちの声を聞かなくてはいけませんので、その辺の評価、調理代行に対してどのような評価をされているのか、お聞きしたいと思います。","respondent":"金子保育課長","answer":"コスト面に関しましては、先ほど、ご答弁申し上げましたとおり、従来の直営の部分と比べまして、５０％以下で実施していることですので、そのようにご理解いただければと考えております。","voiceIndex":238,"id":"exchange-109"},{"speaker":"松澤委員","kind":"質問・要望","question":"今までは何だったんだろうかという声があります。今もたくさん聞こえてまいりました。今までこれをする前に、なんで状態が違ったのかということをコメントしていただきたい。それと、平成１２年度から、５園、５園、９園と１９園に拡大してきたんですけれども、こんなにいいものでしたら、よし、来年は全部やっちゃおうという形がなぜできないのか。そこも一つ、お願いします。","respondent":"金子保育課長","answer":"それが一番大きいかなと思ってあります。それから、残る１８園ありますが、これについて一挙にできないかというお尋ねかと思います。","voiceIndex":240,"id":"exchange-110"},{"speaker":"松澤委員","kind":"質問・要望","question":"拡大しては、業者のほうが、自分たちの衛生面、あるいはそういうことでサービスが低下しては困るというようなお話、逆に、さらにすばらしいと思いますので、ぜひ進めていただきたいと思います。それとさらに、平成１２年度から調理業務代行を実施して、コストを大幅に削減している、やはりこれだけではだめですね。２点目に移ります。保育園の閉園時間をお教え願いたいと思います。","respondent":"金子保育課長","answer":"それ以降、７時半までを延長保育、それから８時半までの園と１０時までの園、二とおりの夜間保育を実施しております。１０時までの園が、公立では７園、８時半までの園が３園、その他が７時半までとなっております。","voiceIndex":242,"id":"exchange-111"},{"speaker":"松澤委員","kind":"質問","question":"保育園のほうは、平成１２年度から、公私立すべて４４園で延長保育を実施したとなっています。７時半までが延長保育で、８時半、１０時までが夜間保育と言われたんですか。私、予算特別委員会のときにもやりましたけれども、常にこの問題があるものですから、やはり延長保育と夜間保育は、事務事業評価でも分けるべきだと思います。それと、延長保育の考え方を、改めてお伺いします。","respondent":"金子保育課長","answer":"それは、既存の２２時までの園について、かなり子どもが集中してきているという現実がありますので、それを分散するために、各実施園の近くにさらに加えたということを実施しております。今後につきましては、以上の趣旨を踏まえて、政策展開を考えていきたいと考えています。","voiceIndex":244,"id":"exchange-112"},{"speaker":"松澤委員","kind":"質問・要望","question":"お話は、承っておきます。私は、品川区が決して同じだとは思いませんけれども、やはり、そういう意味では、やっぱり隣の区ですから、このことに対して、我々も考えます。本会議の質問でも出ましたよね。そのときの答弁の中で、たしか品川方式で云々という話をされたと思うんですけれども、その品川方式というのは大変あいまいなものですから、品川方式は何ぞやということで、ひとつお答えいただきたい。","respondent":"小沼福祉事業部長","answer":"やはり諸状況等を見まして、先ほど、お話が出ました公設民営の問題ということも、時期が来て、あるいは折が来れば、当然、俎上に上がってくるということで、ご理解いただければと思います。","voiceIndex":246,"id":"exchange-113"},{"speaker":"松澤委員","kind":"意見","question":"わかりました。これも承っておきます。時間があるんで、もう一つと追加すると、何か失敗しそうですけれども、保育園ＰＴＡについて。保育園ＰＴＡというものが、試行期間、モデル実施が過ぎて、また今年も始まりましたよね。それが拡大されてきた。私どもあまり情報が入りませんので、今、何園ぐらいやっているのか、その辺の様子をお聞かせください。","respondent":"金子保育課長","answer":"今年度につきましては、今のところ６園を予定しておりまして、既に発足したところ、これから発足しつつあるところという状態ですので、今年度中には、見込みとして、１４園実施できるかなと考えております。","voiceIndex":248,"id":"exchange-114"},{"speaker":"松澤委員","kind":"質問・要望","question":"モデル実施と８園はもう丸々１年経ちますので、モデル実施した成果というんでしょうか、どういうような形でＰＴＡを立ち上げて、その行事をやって、その結果、保護者、あるいは、園長、職員、その辺の評価のほどを、ちょっとお教えいただきたいと思います。","respondent":"金子保育課長","answer":"既に実施してきた園ですけれども、例えば子育ての悩み事を、懇談会方式でそれぞれ出し合って話し合うとか、あるいは親子そろっていろいろな遊び事を実施していくことによって交流を図るなど、それぞれ各園が工夫して実施しております。","voiceIndex":250,"id":"exchange-115"},{"speaker":"松澤委員","kind":"質問","question":"今まで、保育園のお母さんたちから、「保育園の中で署名活動をさせられたり、政治的な話をされるんで、すごく嫌だ。私は、松澤さんを応援しているのに」なんていう声が随分聞こえたんですけれども、最近は聞こえなくなりました。そういうような意味では、大変よくなっているのかなと思います。ほかに機会がありますので、また改めて質問していきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":252,"id":"exchange-116"},{"speaker":"高木委員","kind":"質問・要望","question":"たった１段の段差なんですが、それだけの落差があるんですから、上っていかなくちゃならない。特に今年の春先にハートビル法の改正ができて、公共性、あるいは一般の建物でも公共性の高い建物は、一切バリアフリーを義務づけをされた法律改正があったものですから、よもや区役所のやったことに、そんなことはなかろうと思っておったんですが、とにかくこの段差がどうしてできなければならなかったか。","respondent":"辻田児童課長","answer":"できましたときに、皆さんに見学していただくということで、ご利用になる方を対象にして、障害者の団体であるとか、民生委員、主任児童委員の方であるとか、見学会を実施しております。","voiceIndex":254,"id":"exchange-117"},{"speaker":"高木委員","kind":"質問・要望","question":"一挙に１６cmということがあるものですから、イメージがちょっと強いのではないかなと思います。障害者だとか、たくさんのいろいろなパンフレットを見てみますと、家庭あんしんセンターって何をするところだろうと思っていたんですが、子育て支援のことをいろいろな要望もあって、詰め込んだと言っては申しわけないんですが、たくさん入れたものですから、建物もふくらんできたんではないかなと。","respondent":"辻田児童課長","answer":"私どものほうとしても、今後、建てる際に、いろいろな形でご意見を参考にしたいと思います。そのような中で、これから段差につきましては、私どものほうも、改善の余地があるかどうか、真剣に検討いたしまして、必要な部分について対応してまいりたいと考えております。","voiceIndex":256,"id":"exchange-118"},{"speaker":"高木委員","kind":"質問・要望","question":"それは皆さん方も、所管がいろいろおかわりになりますから、前がどうだったこうだったということを対象にされると、いかがかどうかわかりませんけれども、そういうことも言っておりますので、全面的に、もう少し配慮のいき届いた、障害者からできるだけ苦情のないような仕事をしていただきたいと考えていますので、強く申し上げて、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":258,"id":"exchange-119"},{"speaker":"上山委員","kind":"質問・要望","question":"私のほうから、１１１ページ生活保護費の関係で、二、三お伺いしたいと思います。私、勉強不足で申しわけないんですが、生活保護のもともとの基本的な考え方を、どういうことでやっているのか、教えていただきたい。それからもう一つ、今、生活保護を受給されている方々で、保護の開始となっている主な理由、要因というんでしょうか、こういうことで、生活保護の開始になっているということ。","respondent":"黒田生活福祉課長","answer":"開始理由ですが、一番基本的なところは、やはり所帯主の傷病ということです。医療費が払えなくてというところから、所帯主が収入が減ったり、ご本人が入院等で生活全体が生活できないというところから保護の開始があります。","voiceIndex":260,"id":"exchange-120"},{"speaker":"上山委員","kind":"質問・要望","question":"資産確認なども含めて調査する場合なんですけれども、いろいろな方がいろいろ訪ねていったりしまして、相談だとかあるかと思うんですけれども、そういう中で、例えば預貯金なども調べなきゃいけないことも当然出てくると思いますし、その他生命保険がどうなっているかとか、あるいはその他いろいろあるかと思うんですが、そこのところを、もう一度ちょっと教えていただけませんでしょうか。","respondent":"黒田生活福祉課長","answer":"ただ、調査に関しましては、申請後でなければ調査できませんので、開始をして以降でないと、生命保険関係とか、預貯金は、すべてこちらでは調査できませんので、開始後ということになります。","voiceIndex":264,"id":"exchange-121"},{"speaker":"上山委員","kind":"質問","question":"今のご答弁で、申請後、調査するということだったかと思うんですが、私も議員になって３年ちょっとなんですが、たまたま生活保護の相談に来られた方と同席したことがあるんです。私の認識が違うなら違うでいいんですが、そこら辺はいかがでしょうか。ちょっとご答弁を、もう一度いただければと思うんですが。","respondent":"黒田生活福祉課長","answer":"というところで、やはり申請をするに当たっては、ご本人に用意していただくものが何もなくては、こちらは受理できませんので、協力を願っています。それ以外の預貯金、ご本人はあくまでも一つの貯金だけはございませんので、皆さん結構お持ちですので、それ以外の調査をするです。","voiceIndex":266,"id":"exchange-122"},{"speaker":"上山委員","kind":"質問","question":"順番の問題を指摘した話なんです。それで、ちょっとお尋ねしたいんですけれども、東京都の福祉局生活福祉部保護課の用例集の中に、少し触れているところがあるんです。協力と言えば協力なのかもしれませんが、そういうことがいかがなものなのかなと私は思うんですが、どうでしょうか。実際上、普通はどういうような形でやっておられるんでしょうか。もう少しわかりやすく教えていただけないかと思うんですが。","respondent":"黒田生活福祉課長","answer":"その意味では、やはり病気につきましても、入院している方、意識がないとか、ほんとうにどうみても話ができない方は当然こちらで職権で開始ということで動きますが、それ以外のお話ができる方は、一応、医療相談の方からご連絡いただいて、こちらが面接に伺うという形で。","voiceIndex":268,"id":"exchange-123"},{"speaker":"上山委員","kind":"質問","question":"私も、働ける方々が働くのは当然だと思います。ただ、順番で言えば、先ほど述べたようなことが現にあるんじゃないですか。そういうことはございませんでしたか。ですから、先ほど述べたような実際の手続上からすると、これはある意味では問題じゃないのかなと、私は思うんです。それは、生活福祉課長が答弁されていたこととも、ある意味では矛盾するように思うんですが、そこら辺はいかがでしょうか。","respondent":"黒田生活福祉課長","answer":"現状を見ながら、まだ余裕がある、一応、稼働年齢等、残っている貯金額がこちらで支給する額を超えている方は受けてございませんので、そういう状況も確認させていただきながら伺っているという状況です。","voiceIndex":270,"id":"exchange-124"},{"speaker":"上山委員","kind":"質問・要望","question":"ただ、私は、順番が少し違うのではないかという話をさせていただいたんです。先ほど、生活福祉課長が答弁されたように、ほんとうに困った方が受けるわけですから、心優しい対応と、そこら辺は、今申し上げたような形で求めたいと思うんです。順番も、先ほど、生活福祉課長が言ったようにやってもらたいと思うんですが、最後にひと言お願いしたいと思います。","respondent":"黒田生活福祉課長","answer":"現在でも、生活保護を受けている方に対しての区民の方のいろいろな苦情があります。そういう意味では、最初の申請時にちゃんとしたお話を伺うということです。","voiceIndex":272,"id":"exchange-125"},{"speaker":"辻委員","kind":"意見","question":"成果報告書の１６ページの保育園園児定数弾力化という説明がされていますが、この表についての見方といいますか、ちょっと説明をお願いしたいと思います。","respondent":"金子保育課長","answer":"保育園園児定数弾力化、いわゆる入園の弾力化についてのお尋ねですが、この表は、私ども、各園の乳幼児、幼児の定数につきましては、０歳児から２歳時、３歳児から５歳児と二分化した区分けをしておりまして、上の段が区立になっておりますが、区立の部分につきましては。","voiceIndex":275,"id":"exchange-126"},{"speaker":"辻委員","kind":"意見","question":"その辺はわかるんですが、数字だけ並べていただいて、０歳児から２歳児が、大変待機児童が多い部分について、プラスという形で、要するに人数を多く預かっていただいている。減少するということについては、いいと思うんです。もう一つは、３歳児から５歳児というのは、逆に、努力しているんだけれども満たないということですよね。この辺の動向については、原因をどのように考えられていられるのか。","respondent":"金子保育課長","answer":"私ども、保育園に関しましては、ご案内のとおり、保育に欠けるというのを基本的な要件ですが、３歳児から５歳児になって、保育園から幼稚園に変わるという方も少なからずおるのかなと考えております。","voiceIndex":277,"id":"exchange-127"},{"speaker":"辻委員","kind":"質問","question":"先ほど、どなたかの答弁の中で、１０月１日現在で２７０人待機児がいるということですが、こうやって考えると、地域差もあるでしょうから、一概には何とも言えないんですが、２７０人と考えると、ほぼ０歳児から２歳児だけで、３歳児から５歳児というのは、割合から言うと、ほとんどいないと考えるのか。どうなんですか、年齢的に、待機児はどういう分布で待っていらっしゃるのか。","respondent":"金子保育課長","answer":"そういう意味では、０歳児から２歳児が２６０人で、ほとんどであるという実態です。","voiceIndex":279,"id":"exchange-128"},{"speaker":"辻委員","kind":"質問","question":"ただ、それは０歳児とか２歳児を対象としてやっていくというのが大きなポイントになっているようですけれども、それが増えてきて、何とか待機児の解消になってもらいたいということが一つ。認証保育所はスタートが新しいですから、まだまだ先の話でしょうけれども、要するに、認証保育所で就学前までずっと預かるような方向なんでしょうか。","respondent":"金子保育課長","answer":"ここがなかなか保護者の希望が多いという実態もありますので、そういうところに関しては、引き続き認証保育所のほうに通われるという選択する方もいらっしゃるかという意味で、これからは、そういう多様な選択が可能なのかなと考えております。","voiceIndex":281,"id":"exchange-129"},{"speaker":"辻委員","kind":"質問・要望","question":"認証保育所というのは、まだまだスタートしたばかりですから、先行きの話かと思うんですけれども、これはぜひ、関係者の間での話をやっていただきたい。その辺のことを。この実態から言うと、例えば、夜間保育に、年間延べが５，２８３人ということで、区立保育園の全体の在籍児童数の延べ９５万４，０００人余りのうちの５，２８３人ですから、０.６％になっている。その辺をちょっと教えていただければ。","respondent":"金子保育課長","answer":"具体的に、細かく統計を取ったデータというのはございませんが、夜間をやっている保育園の実態としては、朝早くから預かって、夜遅くまでというお子さんが非常に増えているというのが実態です。ただ、中には、若干の例ですけれども、お昼ごろ登園される方というケースもあります。","voiceIndex":283,"id":"exchange-130"},{"speaker":"辻委員","kind":"意見","question":"そういうところの実態に合わすときに、ぽつぽつ出てきている２４時間対応の保育園、これは非常に誤解を与える部分が強いわけですね。女性の社会参加があったり、いろいろな形であったときに、保育園というのは、預け放しでずっといるのと、最低８時間なら８時間という時間をもってずれていく。この辺の考え方というのは、どのようにお考えになっておられますか。","respondent":"金子保育課長","answer":"仮に、レアケースでそれを超えている時間のニーズがあった場合には、本年、９月１日に家庭あんしんセンターという施設がオープンしておりますので、こういったところでも対応ができるというのが現在のところですので、そういう意味では。","voiceIndex":285,"id":"exchange-131"},{"speaker":"辻委員","kind":"意見","question":"私は、いきなり２４時間とかいうことではなくて、さまざまな需要に対して、区としてもこういう病後児保育、あるいはそのほか休日とか、要するに子どもの保育をどうしたらいいか、そのためにどうかという観点から、これからさまざまな取り組みが必要かと思うんで、その辺はよろしくご努力をお願いしたいと思います。","respondent":"金子保育課長","answer":"保育園における子育て広場事業の実施という事務事業ですが、これは、特定の２カ所の保育園で、子育て広場ということで、予約による相談を実施しておりまして、一定のスペースを確保して、実施しているわけです。","voiceIndex":287,"id":"exchange-132"},{"speaker":"辻委員","kind":"提案","question":"大人というのは、幼児が約１０万人で、大人が１４万８，０００人ということですから、多分、同じぐらいが、幼児を連れてきたお母さんで、残りは高校生かとかな感じがする。そのためには、先ほどあったけれども、先行きまたご提案させていただきたいと思うんですが、学童保育事業とか、児童センターでやっている事業というものと、単独館での学童保育がいろいろ差がある。","respondent":"辻田児童課長","answer":"そのような中で、児童センターのあり方、それから学童保育のあり方、これは根本的に検討をして、広い視野で今後の施策につなげていくということで、検討委員会などを設置してやっていきたいと考えております。","voiceIndex":289,"id":"exchange-133"},{"speaker":"辻委員","kind":"質問・要望","question":"ぜひ検討をお願いしたいと思います。すまいるスクールがスタートして、今、やってきているわけで、これは教育長のほうも、ぜひ取り組んでいただきたい。その学校のいろいろな取り組みが、また、地域に新しい、進学しようというときの学校選択制の大きなかぎになるということで、ぜひ、区を挙げて取り組んでいただきたいと思います。その点について、ちょっとお考えをお聞かせください。","respondent":"指田教育次長","answer":"すまいるスクールにつきまして、幾つかお話がございました。私どもも、議会のほうのご意向等を十分に踏まえつつ、それと同時に、福祉事業部との連携を図りながら検討してまいります。","voiceIndex":291,"id":"exchange-134"},{"speaker":"辻委員","kind":"意見","question":"最後に、１０月１日はもう過ぎましたけれども、福祉用具の日ということらしいんです。これは先ほど三上委員も取り上げましたけれども、福祉機器をどう使っていくかということについて、区長はじめさまざまな形で、元気だからいいということではなくて、福祉機器にぜひ触れて、社会の中で自立し、やっていくということが大切です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":293,"id":"exchange-135"},{"speaker":"須藤委員","kind":"質問","question":"何点かお願いします。国民健康保険につきましては、収納率が低いというので、努力しているということで、先ほど、田中委員から質問がありまして、お答えいただきました。それから、２２対１という表現で、そうすると国民健康保険連合会の分担金、その辺もむしろ区独自で広報と一緒になっていろいろなＰＲをしていったらいいんじゃないかという感じもするんですけれども、その辺はいかがでしょうか。","respondent":"太田保険年金課長","answer":"１点目の資格証の件ですけれども、昨年の１０月から発行をいたしています。","voiceIndex":295,"id":"exchange-136"},{"speaker":"須藤委員","kind":"質問・要望","question":"その後のフォローを、またよろしくお願いいたします。それから、介護保険のほうで、高齢者と介護保険の認定を受けた方、認定を要請されてきた方が、どの程度の割合で、その中で、認定が１度から５度になった人がどの程度、要支援がどの程度ということが、おわかりになれば、教えていただきたいと思います。","respondent":"早津高齢福祉課長","answer":"認定をされた方が７，２７４人、そのうち１，３３９人が要支援ということで、要介護１が２，０５６人、２が１，２１１人、３が９７８人、４が９５５人、５が７３５人という状態です。","voiceIndex":297,"id":"exchange-137"},{"speaker":"須藤委員","kind":"質問","question":"認定を受けたけど、１から５に入らないという人がどのぐらいいて、要支援がどのぐらいなのかなということがわかればというので。全部受けた人が要介護とか、その辺にはなってこないだろうと思うんですけれども。あるいは、軽度の人は、そのまま日常生活をしていたりというような状況もあろうかと思うので、その辺の割合があれば教えてください。","respondent":"早津高齢福祉課長","answer":"そのうち、実際にサービスを受けている方が４，７５７名ということで、約５００名ほどの方が、認定は受けたけれども、まだサービスを受けていないという方が５００名ほどです。","voiceIndex":299,"id":"exchange-138"},{"speaker":"須藤委員","kind":"質問","question":"その５００名は、病院に入ってという方も含めてと理解してよろしいですね。そのときに、保健高齢事業部長のほうからご答弁いただいたのは、ホテルとか、地方にはそういう制度がだんだんできているので、区内の多様なニーズをもって検討していきたいというようなお話をいただいたんですけれども、そのあたりの方向性はいかがでしょうか。","respondent":"早津高齢福祉課長、新美保健高齢事業部長","answer":"そういった方が５００人ということになります。つまり、自費サービスということになろうかと思いますけれども、検討をしています。","voiceIndex":301,"id":"exchange-139"},{"speaker":"須藤委員","kind":"質問・要望","question":"法人のほうも、自費で入って来るわけですから、ある程度利益率も上がってこようかと思うんで、そういったことも検討していただければと思います。それから、ちょっと細かいところで申しわけないんですけれども、科目の記載の仕方というのが、自治法２３３条で出されてきているんですけれども、科目の記載の仕方というのは決められているんですか。その辺を、ちょっとお知らせいただきたいと思います。","respondent":"市岡企画財政課長","answer":"ただ、全然自由度がないというわけではなくて、特に歳入は、かなり厳格に、どういう歳入をもってどういう仕事をしているかが明確になるように、非常に拘束力が強いんですが、歳出は、ある程度逆に、住民の方にわかりやすい形をとるならば、自由度が認められているです。","voiceIndex":304,"id":"exchange-140"},{"speaker":"須藤委員","kind":"質問","question":"その辺のところは、今言ったように、一つの決まりがあるならば、それで整理していったほうが見やすいと思うんですが、いかがでしょうか。","respondent":"市岡企画財政課長","answer":"十分検討します。","voiceIndex":306,"id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"国民健康保険の関係で、ちょっと伺わせていただきたいと思います。滞納が出ているということで、資格証だとか、短期証の発行とかいう説明が、今、ありましたけれども、滞納がどのぐらいの数あるのか、その理由の主なところを、ちょっとお知らせいただきたい。それと同時に、資格証の発行件数、短期証の発行件数、これも教えてください。","respondent":"太田保険年金課長","answer":"２点目の徴収の関係で、短期証、資格証の関係ですけれども、短期証につきましては約２，７００人です。それから、資格証につきましては、１０月１日現在でカウントしますと、４０世帯です。","voiceIndex":309,"id":"exchange-142"},{"speaker":"南委員","kind":"質問","question":"これらの短期証や資格証を発行することによって、先ほどのご説明では、収納率も上がっていると説明していただいたと思うんですけれども、収納率がどのぐらい上がったのか。これについては何世帯というんでしょうか、どのぐらいの数なのか、そこも教えてください。","respondent":"太田保険年金課長","answer":"ただ、短期証を導入する前と、導入後との同時期の金額で比較しますと、約６，０００万円ほど増えている。それから、資格証につきましては、昨年の段階で、導入時期で４０世帯導入をいたしましたけれども、そのとき１回で、約２００万円ちょっと収入があったです。","voiceIndex":311,"id":"exchange-143"},{"speaker":"南委員","kind":"質問・要望","question":"半年ごとに訪れるというシステムになっているわけですけれども、収納率を上げること自体は否定するものではありませんけれども、しかし、やっぱり世相の状況等々をいろいろ勘案していただいて、厳しい指導ということは、ちょっとどうなんでしょうか、そこら辺は丁寧に、状況をしっかり見て、受診抑制につながらないような姿勢で臨んでいただきたいということを、強く要望しておきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":313,"id":"exchange-144"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1200#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":109527,"voices":314}}]);
